INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-9', '2-handed-kettlebell-swing-9', '2 Handed Kettlebell Swing', '["hamstrings","glutes","quads","abs"]', '["kettlebell"]', 'Stand with your feet slightly wider than shoulder-width, the kettlebell on the floor about 20-30 cm in front of your toes. Hinge at the hips with a slight bend in the knees and a flat back, and grip the handle with both hands. Hike the kettlebell back between your legs, then drive your hips forward explosively so that it swings forward and up to chest or shoulder height (Russian style, not overhead). Your arms stay straight and relaxed, the power comes from the hips. Let the kettlebell swing back down, hinge again as it passes between your legs and go straight into the next rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'deusinvictus', 'https://wger.de/en/exercise/9/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-12', 'seated-hip-adduction-12', 'Seated Hip Adduction', '["glutes"]', '[]', 'Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'flori', 'https://wger.de/en/exercise/12/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-20', 'arnold-shoulder-press-20', 'Arnold Shoulder Press', '["shoulders","triceps"]', '["dumbbell"]', 'Sit on a bench with your back supported. Hold a pair of dumbbells in front of your shoulders, palms facing you and elbows in front of your body. Press the dumbbells overhead while rotating your hands, so that your palms face forward at the top. Stop just before your elbows lock out. Reverse the movement under control: lower the dumbbells and turn your palms back towards you until you are in the starting position again. As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'trzr23', 'https://wger.de/en/exercise/20/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-31', 'axe-hold-31', 'Axe Hold', '[]', '["dumbbell"]', 'Hold a dumbbell in each hand and raise your straight arms out to the sides to shoulder height. Hold this position for as long as you can.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'GrosseHund', 'https://wger.de/en/exercise/31/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-41', 'barbell-ab-rollout-41', 'Barbell Ab Rollout', '[]', '["barbell"]', 'Place a barbell on the floor at your feet. Bending at the waist, grip the barbell with a shoulder with overhand grip. With a slow controlled motion, roll the bar out so that your back is straight. Roll back up raising your hips and butt as you return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/41/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-43', 'barbell-hack-squats-43', 'Barbell Hack Squats', '["quads","hamstrings","glutes"]', '["barbell"]', 'Place a barbell on the floor just behind your heels. Stand with your feet about hip-width apart or closer, keep your chest up and your back straight, and squat down to grip the bar behind you with straight arms. Stand up by extending your knees and hips, sliding the bar up along the back of your legs. Lower it under control to complete the rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'BePieToday', 'https://wger.de/en/exercise/43/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-46', 'barbell-lunges-standing-46', 'Barbell Lunges Standing', '["quads","glutes"]', '["barbell"]', 'Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg. Remember to keep good posture.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mikko Ruohola', 'https://wger.de/en/exercise/46/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-48', 'barbell-reverse-wrist-curl-48', 'Barbell Reverse Wrist Curl', '[]', '["barbell","bench"]', 'Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Curl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'burenl', 'https://wger.de/en/exercise/48/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-50', 'barbell-triceps-extension-50', 'Barbell Triceps Extension', '["triceps","shoulders","chest"]', '["barbell"]', 'Position barbell overhead with narrow overhand grip. Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/50/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-51', 'barbell-wrist-curl-51', 'Barbell Wrist Curl', '["biceps"]', '["barbell","bench"]', 'Sitting on a bench, grab a barbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face. Pause for a moment in the top position, then slowly return the barbell to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'burenl', 'https://wger.de/en/exercise/51/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-56', 'abdominal-stabilization-56', 'Abdominal Stabilization', '["abs"]', '["gym mat"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'andikeller', 'https://wger.de/en/exercise/56/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-57', 'bear-walk-2-57', 'Bear Walk 2', '["shoulders","calves","chest","abs","triceps","glutes","lats","quads"]', '["none (bodyweight exercise)"]', '-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position -Move by stepping with your R palm and L foot, then your L palm and R foot. Basically, walk like a lumbering bear. -Move as fast as you can. Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds) -Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/57/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-71', 'single-leg-extension-71', 'Single Leg Extension', '["quads"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/71/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-73', 'bench-press-73', 'Bench Press', '["chest","shoulders","triceps"]', '["barbell","bench"]', 'Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up. If you train with a high weight it is advisable to have a spotter that can help you up if you can''t lift the weight on your own. With the width of the grip you can also control which part of the chest is trained more: wide grip: outer chest muscles narrow grip: inner chest muscles and triceps', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/73/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-75', 'benchpress-dumbbells-75', 'Benchpress Dumbbells', '["chest","shoulders","triceps"]', '["bench","dumbbell"]', 'Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees. The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve. Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders. Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45-60 degrees relative to your body. Feel the stretch in the lower part of your chest. Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift. Translated with DeepL.com (free version)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/75/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-76', 'bench-press-narrow-grip-76', 'Bench Press Narrow Grip', '["triceps","shoulders","chest"]', '["barbell","bench"]', 'Setup: Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press). Descent: Lower the bar with control to your lower chest. Form: Keep your elbows tucked in tight against your torso-do not let them flare out. Ascent: Press the bar straight back up, squeezing your triceps at the top.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/76/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-79', 'bent-high-pulls-79', 'Bent High Pulls', '[]', '["dumbbell"]', 'Bend over slightly while holding two dumbbells. Pull the dumbbells up to your chest, keeping your elbows as high as you can.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'lakerbeezel', 'https://wger.de/en/exercise/79/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-81', 'bent-over-dumbbell-rows-single-arm-81', 'Bent Over Dumbbell Rows (Single Arm)', '["lats"]', '["bench","dumbbell"]', 'With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sebk', 'https://wger.de/en/exercise/81/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-82', 'bent-over-lateral-raises-82', 'Bent-over Lateral Raises', '[]', '["bench","dumbbell"]', 'Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/82/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-83', 'bent-over-rowing-83', 'Bent Over Rowing', '["lats","shoulders","biceps"]', '["barbell"]', 'Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause. Then inhale and slowly lower the barbell back to the starting position. Repeat for the recommended amount of repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/83/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-84', 'bent-over-rowing-reverse-84', 'Bent Over Rowing Reverse', '["lats","shoulders","biceps"]', '["barbell"]', 'The same as regular rowing, but holding a reversed grip (your palms pointing forwards): Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/84/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-91', 'biceps-curls-with-barbell-91', 'Biceps Curls With Barbell', '["biceps"]', '["barbell"]', 'Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/91/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-92', 'biceps-curls-with-dumbbell-92', 'Biceps Curls With Dumbbell', '["biceps"]', '["dumbbell"]', 'Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/92/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-94', 'biceps-curls-with-sz-bar-94', 'Biceps Curls With SZ-bar', '["biceps"]', '["sz-bar"]', 'Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/94/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-95', 'biceps-curl-with-cable-95', 'Biceps Curl With Cable', '["biceps"]', '["cable machine"]', 'Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/95/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-112', 'body-ups-112', 'Body-Ups', '["triceps","shoulders","abs"]', '["none (bodyweight exercise)"]', 'Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position. Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement. Slowly lower your forearms back to the ground by allowing the elbows to flex. Repeat as needed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/112/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-124', 'braced-squat-124', 'Braced Squat', '["quads","glutes"]', '[]', 'Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can. Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back. Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/124/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-129', 'chest-press-129', 'Chest Press', '["chest"]', '[]', 'Adjust the seat height so that the grips are parallel to your chest. Use your legs to push the foot forward pedal. Bring the handles to the start position. Keep your back in contact with the back pad, press outwards. Press the handles away from your chest and exhale. Allow the handles to come in gently until they reach your chest. Allow the handles to return to your chest as you inhale.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/129/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-132', 'burpees-132', 'Burpees', '[]', '[]', 'Jump, lay down on your chest, do a pushup then jump, repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'er0355', 'https://wger.de/en/exercise/132/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-135', 'butterfly-135', 'Butterfly', '["chest","shoulders"]', '[]', 'Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/135/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-137', 'butterfly-narrow-grip-137', 'Butterfly Narrow Grip', '["chest"]', '[]', 'The movement is the same as with a regular butterfly, only that the grip is narrow: Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/137/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-139', 'butterfly-reverse-139', 'Butterfly Reverse', '["shoulders"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/139/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-142', 'cable-external-rotation-142', 'Cable External Rotation', '["shoulders"]', '["cable machine"]', 'Steps: Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level. Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle. Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position. Repeat for as many reps and sets as desired.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'lauroernesto', 'https://wger.de/en/exercise/142/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-145', 'cable-woodchoppers-145', 'Cable Woodchoppers', '[]', '["cable machine"]', 'Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable. Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'robhoyt', 'https://wger.de/en/exercise/145/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-146', 'calf-press-using-leg-press-machine-146', 'Calf Press Using Leg Press Machine', '["calves"]', '[]', 'Put the balls of your feet on an extended leg press pad. Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position. This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/146/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-148', 'calf-raises-on-hackenschmitt-machine-148', 'Calf Raises on Hackenschmitt Machine', '["calves"]', '[]', 'Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down. With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/148/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-152', 'chin-up-152', 'Chin Up', '["biceps","lats"]', '["pull-up bar"]', 'The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/152/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-158', 'close-grip-lat-pull-down-158', 'Close-grip Lat Pull Down', '["lats"]', '[]', 'Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/158/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-161', 'cross-bench-dumbbell-pullovers-161', 'Cross-Bench Dumbbell Pullovers', '["lats","chest"]', '["dumbbell"]', 'Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'powerade69', 'https://wger.de/en/exercise/161/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-165', 'ball-crunches-165', 'Ball crunches', '["abs"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Konsumopfer', 'https://wger.de/en/exercise/165/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-167', 'crunches-167', 'Crunches', '["abs"]', '["gym mat"]', 'Lay down on your back a soft surface, the feet are on the floor. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/167/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-171', 'incline-crunches-171', 'Incline Crunches', '["abs"]', '["incline bench"]', 'Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/171/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-172', 'crunches-on-machine-172', 'Crunches on Machine', '["abs"]', '[]', 'The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/172/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-173', 'crunches-with-cable-173', 'Crunches With Cable', '["abs"]', '["cable machine"]', 'Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/173/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-174', 'crunches-with-legs-up-174', 'Crunches With Legs Up', '["abs"]', '[]', 'On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'krisbbb', 'https://wger.de/en/exercise/174/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-177', 'cycling-177', 'Cycling', '["hamstrings","glutes","lats","quads"]', '["none (bodyweight exercise)"]', 'Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/177/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-178', 'deadbug-178', 'Deadbug', '["abs"]', '[]', 'Lie on your back, with your hips and knees bent to 90°. Raise both arms toward the ceiling. Pull your lower back to the floor to eliminate the gap. Start by pressing one leg out, and tapping the heel to the floor. "As you extend one leg, exhale as much as you can, keeping your lower back glued to the floor," Dunham says. When you can’t exhale any more, pull your knee back to the starting position. Make this more difficult by holding weight in your hands, or by lowering opposite arm and leg.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Metin', 'https://wger.de/en/exercise/178/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-182', 'deadhang-182', 'Deadhang', '[]', '[]', 'Deadhang performed on an edge either with or without added weight (adujst edge or weight to adjust difficulty)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '2dPREtEZP221u68Akf0JImv5L48', 'https://wger.de/en/exercise/182/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-184', 'deadlifts-184', 'Deadlifts', '["lats","glutes"]', '["barbell"]', 'Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one overhand, one underhand (mixed grip). Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/184/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-185', 'decline-bench-press-barbell-185', 'Decline Bench Press Barbell', '["chest"]', '["barbell","bench"]', 'Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/185/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-186', 'decline-bench-press-dumbbell-186', 'Decline Bench Press Dumbbell', '["chest"]', '["bench","dumbbell"]', 'Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/186/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-189', 'deficit-deadlift-189', 'Deficit Deadlift', '["hamstrings","glutes","lats","abs"]', '["barbell"]', 'Preparation Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip. Execution Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat. Comments Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates. Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'bobbyprince89', 'https://wger.de/en/exercise/189/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-193', 'diagonal-shoulder-press-193', 'Diagonal Shoulder Press', '[]', '["bench"]', 'You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press. In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'oboema', 'https://wger.de/en/exercise/193/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-194', 'dips-194', 'Dips', '["chest","triceps"]', '["none (bodyweight exercise)"]', 'A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/194/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-197', 'dips-between-two-benches-197', 'Dips Between Two Benches', '["triceps"]', '["bench"]', 'Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/197/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-202', 'dumbbell-concentration-curl-202', 'Dumbbell Concentration Curl', '["biceps"]', '["dumbbell"]', 'Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'http://www.exrx.net/WeightExercises/Brachialis/DBC', 'https://wger.de/en/exercise/202/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-203', 'dumbbell-goblet-squat-203', 'Dumbbell Goblet Squat', '["quads"]', '["dumbbell"]', 'Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent. Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat. Keep bodyweight on heels and look ahead or slightly above to keep back straight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ataraxie67', 'https://wger.de/en/exercise/203/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-204', 'dumbbell-incline-curl-204', 'Dumbbell Incline Curl', '["biceps"]', '["dumbbell"]', 'Setup: Set an adjustable bench to an incline of approximately 45 to 60 degrees . Starting Position: Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip). The Curl: Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders. Peak Contraction: Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward. The Descent: Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ExRx', 'https://wger.de/en/exercise/204/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-205', 'dumbbell-lunges-standing-205', 'Dumbbell Lunges Standing', '["quads","glutes"]', '["dumbbell"]', '.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/205/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-206', 'dumbbell-lunges-walking-206', 'Dumbbell Lunges Walking', '["quads","glutes"]', '["dumbbell"]', 'Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides. The Stride: Take a wide step forward with your right leg. The Descent: Lower your hips until both knees are bent at approximately 90-degree angles . The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/206/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-208', 'dumbbells-on-scott-machine-208', 'Dumbbells on Scott Machine', '["biceps"]', '["dumbbell"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/208/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-211', 'dumbbell-triceps-extension-211', 'Dumbbell Triceps Extension', '["triceps","shoulders","chest"]', '["dumbbell"]', 'Position one dumbbell over head with both hands under inner plate (heart shaped grip). With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuninx', 'https://wger.de/en/exercise/211/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-222', 'facepull-222', 'Facepull', '[]', '["cable machine"]', 'Attach a rope to a pulley station set at about chest level. Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base. Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back. As you near your face, externally rotate so your knuckles are facing the ceiling. Hold for one second at the top position and slowly lower.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'abeworld', 'https://wger.de/en/exercise/222/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-235', 'flutter-kicks-235', 'Flutter Kicks', '["abs"]', '[]', '-Laying on the back, lift your straightened legs from the ground at a 45 degree angle. -As your Left foot travels downward and nearly touches the floor, your Right foot should seek to reach a 90 degree angle, or as close to one as possible. -Bring your R foot down until it nearly touches the floor, and bring your L foot upwards. Maintain leg rigidity throughout the exercise. Your head should stay off the ground, supported by tightened upper abdominals. -(L up R down, L down R up, x2) ^v, v^, ^v, v^ = 1 rep -Primarily works the Rectus Abdominus, the hip flexors and the lower back. Secondarily works the Obliques. Emphasis placed on the lower quadrant of the abs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/235/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-237', 'fly-with-cable-237', 'Fly With Cable', '["chest"]', '["cable machine"]', 'cable machine, two steps forward, straight back', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/237/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-238', 'fly-with-dumbbells-238', 'Fly With Dumbbells', '["chest"]', '["dumbbell"]', 'Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/238/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-239', 'fly-with-dumbbells-decline-bench-239', 'Fly With Dumbbells, Decline Bench', '["chest"]', '["bench","dumbbell"]', 'The exercise is the same as with a regular bench: Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/239/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-245', 'skullcrusher-dumbbells-245', 'Skullcrusher Dumbbells', '["triceps"]', '["bench","dumbbell"]', 'Hold the dumbbells and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch arms straight up and then lean dumbbells away from your toes to a 10-20 degree angle. Keep upper arm at this angle throughout exercise. Dumbbell shall not be amed at your head, but away over your head. This will maximise gain from exercise with load on triceps all the time. Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/245/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-246', 'skullcrusher-sz-bar-246', 'Skullcrusher SZ-bar', '["triceps"]', '["bench","sz-bar"]', 'Hold the SZ-bar and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch your arms with the bar and bend them so that the bar is lowered. Just before it touches your forehead, push it up. Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/246/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-254', 'front-raises-with-plates-254', 'Front Raises with Plates', '["shoulders"]', '[]', 'The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit. While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip : The arms will remain in this position throughout the exercise. This will be your starting position. Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position. Repeat for the recommended amount of repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Marius', 'https://wger.de/en/exercise/254/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-256', 'front-raises-256', 'Front Raises', '["shoulders"]', '["barbell","dumbbell"]', 'To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip. The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight. When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury. A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Manu, wikipedia', 'https://wger.de/en/exercise/256/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-257', 'front-squats-257', 'Front Squats', '["glutes","abs"]', '["barbell"]', 'This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/257/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-258', 'front-pull-wide-258', 'Front pull wide', '["lats","shoulders","biceps"]', '["barbell","sz-bar"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/258/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-259', 'front-pull-narrow-259', 'Front Pull narrow', '["lats","biceps"]', '["barbell","sz-bar"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/259/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-260', 'full-sit-outs-260', 'Full Sit Outs', '["glutes","abs"]', '["none (bodyweight exercise)"]', '(A) Get in high plank position on your hands and toes. (B) Shift your weight to your left hand as you turn your body to the right; bend your right leg behind you and extend your right arm up. Return to the center and repeat on the opposite side. Continue, alternating sides. Make it easier: Don’t raise your arm after you bend your leg behind you. Make it harder: Balance with your arm and leg extended for two counts.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'http://www.realsimple.com/health/fitness-exercise/', 'https://wger.de/en/exercise/260/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-265', 'glute-bridge-265', 'Glute Bridge', '["glutes","hamstrings"]', '[]', 'Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tdprice12', 'https://wger.de/en/exercise/265/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-272', 'hammer-curls-272', 'Hammer Curls', '["biceps"]', '["dumbbell"]', 'Start: Hold dumbbells at your sides with palms facing your torso. Curl: Lift the weights toward your shoulders while maintaining the neutral grip (like holding a hammer). Squeeze: Contract the biceps at the top without moving your elbows forward. Lower: Slowly return to the starting position with full control.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/272/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-275', 'hammercurls-on-cable-275', 'Hammercurls on Cable', '["biceps"]', '["cable machine"]', 'Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms. Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/275/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-279', 'hand-grip-279', 'Hand Grip', '[]', '[]', 'A spring-loaded hand grip trainer for building grip strength and the forearm flexors. Position: hold the hand grip firmly in one hand. Squeeze: close it as hard as you can, trying to make the handles touch. Release: hold the contraction for one or two seconds, then open your hand slowly and under control, resisting the spring.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'vince63', 'https://wger.de/en/exercise/279/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-282', 'handstand-pushup-282', 'Handstand Pushup', '["shoulders","triceps"]', '["none (bodyweight exercise)"]', 'The handstand push-up (press-up) - also called the vertical push-up (press-up) or the inverted push-up (press-up) also called commandos- is a type of push-up exercise where the body is positioned in a handstand. For a true handstand, the exercise is performed free-standing, held in the air. To prepare the strength until one has built adequate balance, the feet are often placed against a wall, held by a partner, or secured in some other way from falling. Handstand pushups require significant strength, as well as balance and control if performed free-standing.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/282/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-283', 'hanging-leg-raises-283', 'Hanging Leg Raises', '["abs"]', '["pull-up bar"]', 'Hanging from bar or straps, bring legs up with knees extended or flexed', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'robhoyt', 'https://wger.de/en/exercise/283/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-284', 'hercules-pillars-284', 'Hercules Pillars', '["biceps","triceps","shoulders"]', '["cable machine"]', 'Grab two cables stand in the middle so both have tension and hold', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'GrosseHund', 'https://wger.de/en/exercise/284/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-285', 'high-knee-jumps-285', 'High Knee Jumps', '["hamstrings","calves","quads","abs"]', '[]', 'Start with legs slightly wider than shoulder width Drop into a bodyweight squat As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight. Remain tucked until the apex of your jump. Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints. Collect yourself into the next rep as quickly but under control as possible.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/285/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-289', 'high-pull-289', 'High Pull', '["shoulders","glutes"]', '[]', 'Use a light barbell, perform explosive lift up starting from underneath knee cap level. Lift/raise explosively using hips, at shoulder level. Tempo: 2111', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/289/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-291', 'hindu-squats-291', 'Hindu Squats', '["quads","glutes"]', '[]', 'Start with your feet shoulder width apart and arms slightly behind your back. As you descend towards the floor, raise your heels off the ground, while keeping your back as vertical as possible. Upon attaining the bottom position, touch the hands to the heels. Then stand up ending with the heels on the ground, arms extended in front of the chest then rowing into the start position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Vilhelmo', 'https://wger.de/en/exercise/291/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-292', 'hip-raise-lying-292', 'Hip Raise, Lying', '["glutes","hamstrings"]', '["none (bodyweight exercise)"]', 'Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'James Mackay', 'https://wger.de/en/exercise/292/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-294', 'hip-thrust-294', 'Hip Thrust', '["glutes"]', '["barbell","bench"]', 'The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Bret Contreras', 'https://wger.de/en/exercise/294/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-297', 'hollow-hold-297', 'Hollow Hold', '["abs"]', '["gym mat"]', 'Get on a mat and lie on your back. Contract your abs, stretch your arms and legs and raise them (your head and shoulders are also be raised). Make sure your lower back remains in contact with the mat.', '2026-10-28T22:02:36.153Z', 'CC0', 'Behrooz', 'https://wger.de/en/exercise/297/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-301', 'hyperextensions-301', 'Hyperextensions', '[]', '[]', 'Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/301/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-308', 'incline-dumbbell-fly-308', 'Incline Dumbbell Fly', '["chest"]', '["dumbbell","incline bench"]', 'Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/308/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-310', 'incline-dumbbell-row-310', 'Incline Dumbbell Row', '["lats"]', '["dumbbell","incline bench"]', 'Using a neutral grip, lean into an incline bench. Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position. Retract the shoulder blades and flex the elbows to row the dumbbells to your side. Pause at the top of the motion, and then return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/310/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-312', 'incline-plank-with-alternate-floor-touch-312', 'Incline Plank With Alternate Floor Touch', '["abs"]', '["none (bodyweight exercise)"]', 'Perform the plank with legs elevated, feet on a gymball. Once stabilised, slowly move one foot sideways off the ball, then make it touch the floor, then come back to starting position. Alternate with the other foot. This is a core exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/312/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-314', 'isometric-wipers-314', 'Isometric Wipers', '["chest","abs"]', '["none (bodyweight exercise)"]', 'Assume push-up position, with hands slightly wider than shoulder width. Shift body weight as far as possible to one side, allowing the elbow on that side to flex. Reverse the motion, moving completely over to the other side. Return to the starting position, and repeat for the desired number of repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/314/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-319', 'jogging-319', 'Jogging', '[]', '[]', 'Get your shoes on, go outside and start running at a moderate pace.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Papazit', 'https://wger.de/en/exercise/319/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-320', 'jumping-jacks-320', 'Jumping Jacks', '["quads"]', '[]', 'A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'student1234', 'https://wger.de/en/exercise/320/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-323', 'cable-cross-over-323', 'Cable Cross-over', '["chest","shoulders"]', '["cable machine"]', 'Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/323/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-331', 'kettlebell-swings-331', 'Kettlebell Swings', '["glutes","hamstrings"]', '["kettlebell"]', 'Hold the kettlebell securely in both hands. Keep your back flat throughout the move, avoiding any rounding of the spine.Keeping your knees "soft", hinge your hips backwards, letting the kettlebell swing between your knees. You want to bend from the hips as far as you can without letting your back round forwards . Then, snap your hips forwards quickly and standing up straight, locking your body in an upright posture. The speed you do this will cause your arms and the kettlebell to swing up in front of you. Don''t try to lift the kettlebell with your arms. The snapping forwards of your hips will cause the kettlebell to swing forwards through momentum. Depending on the weight of the kettlebell and the speed of your hip movement, your arms will swing up to about shoulder height. At the top of this swing, let your hips hinge backwards again as the kettlebell swings back down to between your legs and the start of the next repetition.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'J120290,cerin', 'https://wger.de/en/exercise/331/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-341', 'squats-on-multipress-341', 'Squats on Multipress', '["quads","glutes"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/341/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-346', 'landmine-press-346', 'Landmine press', '["shoulders","chest","triceps"]', '["barbell"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Torsten Linnecke', 'https://wger.de/en/exercise/346/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-348', 'lateral-raises-348', 'Lateral Raises', '["shoulders"]', '["dumbbell"]', 'This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/348/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-349', 'lateral-rows-on-cable-one-armed-349', 'Lateral Rows on Cable, One Armed', '["shoulders"]', '["cable machine"]', 'Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/349/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-351', 'lateral-to-front-raises-351', 'Lateral-to-Front Raises', '["shoulders"]', '["dumbbell"]', '-(1) Perform a lateral raise, pausing at the top of the lift (2). -Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise. You will do this by using a Pec Fly motion, maintaining straight arms. (3) -Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4) -Reverse the motion: Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7). THIS IS ONE REP. (1) l front view (2) -l- FV (3) l- side view (4) l SV/FV (5) l- SV (6) -l- FV (7) l FV/SV', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/351/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-354', 'lat-pull-down-leaning-back-354', 'Lat Pull Down (Leaning Back)', '["lats"]', '[]', 'Lean Back, Pull into chest', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'drthurlow', 'https://wger.de/en/exercise/354/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-355', 'lat-pull-down-straight-back-355', 'Lat Pull Down (Straight Back)', '["lats"]', '[]', 'The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'drthurlow', 'https://wger.de/en/exercise/355/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-364', 'leg-curl-364', 'Leg Curl', '["hamstrings","glutes"]', '[]', 'The leg curl, also known as the hamstring curl, is an isolation exercise that targets the hamstring muscles. The exercise involves flexing the lower leg against resistance towards the buttocks. Other exercises that can be used to strengthen the hamstrings are the glute-ham raise and the deadlift.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/364/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-365', 'leg-curls-laying-365', 'Leg Curls (laying)', '["hamstrings"]', '[]', 'Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/365/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-366', 'leg-curls-sitting-366', 'Leg Curls (sitting)', '["hamstrings"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/366/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-367', 'leg-curls-standing-367', 'Leg Curls (standing)', '["hamstrings"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/367/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-369', 'leg-extension-369', 'Leg Extension', '["quads"]', '[]', 'The leg extension is a resistance weight training exercise that targets the quadriceps muscle in the legs. The exercise is done using a machine called the Leg Extension Machine. There are various manufacturers of these machines and each one is slightly different. Most gym and weight rooms will have the machine in their facility. The leg extension is an isolated exercise targeting one specific muscle group, the quadriceps. It should not be considered as a total leg workout, such as the squat or deadlift. The exercise consists of bending the leg at the knee and extending the legs, then lowering them back to the original position.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/369/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-371', 'leg-press-371', 'Leg Press', '["hamstrings","calves","glutes","quads"]', '[]', 'The leg press is a weight training exercise in which the individual pushes a weight or resistance away from them using their legs.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/371/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-373', 'leg-presses-narrow-373', 'Leg Presses (narrow)', '["quads","glutes"]', '[]', 'The exercise is very similar to the wide leg press: Sit on the machine and put your feet on the platform so far apart that you could just put another foot in between them. The feet are parallel and point up. Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/373/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-374', 'leg-presses-wide-374', 'Leg Presses (wide)', '["quads","glutes"]', '[]', 'Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees. Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/374/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-375', 'leg-press-on-hackenschmidt-machine-375', 'Leg Press on Hackenschmidt Machine', '["quads"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/375/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-376', 'leg-raise-376', 'Leg Raise', '["abs"]', '[]', 'The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/376/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-377', 'leg-raises-lying-377', 'Leg Raises, Lying', '["abs"]', '["gym mat"]', 'Lay down on a bench and hold onto the recliner with your hands to keep you stable. Hold your legs straight and lift them till they make an angle of about 45°. Make a short pause of 1 sec. and go slowly down to the initial position. To increase the intensity you can make a longer pause of 7 sec. every 5th time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/377/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-378', 'leg-raises-standing-378', 'Leg Raises, Standing', '["abs"]', '[]', 'Put your forearms on the pads on the leg raise machine, the body is hanging freely. Lift now your legs with a fast movement as high as you can, make a short pause of 1sec at the top, and bring them down again. Make sure that during the exercise your body does not swing, only the legs should move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/378/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-379', 'leverage-machine-chest-press-379', 'Leverage Machine Chest Press', '["chest"]', '[]', 'Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/379/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-380', 'leverage-machine-iso-row-380', 'Leverage Machine Iso Row', '["lats"]', '[]', 'Adjust seat height so that the handles are at the bottom of your pectorals or just below.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/380/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-382', 'l-hold-382', 'L Hold', '[]', '["none (bodyweight exercise)"]', 'Hold the L position for as long as possible', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'bizyguy', 'https://wger.de/en/exercise/382/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-386', 'diamond-push-ups-386', 'Diamond push ups', '["chest","triceps"]', '["none (bodyweight exercise)"]', 'Start: Get into a plank. Place hands close together under your chest so thumbs and index fingers form a diamond shape. Lower: Bend your elbows to lower your chest toward your hands. Keep your body straight. Push: Push back up until arms are fully extended. New note Keep elbows close to your body and core tight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'notdefine', 'https://wger.de/en/exercise/386/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-394', 'long-pulley-low-row-394', 'Long-Pulley (low Row)', '["lats","biceps"]', '["cable machine"]', 'Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/394/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-395', 'long-pulley-narrow-395', 'Long-Pulley, Narrow', '["lats","biceps"]', '["cable machine"]', 'The exercise is the same as the regular long pulley, but with a narrow grip: Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/395/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-397', 'low-box-squat-wide-stance-397', 'Low Box Squat - Wide Stance', '["glutes","quads"]', '["barbell"]', 'Unrack the bar and set your stance wide, beyond your hips. Push your hips back and sit down to a box that takes you below parallel. Sit completely down, do not touch and go. Then explosively stand up. Stay tight in your upper back and torso throughout the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'taylorbarbell', 'https://wger.de/en/exercise/397/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-406', 'lying-rotator-cuff-exercise-406', 'Lying Rotator Cuff Exercise', '[]', '["dumbbell"]', 'This is an excercise for problems with the rotator cuff. Primary Infraspinatus, secondary Teres Minor. Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Trix', 'https://wger.de/en/exercise/406/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-418', 'military-press-mit-sz-bar-418', 'Military Press mit SZ-Bar', '["shoulders","triceps"]', '["sz-bar"]', 'On an SZ-bar grip your hands on the outside of each bend and stand with your arms straight down, palms facing your legs. Pull the bar (bending your arms at the elbow) to your chest, and the push the bar above your head (arms as straight as possible). Return the bar to your chest by dropping your arms at the elbows. Return the bar to it''s origional position (stand with your arms straight down, palms facing your legs.)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'mbozi1', 'https://wger.de/en/exercise/418/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-423', 'muscle-up-423', 'Muscle up', '["biceps","lats","shoulders","triceps"]', '["pull-up bar"]', 'The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight. To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated. As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'arson', 'https://wger.de/en/exercise/423/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-427', 'negative-crunches-427', 'Negative Crunches', '["abs"]', '[]', 'Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don''t let your head move during the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/427/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-439', 'overhand-cable-curl-439', 'Overhand Cable Curl', '["biceps"]', '["cable machine"]', 'Hands at shoulder height, curl arms in toward head, then back out.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'ThisGirl0819', 'https://wger.de/en/exercise/439/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-441', 'overhead-squat-441', 'Overhead Squat', '["glutes","quads","shoulders","hamstrings"]', '[]', 'The barbell is held overhead in a wide-arm snatch grip; however, it is also possible to use a closer grip if balance allows.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'geraldbaeck', 'https://wger.de/en/exercise/441/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-445', 'pause-bench-445', 'Pause Bench', '["chest","triceps"]', '["barbell","bench"]', 'Lower the bar to your chest and pause (but do not rest) there for 2 seconds. Press back up. use the same weight you would on bench press, but perform only single reps. Total the number of reps you did in one set of bench press (if you did 3 sets of 8 do 8 sinlge pause bench reps.', '2026-10-28T22:02:36.153Z', 'CC0', 'Mens Fitness', 'https://wger.de/en/exercise/445/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-448', 'pendelay-rows-448', 'Pendelay Rows', '["lats","biceps","triceps"]', '["barbell"]', 'Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Nallitnas', 'https://wger.de/en/exercise/448/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-454', 'pike-push-ups-454', 'Pike Push Ups', '["chest","triceps"]', '["none (bodyweight exercise)"]', 'Push Up performed from a pike position (optional to have feet elevated).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Nash', 'https://wger.de/en/exercise/454/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-456', 'pistol-squat-456', 'Pistol Squat', '["hamstrings","glutes","shoulders","biceps"]', '[]', 'Stand with feet hip-width apart, toes pointed forward, and chest tall. Extend your leg straight out; extend both arms in front of you, at shoulder level. Brace your core and look straight ahead. Slowly squat down. (optional) pause at the bottom. Keep your (free) leg and arms extended for the whole duration.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'minifigmaster125', 'https://wger.de/en/exercise/456/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-458', 'plank-458', 'Plank', '["abs","biceps","quads","triceps"]', '["none (bodyweight exercise)"]', 'Get into a position on the floor supporting your weight on your forearms and toes. Arms are bent and directly below the shoulder. Keep your body straight at all times and hold this position as long as possible. To increase difficulty an arm or leg can be raised while performing this exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'YYCfit / BFad07', 'https://wger.de/en/exercise/458/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-465', 'preacher-curls-465', 'Preacher Curls', '[]', '["sz-bar"]', 'Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'cgoob883', 'https://wger.de/en/exercise/465/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-468', 'prone-scapular-retraction-arms-at-side-468', 'Prone Scapular Retraction - Arms at Side', '[]', '[]', 'Lying on stomach with head on towel. Stretch arms straight out to your sides. Slowly lift your arms, pulling your shoulderblades together, hold for 3 seconds.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'donaddon', 'https://wger.de/en/exercise/468/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-475', 'pull-ups-475', 'Pull-ups', '["lats","shoulders","biceps"]', '["pull-up bar"]', 'Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/475/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-477', 'pull-ups-on-machine-477', 'Pull Ups on Machine', '["lats","shoulders","biceps"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/477/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-478', 'push-press-478', 'Push Press', '["glutes"]', '[]', 'Clean your dumbbells onto your shoulders, palms facing in. Take a breath and brace your core. (picture 1)Dip at the knees and use your legs to help (picture 2) press your dumbbells overhead. Lower under control with a slow tempo to your shoulders and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/478/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-484', 'rack-deadlift-484', 'Rack Deadlift', '["glutes","biceps"]', '[]', 'Deadlift to be done using a Smith machine or a free rack. Bar or barbell hould be just right under the knee cap level. Lift using the glutes and through the heels, then come back to starting postion with a control movement of 2 seconds. This exercise targets mainly the lower back and glutes.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/484/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-487', 'rear-delt-raises-487', 'Rear Delt Raises', '[]', '["dumbbell"]', 'Seated on a bench with the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'YYCfit', 'https://wger.de/en/exercise/487/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-490', 'renegade-row-490', 'Renegade Row', '["lats"]', '["dumbbell"]', 'Get into pushup position gripping some dumbbells. Perform one pushup, then drive your left elbo up, bringing the dumbell up to your body. Return the dumbell to starting position. Perform another pushup and then row with the other arm to complete one rep.', '2026-10-28T22:02:36.153Z', 'CC0', 'fletchgraham', 'https://wger.de/en/exercise/490/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-493', 'reverse-bar-curl-493', 'Reverse Bar Curl', '["biceps"]', '["sz-bar"]', 'Hold bar with reverse (or "overhand") grip, palms facing the floor.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/493/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-495', 'reverse-curl-495', 'Reverse Curl', '["biceps"]', '["barbell","dumbbell"]', 'The reverse-grip barbell curl is a variation on the biceps curl where the palms face downward. The switch from an underhand to an overhand grip brings the forearm and brachialis muscles more into the exercise.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/495/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-498', 'reverse-grip-bench-press-498', 'Reverse Grip Bench Press', '["chest","triceps","shoulders"]', '["barbell","bench"]', 'Upper chest focuses exercise that also works triceps', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'bl0sh', 'https://wger.de/en/exercise/498/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-500', 'reverse-plank-500', 'Reverse Plank', '[]', '["none (bodyweight exercise)"]', 'Plank with stomach towards ceiling', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'spacetowaste', 'https://wger.de/en/exercise/500/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-501', 'ring-dips-501', 'Ring Dips', '["triceps"]', '[]', 'Dips peformed on gymnastic rings.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Nash', 'https://wger.de/en/exercise/501/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-505', 'roman-chair-crunch-505', 'Roman Chair Crunch', '["abs"]', '[]', 'Crunches on roman chair. Keep your torso straight, abs tight, and don''t come up all the way vertical or lie flat to keep constant tension on your abs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'MaddieBeasley', 'https://wger.de/en/exercise/505/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-507', 'romanian-deadlift-507', 'Romanian Deadlift', '["hamstrings","glutes"]', '["barbell"]', 'DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'pjwirth', 'https://wger.de/en/exercise/507/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-508', 'row-508', 'Row', '["lats","quads"]', '["barbell","dumbbell","pull-up bar"]', 'In strength training, rowing (or a row, usually preceded by a qualifying adjective - for instance a seated row) is an exercise where the purpose is to strengthen the muscles that draw the rower''s arms toward the body (latissimus dorsi) as well as those that retract the scapulae (trapezius and rhomboids) and those that support the spine (erector spinae). When done on a rowing machine, rowing also exercises muscles that extend and support the legs (quadriceps and thigh muscles). In all cases, the abdominal and lower back muscles must be used in order to support the body and prevent back injury.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/508/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-510', 'rowing-lying-on-bench-510', 'Rowing, Lying on Bench', '["lats"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/510/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-512', 'rowing-seated-narrow-grip-512', 'Rowing seated, narrow grip', '["lats"]', '[]', 'Tighten muscles Controlled movement Slow movement Keep upper body upright Do not lean back Pull toward chest', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/512/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-513', 'rowing-t-bar-513', 'Rowing, T-bar', '["lats","shoulders","biceps"]', '[]', 'The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here. Grab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/513/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-516', 'front-wood-chop-516', 'Front Wood Chop', '[]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Konsumopfer', 'https://wger.de/en/exercise/516/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-527', 'run-527', 'Run', '[]', '["none (bodyweight exercise)"]', 'Running or jogging outside in a park, on the tracks,...', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'BeLikeWater', 'https://wger.de/en/exercise/527/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-529', 'run-interval-training-529', 'Run - Interval Training', '[]', '["none (bodyweight exercise)"]', 'Run and do some interval trainings such as hill repat, fartlek,..', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'BeLikeWater', 'https://wger.de/en/exercise/529/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-530', 'run-treadmill-530', 'Run - Treadmill', '[]', '[]', 'Run on a treadmill', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'foguinho.peruca', 'https://wger.de/en/exercise/530/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-537', 'incline-bench-press-dumbbell-537', 'Incline Bench Press - Dumbbell', '["chest","shoulders","triceps"]', '["dumbbell","incline bench"]', 'This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso. Bench Adjustment and Preparation: Set the bench to an incline of between 30 and 45 degrees (an incline greater than 45° will place too much strain on the shoulders and reduce the stimulus to the chest). Sit down with a dumbbell on each thigh. Starting position: Lean back, resting your back against the bench, while using your knees one after the other to push the dumbbells upward to shoulder height. Anatomical Stabilization: Plant your feet firmly on the floor. Retract your scapulas (bring your shoulder blades together and press them into the bench) to protect your shoulders and stabilize the load. Eccentric Phase (Lowering): Lower the dumbbells slowly and in a controlled manner toward the upper part of your chest. Your elbows should not splay out to the sides (90°); maintain a safe angle of about 45 to 60 degrees relative to your torso. Concentric Phase (Lift): Push the dumbbells vertically upward as you exhale. Follow a slightly converging path (without letting them touch at the top). Stop the movement just before locking out your elbows to maintain muscle tension in the upper pectoral.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/537/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-538', 'incline-bench-press-barbell-538', 'Incline Bench Press - Barbell', '["chest","shoulders","triceps"]', '["barbell","incline bench"]', 'To do slowly, tempo is 4010', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/538/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-539', 'incline-bench-press-mp-539', 'Incline Bench Press - MP', '["chest","shoulders","triceps"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/539/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-543', 'shoulder-press-on-machine-543', 'Shoulder Press, on Machine', '["shoulders","triceps"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/543/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-545', 'scissors-545', 'Scissors', '["abs"]', '[]', 'Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'vkylamba', 'https://wger.de/en/exercise/545/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-549', 'seated-triceps-press-549', 'Seated Triceps Press', '["triceps"]', '["bench","dumbbell"]', 'Sit down on a back (better with back support). Take a dumbbell firmly with both hands and hold it with extended arms over your head. With your palms facing upward and holding the weight of the dumbbell, slowly lower the weight behind your head.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'richmr2174@gmail.com', 'https://wger.de/en/exercise/549/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-556', 'side-bends-on-machine-556', 'Side Bends on Machine', '["abs"]', '["dumbbell"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'klabautermann', 'https://wger.de/en/exercise/556/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-562', 'shotgun-row-562', 'Shotgun Row', '["lats"]', '["cable machine"]', 'Attach a single handle to a low cable. After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position. Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go. After a brief pause, return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/562/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-566', 'shoulder-press-barbell-566', 'Shoulder Press, Barbell', '["shoulders"]', '["barbell"]', 'Sit on a bench, the back rest should be almost vertical. Take a barbell with a shoulder wide grip and bring it up to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/566/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-567', 'shoulder-press-dumbbells-567', 'Shoulder Press, Dumbbells', '["shoulders"]', '["dumbbell"]', 'Sit on a bench, the back rest should be almost vertical. Take two dumbbells and bring them up to shoulder height, the palms and the elbows point during the whole exercise to the front. Press the weights up, at the highest point they come very near but don''t touch. Go slowly down and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/567/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-569', 'shoulder-press-on-multi-press-569', 'Shoulder Press, on Multi Press', '["shoulders"]', '[]', 'The exercise is basically the same as with a free barbell: Sit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/569/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-570', 'shoulder-shrug-570', 'Shoulder Shrug', '[]', '["none (bodyweight exercise)"]', 'The shoulder shrug (usually called simply the shrug) is an exercise in weight training used to develop the upper trapezius muscle. The lifter stands erect, hands about shoulder width apart, and raises the shoulders as high as possible, and then lowers them, while not bending the elbows, or moving the body at all. The lifter may not have as large a range of motion as in a normal shrug done for active flexibility. It is usually considered good form if the slope of the shoulders is horizontal in the elevated position.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/570/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-571', 'shrugs-barbells-571', 'Shrugs, Barbells', '["shoulders"]', '["barbell"]', 'Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position. When training with a higher weight, make sure that you still do the whole movement!', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/571/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-572', 'shrugs-dumbbells-572', 'Shrugs, Dumbbells', '["shoulders"]', '["dumbbell"]', 'Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position. When training with a higher weight, make sure that you still do the whole movement!', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/572/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-575', 'shrugs-on-multipress-575', 'Shrugs on Multipress', '["shoulders","triceps"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/575/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-576', 'side-crunch-576', 'Side Crunch', '["abs"]', '["gym mat"]', 'Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'kwrindy', 'https://wger.de/en/exercise/576/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-577', 'side-dumbbell-trunk-flexion-577', 'Side Dumbbell Trunk Flexion', '["abs"]', '["dumbbell"]', 'AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. Make slow and controlled torso side flexions till you reach the angle of approximately 45°.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'GiglioRosso', 'https://wger.de/en/exercise/577/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-578', 'side-lying-external-rotation-578', 'Side-lying External Rotation', '[]', '[]', 'With a weight in one hand, lie on your side opposite the weight. Keep your knees slightly bent. Hold your elbow against your side, and extend your upper arm straight ahead of you. While continuing to hold your elbow against your side, rotate your upper arm 90 degrees upwards. It is helpful to place a towel under your armpit to help with the form on this exercise. Placing a support under your head for the duration of the exercise is also a good idea.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/578/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-580', 'side-plank-580', 'Side Plank', '["abs"]', '["none (bodyweight exercise)"]', 'Works your obliques and helps stabilize your spine. Lie on your side and support your body between your forearm and knee to your feet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'http://www.bodybuilding.com/', 'https://wger.de/en/exercise/580/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-583', 'side-to-side-push-ups-583', 'Side to Side Push Ups', '["shoulders","chest","triceps"]', '[]', '-start in push up position -lean the body weight to the right side, and complete a push up with the chest over the right hand -come back to the centered position -on rep 2, lean to the left side', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/583/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-584', 'single-arm-preacher-curl-584', 'Single-arm Preacher Curl', '["biceps"]', '["dumbbell"]', 'Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm''s elbow.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/584/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-590', 'sitting-calf-raises-590', 'Sitting Calf Raises', '["calves"]', '[]', 'Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/590/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-591', 'sit-ups-591', 'Sit-ups', '["abs"]', '[]', 'Sit on a mat, your calves are resting on a bench, the knees make a right angle. Hold your hands behind your neck. Go now up with a rolling movement of your back, you should feel how the individual vertebrae lose contact with the mat. At the highest point, contract your abs as much as you can and hold there for 2 sec. Go now down, unrolling your back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/591/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-595', 'skipping-standard-595', 'Skipping - Standard', '["calves"]', '[]', 'Do a single, double footed jump for each swing of the rope. Work on a smooth, rhythmical movement, bouncing lightly on the balls of your feet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Cerin', 'https://wger.de/en/exercise/595/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-598', 'smith-machine-close-grip-bench-press-598', 'Smith Machine Close-grip Bench Press', '["triceps","chest"]', '[]', 'Perform a standard bench press on the smith machine, but have your hands on the bar about shoulder width apart, and keep your elbows close to your body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/598/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-599', 'snatch-599', 'Snatch', '["shoulders"]', '["barbell"]', 'Stand with your feet at hip width and your shins against the bar. Grasp the bar at double shoulder width and, keeping your lower back flat, drive your heels into the floor to begin lifting the bar. When it''s above your knees, explosively extend your hips and shrug your shoulders. Let the momentum carry the weight overhead.', '2026-10-28T22:02:36.153Z', 'CC0', 'Mens Fitness', 'https://wger.de/en/exercise/599/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-604', 'speed-deadlift-604', 'Speed Deadlift', '["hamstrings","glutes","quads"]', '[]', 'Deadlift with short (less than one 1min) rest between sets.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MrSteele', 'https://wger.de/en/exercise/604/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-607', 'splinter-sit-ups-607', 'Splinter Sit-ups', '[]', '[]', 'Lie on your back with your legs straight and arms at your sides, keeping your elbows bent at 90 degrees. As you sit up, twist your upper body to the right and bring your left knee toward your right elbow while you swing your left arm back. Lower your body to the starting position, and repeat to your right. That''s 1 rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'djblitzd', 'https://wger.de/en/exercise/607/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-614', 'squat-jumps-614', 'Squat Jumps', '["quads"]', '[]', 'Jump wide, then close', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'OGhTebfCxhexZXuf35mUxV9C--A', 'https://wger.de/en/exercise/614/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-615', 'squats-615', 'Squats', '["quads","glutes"]', '["barbell"]', 'Place a barbell in a rack just below shoulder-height. Dip under the bar to put it behind the neck across the top of the back, and grip the bar with the hands wider than shoulder-width apart. Lift the chest up and squeeze the shoulder blades together to keep the straight back throughout the entire movement. Stand up to bring the bar off the rack and step backwards, then place the feet so that they are a little wider than shoulder-width apart. Sit back into hips and keep the back straight and the chest up, squatting down so the hips are below the knees. From the bottom of the squat, press feet into the ground and push hips forward to return to the top of the standing position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/615/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-616', 'squat-thrust-616', 'Squat Thrust', '["glutes","quads","abs"]', '["none (bodyweight exercise)"]', 'The burpee, or squat thrust, is a full body exercise used in strength training and as an aerobic exercise. The basic movement is performed in four steps and known as a four-count burpee: Begin in a standing position. Move into a squat position with your hands on the ground. (count 1) Kick your feet back into a plank position, while keeping your arms extended. (count 2) Immediately return your feet into squat position. (count 3) Stand up from the squat position (count 4)', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/616/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-621', 'standing-bicep-curl-621', 'Standing Bicep Curl', '["biceps"]', '["dumbbell"]', 'Stand holding dumbbells at shoulder width apart. Face forearm upward and keep upper arm still while raising each dumbbell up to your shoulder.', '2026-10-28T22:02:36.153Z', 'CC0', 'BFad07', 'https://wger.de/en/exercise/621/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-622', 'standing-calf-raises-622', 'Standing Calf Raises', '["calves"]', '[]', 'Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don''t make a hollow back and don''t bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/622/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-623', 'standing-rope-forearm-623', 'Standing Rope Forearm', '[]', '[]', 'Grab a wrist roller tool with both hands while standing with your feet about shoulder width apart. If your gym does not have a wrist roller tool, you can easily put one together. All you need is a 5 or 10 pound weight plate, a strong thin rope about 3 feet long and a 6-8 inch stick or bar. Securely fasten the rope to the middle of the bar/stick and tie the other end of the rope to the weight plate. To begin this exercise, grab the bar/stick with both hands using an overhand grip. Extend both arms straight out in front of you, parallel to the floor. Next, roll the weight up from the floor by rapidly twisting the bar/stick with your hands and wrists. Once the weight reaches the top, slowly lower the plate back to the floor by reversing the motion of your hands and wrists. Repeat (if you can!).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'pwiltrout', 'https://wger.de/en/exercise/623/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-624', 'stationary-bike-624', 'Stationary Bike', '[]', '[]', 'Ride a Stationary Bike with various tensions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'intelman', 'https://wger.de/en/exercise/624/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-627', 'stiff-legged-deadlifts-627', 'Stiff-legged Deadlifts', '["hamstrings","glutes"]', '["barbell"]', 'Keep legs straight Keep back straight', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/627/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-628', 'straight-arm-pull-down-bar-attachment-628', 'Straight-arm Pull Down (bar Attachment)', '["lats","triceps"]', '["cable machine"]', 'Use the straight bar attachment on a high pulley. Grasp the two ends of the bar with your palms facing downward and your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/628/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-629', 'straight-arm-pull-down-rope-attachment-629', 'Straight-arm Pull Down (rope Attachment)', '["lats","triceps"]', '["cable machine"]', 'Use the rope attachment on a high pulley. Grasp the two ends of the rope with your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/629/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-630', 'sumo-deadlift-630', 'Sumo Deadlift', '["hamstrings","glutes","quads"]', '[]', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees. As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together. Return the weight to the ground by bending at the hips and controlling the weight on the way down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'magdy', 'https://wger.de/en/exercise/630/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-632', 'sumo-squats-632', 'Sumo Squats', '["glutes","quads"]', '["none (bodyweight exercise)"]', 'Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder. While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting). Lower yourself until your quadriceps and hamstrings are parallel to the floor. Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sophialj', 'https://wger.de/en/exercise/632/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-636', 'superman-636', 'Superman', '["glutes","lats"]', '["gym mat"]', 'Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and legs at the same time, as if you were flying, and contract the lower back. Make sure that you are breathing and, depending on your fitness level, hold the movement for at least two to five seconds per repetition.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'baldurmen', 'https://wger.de/en/exercise/636/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-650', 'thruster-650', 'Thruster', '["shoulders"]', '["barbell"]', 'Start by doing a front squat At the top position, push the bar above your head (similar to a press) Lower the bar to the shoulders', '2026-10-28T22:02:36.153Z', 'CC0', 'BeLikeWater', 'https://wger.de/en/exercise/650/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-655', 'tricep-dumbbell-kickback-655', 'Tricep Dumbbell Kickback', '["triceps"]', '["dumbbell"]', 'Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position. Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm. After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position. Repeat the movement for the prescribed amount of repetitions. Variations: This exercise can be executed also one arm at a time much like the one arm rows are performed. Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'http://www.bodybuilding.com/', 'https://wger.de/en/exercise/655/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-659', 'triceps-extensions-on-cable-659', 'Triceps Extensions on Cable', '["triceps"]', '["cable machine"]', 'Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/659/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-660', 'triceps-extensions-on-cable-with-bar-660', 'Triceps Extensions on Cable With Bar', '["triceps"]', '["cable machine"]', 'Grab the bar, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Without pause go back to the initial position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/660/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-661', 'triceps-on-machine-661', 'Triceps on Machine', '["triceps"]', '[]', 'Sit down and hold the bar firmly with your hands. Now press the weight upwards (don''t fully extend your arms) and lower it slowly again. As with other triceps exercises, it''s important not to move your upper arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/661/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-672', 'trunk-rotation-with-cable-672', 'Trunk Rotation With Cable', '["lats"]', '["cable machine"]', 'Seated trunk rotation with cable', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Robertcoop', 'https://wger.de/en/exercise/672/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-674', 'rowing-with-trx-band-674', 'Rowing with TRX band', '["lats","biceps"]', '["none (bodyweight exercise)"]', 'Rowing with resistance bands - Bodyweight Exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Skadi', 'https://wger.de/en/exercise/674/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-675', 'turkish-get-up-675', 'Turkish Get-Up', '["shoulders","glutes"]', '["dumbbell"]', 'Starting on back, move to the standing position with dumbbell in one hand. Switch hands between reps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'dookie1481', 'https://wger.de/en/exercise/675/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-683', 'power-clean-683', 'Power Clean', '["chest"]', '["barbell"]', 'Olympic weight lifting', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/683/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-684', 'underhand-lat-pull-down-684', 'Underhand Lat Pull Down', '["lats","biceps"]', '[]', 'Grip the pull-down bar with your palms facing you and your hands closer than shoulder-width apart. Lean back slightly and keep your back straight. Pull the bar down towards your chest, pulling your shoulders back slightly at the end of the motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/684/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-687', 'overhead-press-687', 'Overhead Press', '["shoulders"]', '["barbell"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Vazco', 'https://wger.de/en/exercise/687/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-688', 'upper-external-oblique-688', 'Upper External Oblique', '[]', '["pull-up bar"]', 'Exercise for upper external oblique muscles', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'http://www.carinatum.com/', 'https://wger.de/en/exercise/688/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-691', 'upright-row-on-multi-press-691', 'Upright Row, on Multi Press', '["shoulders","biceps"]', '[]', 'The movements are basically the same as with an SZ-bar, but you use the bar on the multi press: Stand straight, your feet are shoulder-width apart. Hold the bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/691/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-693', 'upright-row-sz-bar-693', 'Upright Row, SZ-bar', '["shoulders","biceps"]', '["sz-bar"]', 'Stand straight, your feet are shoulder-width apart. Hold the SZ-bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/693/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-694', 'upright-row-w-dumbbells-694', 'Upright Row w/ Dumbbells', '["shoulders","biceps"]', '["dumbbell"]', 'Hold a dumbbell in each hand in front of your body. Keep your palms towards your body. Lift you hands straight up until your hands are under your chin, then lower them. Repeat the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'koreyhinton', 'https://wger.de/en/exercise/694/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-695', 'v-bar-pulldown-695', 'V-Bar Pulldown', '["lats","biceps"]', '["cable machine"]', 'Pulldowns using close grip v-bar.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/695/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-702', 'calf-raises-one-legged-702', 'Calf raises, one legged', '["calves"]', '[]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'McMarcel13', 'https://wger.de/en/exercise/702/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-711', 'wall-handstand-711', 'Wall Handstand', '[]', '["none (bodyweight exercise)"]', 'Handstand against a wall for support (chest facing wall).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Nash', 'https://wger.de/en/exercise/711/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-713', 'wall-pushup-713', 'Wall Pushup', '["shoulders","chest","triceps","glutes","abs"]', '["none (bodyweight exercise)"]', 'Pushup against a wall', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Dexter', 'https://wger.de/en/exercise/713/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-716', 'wall-slides-716', 'Wall Slides', '["biceps","hamstrings","chest","triceps"]', '["none (bodyweight exercise)"]', 'Stand with heels, shoulders, back of head, and hips touching the wall. Start with biceps straight out and elbows at a 90 degree angle. Straighten the arms while remaining againstthe wall without arching the back off of the wall, mimicking a shoulder press movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Whythebigpaws', 'https://wger.de/en/exercise/716/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-718', 'wall-squat-718', 'Wall Squat', '["hamstrings","quads"]', '["none (bodyweight exercise)"]', 'Find a nice flat piece of wall and stand with your back leaning against the wall. Slowly slide down the wall while moving your feet away from it, until your thighs are parallel to the ground and both your knees and your hips are bent at a 90° angle. Cross your arms in front of your chest and hold this position for 30 seconds. Variant: put a big inflated rubber ball (like a small basketball) between your knees and squeeze the ball while holding the squat position', '2026-10-28T22:02:36.153Z', 'CC0', 'Blablabla', 'https://wger.de/en/exercise/718/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-722', 'weighted-step-ups-722', 'Weighted Step-ups', '["glutes","quads","hamstrings","calves"]', '[]', 'box step ups w/ barbell and 45''s on each side', '2026-10-28T22:02:36.153Z', 'CC0', 'jigglychipmunk', 'https://wger.de/en/exercise/722/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-723', 'wide-grip-pulldown-723', 'Wide-grip Pulldown', '["lats","shoulders"]', '["cable machine"]', 'Starting position: Arms extended overhead, feeling a stretch in your lats. Keep your shoulders depressed (don’t shrug upward). Pulling phase (concentric): Pull the bar down to your upper chest or collarbone area by driving your elbows down and back. Keep your chest lifted and squeeze your shoulder blades together at the bottom.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/723/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-801', 'dumbbell-push-up-801', 'Dumbbell Push-Up', '["chest","shoulders","triceps"]', '["dumbbell"]', 'Normal Push-ups on Dumbbells, this brings a further range of movement', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/801/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-802', 'barbell-lunges-walking-802', 'Barbell Lunges Walking', '["glutes","quads","hamstrings","calves"]', '["barbell"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/802/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-803', 'one-arm-triceps-extensions-on-cable-803', 'One Arm Triceps Extensions on Cable', '["triceps"]', '["cable machine"]', '', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/803/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-804', 'sloper-hanging-804', 'Sloper hanging', '[]', '["none (bodyweight exercise)"]', 'Hanging on sloper holds of a fingerboard for a amount of seconds', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/804/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-805', 'tricep-pushdown-on-cable-805', 'Tricep Pushdown on Cable', '["triceps"]', '["cable machine"]', 'The cable rope push-down is a popular exercise targeting the triceps muscles. It''s easy to learn and perform, making it a favorite for everyone from beginners to advanced lifters. It is usually performed for moderate to high reps, such as 8-12 reps or more per set, as part of an upper-body or arm-focused workout.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/805/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-820', 'fingerboard-20-mm-edge-820', 'Fingerboard 20 mm edge', '[]', '[]', 'Hang for 10 seconds on a fingerboard with a 20 mm edge', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/820/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-821', 'pullup-on-fingerboard-821', 'Pullup on fingerboard', '["biceps","lats"]', '["none (bodyweight exercise)"]', 'Pullup on a choosen edge of a fingerboard / hangboard', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/821/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-822', 'cable-rear-delt-fly-822', 'Cable Rear Delt Fly', '["shoulders","triceps"]', '["cable machine"]', 'The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles. Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head. With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey. Start the movement by moving your arms back and forth while keeping your arms straight. Pause at the finish of the move for a brief moment before returning the handles to their starting positions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/822/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-828', 'incline-bench-reverse-fly-828', 'Incline Bench Reverse Fly', '["shoulders"]', '["dumbbell","incline bench"]', 'The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/828/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-908', 'zone-2-running-908', 'Zone 2 Running', '[]', '[]', 'Zone two Cardio for endurance, you should be able to speak while running', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'karly', 'https://wger.de/en/exercise/908/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-909', 'reverse-nordic-curl-909', 'Reverse Nordic Curl', '["quads","glutes","abs"]', '[]', 'Natural Leg Extension is alternative to Leg Extension machine with no equipment.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'karly', 'https://wger.de/en/exercise/909/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-910', 'nordic-curl-910', 'Nordic Curl', '["hamstrings","glutes"]', '[]', 'The Nordic hamstring curl is one of the best lower-body exercises to build posterior leg strength, improve knee health, and prevent injury.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'karly', 'https://wger.de/en/exercise/910/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-911', 'incline-skull-crush-911', 'Incline Skull Crush', '["triceps"]', '[]', 'Siting in a 45 Degree Angle, using DB to do Incline Skull Crush', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/911/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-912', 'straight-bar-cable-curls-912', 'Straight Bar Cable Curls', '["biceps"]', '["cable machine"]', 'Standing upright in front of Cable Tower using a straight bar', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/912/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-913', 'reverse-preacher-curl-close-grip-913', 'Reverse Preacher Curl (Close Grip)', '["biceps"]', '["sz-bar"]', 'Sitting reverse on a Biceps Bench with a close grip', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/913/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-914', 'reverse-ez-bar-cable-curls-914', 'Reverse EZ Bar Cable Curls', '["biceps"]', '["cable machine","sz-bar"]', 'Standing in front of cable tower using a SZ Bar', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/914/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-915', 'bus-drivers-915', 'Bus Drivers', '["shoulders"]', '[]', 'Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/915/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-916', 'smith-press-916', 'Smith Press', '["shoulders"]', '["incline bench"]', 'Sitting almost 90 degree angle, smith machine', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/916/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-917', 'straight-bar-cable-front-raise-917', 'Straight Bar Cable Front Raise', '["shoulders"]', '["cable machine","sz-bar"]', 'Back to cable tower, cable between legs, SZ Bar', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/917/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-918', 'seated-dumbbell-side-lateral-918', 'Seated Dumbbell Side Lateral', '["shoulders"]', '["dumbbell"]', 'seated slightly leaned forward at beginning of exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/918/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-919', 't-bar-row-919', 'T-Bar row', '["lats"]', '["barbell"]', 'bent over with triangle grip, slightly bent knees', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/919/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-922', 'seated-cable-mid-trap-shrug-922', 'Seated Cable Mid Trap Shrug', '[]', '["cable machine"]', 'seated straight back, slight hold at top', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/922/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-923', 'lying-dumbbell-row-ss-seated-shrug-923', 'Lying Dumbbell Row SS Seated Shrug', '["lats","biceps"]', '["dumbbell"]', 'laying on the stomach on a bench with slight angle', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/923/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-925', 'smith-machine-slight-incline-press-925', 'Smith Machine Slight Incline Press', '["chest"]', '[]', 'Execution Start position: Unrack the bar and hold it above your upper chest with arms fully extended. Keep your shoulder blades retracted and pressed into the bench . Lowering phase (eccentric): Slowly bring the bar down to just below your collarbone or upper chest. Maintain control - don’t bounce the bar. Pressing phase (concentric): Push the bar upward in a straight line until your arms are fully extended. Focus on squeezing your upper chest at the top. Lock and repeat: Complete your reps, then safely rack the bar back into the hooks.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/925/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-926', 'machine-chest-fly-926', 'Machine chest fly', '["chest"]', '[]', 'seated machine, straight back, slow exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/926/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-927', 'suspended-crossess-927', 'Suspended crossess', '["chest"]', '["none (bodyweight exercise)"]', 'Suspension exercise with trx for chest training', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/927/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-957', 'quadriped-arm-and-leg-raise-957', 'Quadriped Arm and Leg Raise', '["shoulders","glutes","lats"]', '["none (bodyweight exercise)"]', 'In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically. Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'utkb', 'https://wger.de/en/exercise/957/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-958', 'biceps-with-trx-958', 'Biceps with TRX', '["biceps"]', '["none (bodyweight exercise)"]', 'Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/958/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-959', 'trx-rows-959', 'TRX Rows', '["shoulders","biceps","lats"]', '["none (bodyweight exercise)"]', 'This exercise serves as a lead-up to Pull Ups.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/959/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-960', 'kettlebell-swing-960', 'Kettlebell Swing', '["shoulders","glutes","quads","abs"]', '["kettlebell"]', 'While kettlebell swings are a full-body workout, they mostly target the muscles along the posterior chain (back of the body). The main muscles used are the glutes, hamstrings, spinal erectors, and muscles of the upper back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/960/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-961', 'swimming-50m-sprints-961', 'Swimming 50m sprints', '[]', '[]', '50m swimming sprints at 1min', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'abuono', 'https://wger.de/en/exercise/961/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-962', 'elliptical-962', 'Elliptical', '["glutes","quads","biceps","abs","triceps"]', '["none (bodyweight exercise)"]', 'It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/962/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-974', 'curl-with-kettlebell-two-hands-974', 'Curl with kettlebell two hands', '["biceps"]', '["kettlebell"]', 'Stand upright and grip the kettlebell with both hands. Perform the elbow flexion motion, starting from a fully extended position until your hand reaches shoulder height. Spread your legs a little for stability and, to perform the exercise correctly, try not to push with your back or body in general. Change the weight of the kettlebell to adjust the difficulty.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/974/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-975', 'one-handed-kettlebell-curls-975', 'one-handed kettlebell curls', '["biceps"]', '["kettlebell"]', 'Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/975/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-976', 'medicine-ball-booklet-crunch-976', 'Medicine ball booklet crunch', '["abs"]', '["none (bodyweight exercise)"]', 'Using a medicine ball as an overload will make the exercise heavier.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/976/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-977', 'box-squat-977', 'Box squat', '["glutes","quads"]', '["none (bodyweight exercise)"]', 'Set up the box: Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight. Stand with proper form: Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height. Lower down: Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement. Controlled descent: Descend in a controlled manner until your glutes gently touch the box. Don''t plop down. Pause and press up: Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position. Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/977/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-978', 'knee-raises-978', 'Knee Raises', '["abs"]', '["pull-up bar"]', 'The 90° leg raise on the bar is a very intense exercise that involves all the abdominal muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/978/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-979', 'leg-raises-pull-up-bar-979', 'Leg raises pull up bar', '["abs","quads"]', '["pull-up bar"]', 'with a firm grip with both hands on the bar, raise your outstretched legs, until you reach a 90° angle with your torso.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/979/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-980', 'commando-pull-ups-980', 'commando pull-ups', '["shoulders","biceps","lats"]', '["pull-up bar"]', 'variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/980/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-981', 'step-ups-981', 'Step-ups', '["glutes","quads","hamstrings","calves"]', '["bench"]', 'Starting position: Stand facing a chair. Steps: Step up onto the chair. Step off the chair. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/981/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-983', 'high-knees-983', 'High knees', '[]', '["none (bodyweight exercise)"]', 'Starting positionStand straight. Steps: Run in place, putting knees as high up as is comfortable and switching legs at a quick pace.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/983/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-984', 'lunges-984', 'Lunges', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Starting position: Stand with back straight. Steps: Take a large step forward with your left leg. Bring your pelvis down until you almost touch the floor with your right knee. Bring your pelvis back up. Return to the starting position by stepping back. Repeat, switching legs each time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/984/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-985', 'push-up-rotations-985', 'Push-up rotations', '["chest","triceps","shoulders"]', '["none (bodyweight exercise)"]', 'Starting position: Get into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight. Steps: Perform a standard push-up: 1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position. Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor. Repeat, changing sides at step 2 each time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/985/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-986', 'side-split-squats-left-986', 'Side split squats left', '[]', '["none (bodyweight exercise)"]', 'Starting position: Stand tall and take a wide lateral stride, just greater than shoulder width. Steps: Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot. Push back to the starting position. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/986/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-987', 'side-split-squats-right-987', 'Side split squats right', '[]', '["none (bodyweight exercise)"]', 'Starting position: Stand tall and take a wide lateral stride, just greater than shoulder width. Steps: Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot. Push back to the starting position. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/987/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-988', 'bulgarian-split-squats-left-988', 'Bulgarian split squats left', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair. Bend the front knee, balancing with arms until the back knee almost touches the ground. Push back to the starting position and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/988/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-989', 'bulgarian-split-squats-right-989', 'Bulgarian split squats right', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair. Bend the front knee, balancing with arms until the back knee almost touches the ground. Push back to the starting position and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/989/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-990', 'kneeling-kickbacks-990', 'Kneeling kickbacks', '["glutes","hamstrings"]', '["none (bodyweight exercise)"]', 'Starting position: Get down on all fours. Steps: Push one foot back until fully extended, concentrating on the gluteus muscles. Stay for one second, then return to the initial position. Repeat, alternating feet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/990/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-991', 'split-squats-left-991', 'Split squats left', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Starting position: Stand with your back straight. Take a large step forward with your left leg. Steps: Bring your pelvis down until you almost touch the floor with your right knee. Bring your pelvis back up. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/991/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-992', 'split-squats-right-992', 'Split squats right', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Starting position: Stand with your back straight. Take a large step forward with your right leg. Steps: Bring your pelvis down until you almost touch the floor with your left knee. Bring your pelvis back up. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/992/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-993', 'jump-rope-basic-jumps-993', 'Jump rope: basic jumps', '[]', '["none (bodyweight exercise)"]', 'Starting position: Put your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms. Steps: Spin only your wrists with enough force to make the rope spin. Jump just high enough to pass the rope below your feet. Repeat. Notes: This exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/993/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-994', 'forward-arm-circles-994', 'Forward arm circles', '[]', '["none (bodyweight exercise)"]', 'Starting position: Stand tall with your back straight. Steps: Keeping your arms straight, bring them in front of you, move them down, behind your back, then over your head, and back to the initial position. Keep circling your arms as described in step 1.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/994/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-995', 'backward-arm-circles-995', 'Backward arm circles', '[]', '["none (bodyweight exercise)"]', 'Starting position: Stand tall with your back straight. Steps: Keeping your arms straight, bring them in front of you, raise them over your head, then continue the motion behind your back and down to the initial position. Keep circling your arms as described in step 1.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/995/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-996', 'mountain-climbers-996', 'Mountain climbers', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start in the upright push-up position, aka. the high plank position.Hands should be directly under your shoulders.Keep your head in line with your back, facing the floor.Feet should be about hip-width apart. Steps: Move one knee toward the center of your body, towards your elbows, keeping the other leg extended. In a quick jumping movement, straighten the bent leg out and pull the other knee toward your body. Keep repeating step 2, alternating legs. Notes: Throughout the exercise, your back should remain as straight as possible - avoid a hump or a sagging back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/996/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-997', '4-count-burpees-997', '4-count burpees', '[]', '["none (bodyweight exercise)"]', 'Starting position: Stand straight, feet hip-width apart. Steps: Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight. Keeping your hands on the floor, jump your legs backward into high plank position. Jump your feet forward to return to the squat position. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/997/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-998', 'no-push-up-burpees-998', 'No push-up burpees', '[]', '["none (bodyweight exercise)"]', 'Starting position: Stand straight, feet hip-width apart. Steps: Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight. Keeping your hands on the floor, jump your legs backward into high plank position. Jump your feet forward to return to the squat position. Jump up. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/998/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-999', 'reverse-lunges-999', 'Reverse lunges', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Starting position: Stand straight, feet hip-width apart. Steps: Step backward with one leg so it can bend comfortably to a 90 degree angle. Slowly bend both knees to form 90 degree angles. Return to the starting position. Repeat, alternating legs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/999/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1000', 'floor-dips-1000', 'Floor dips', '["triceps","shoulders","chest"]', '["none (bodyweight exercise)"]', 'Starting position: Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together. Steps: Raise your hips off the ground, straightening your arms. Bend your elbows, bringing your hips down. Straighten your arms, returning to the previous position. Repeat steps 2 and 3. Notes: The exercise''s difficulty depends on how high you bring your hips.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1000/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1001', 'high-plank-1001', 'High plank', '["abs","shoulders","triceps"]', '["none (bodyweight exercise)"]', 'Starting position: Get into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight. Steps: Maintain the starting position for the entire duration of the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1001/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1002', 'child-s-pose-1002', 'Child''s pose', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching. Steps: Move your knees so that they''re about hip-width apart. On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground. Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally. Stay in this pose. Tips: To leave the pose, walk your arms back under your shoulders and move your upper body up into a seated position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1002/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1003', 'kettlebell-deadlifts-1003', 'Kettlebell deadlifts', '["hamstrings","glutes","quads"]', '["kettlebell"]', 'Starting position: Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward. Steps: Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement. Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart. While contacting your abs and glutes, stand straight up. Hinge at the hips again to bring the kettlebell back down, similarly to step 1. Repeat from step 3. Tips: Be sure you''re performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1003/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1004', 'forward-shoulder-rotation-1004', 'Forward shoulder rotation', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Place your hands on your shoulders. Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1004/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1005', 'backward-shoulder-rotation-1005', 'Backward shoulder rotation', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Place your hands on your shoulders. Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1005/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1006', 'chin-tuck-1006', 'Chin tuck', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Use fingers on your chin to slowly tuck your chin in, moving your head back to align it with your spine. Hold for 5 seconds. Go back to normal head position and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1006/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1007', 'head-turns-1007', 'Head turns', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight and shoulders down. Steps: Sit or stand up straight, shoulders dropped. Turn your head to the side as far as possible. Stop when you hit a barrier and hold for 5 seconds. Return to center position and repeat, changing sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1007/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1008', 'left-neck-stretch-1008', 'Left neck stretch', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Tilt your head to the side. Take the hand closer to your head and use it to grab your head from the other side. Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still. Maintain this tension until the end of the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1008/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1009', 'right-neck-stretch-1009', 'Right neck stretch', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Tilt your head to the side. Take the hand closer to your head and use it to grab your head from the other side. Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still. Maintain this tension until the end of the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1009/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1010', 'back-neck-stretch-1010', 'Back neck stretch', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit upright on a chair or a firm pillow. Steps: Breathe out and tilt your head forward, chin to chest, putting hands behind your head. Use your hands to pull your head down lightly and press against your hands with your head to balance out the force. Hold for a bit. Relax your arms and head, opening up a bit with your shoulders. Keep repeating this from step 2 onward.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1010/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1011', 'front-neck-stretch-1011', 'Front neck stretch', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Open mouth wide. Slowly tilt head back with mouth opened. If you feel the need for support, clasp your hands behind your head. Very slowly close and open your mouth. At the end, slowly return to starting position and close mouth.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1011/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1012', 'alternating-bicep-curls-1012', 'Alternating bicep curls', '["biceps"]', '["dumbbell"]', 'Starting position: Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down. Steps: Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement. Bring the dumbbell back down until your arm is in its original relaxed position. Repeat, switching arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1012/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1013', 'left-levator-scapulae-stretch-1013', 'Left levator scapulae stretch', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start standing up or sitting down. Turn your head to the left, around 45 degrees or just above your nipple. Place your right hand behind your back or sit on it. Take your left hand and use it to hold the back of your head. Lean your head down slightly. Steps: After assuming the starting position, press your head against your left hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1013/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1014', 'right-levator-scapulae-stretch-1014', 'Right levator scapulae stretch', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start standing up or sitting down. Turn your head to the right, around 45 degrees or just above your nipple. Place your left hand behind your back or sit on it. Take your right hand and use it to hold the back of your head. Lean your head down slightly. Steps: After assuming the starting position, press your head against your right hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1014/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1015', 'clockwise-neck-circles-1015', 'Clockwise neck circles', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing. Steps: In a slower fluid motion and with your head relaxed and not pushing in any direction: lean toward your right shoulder. then bring your head back, facing up. then lean toward your left shoulder.4.and back toward the starting position. Keep repeating this as part of one slower fluid motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1015/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1016', 'counterclockwise-neck-circles-1016', 'Counterclockwise neck circles', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing. Steps: In a slower fluid motion and with your head relaxed and not pushing in any direction: lean toward your left shoulder. then bring your head back, facing up. then lean toward your right shoulder.4.and back toward the starting position. Keep repeating this as part of one slower fluid motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1016/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1017', 'neck-half-circles-1017', 'Neck half circles', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start sitting or standing. Lean your head against one of your shoulders, but don''t push. Steps: In one slower fluid motion and with your head relaxed and not pushing in any direction: bring your head down toward your chest. then lean back aganst your other shoulder. then back toward the chest again.4.and finally toward the starting position. Keep repeating this.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1017/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1018', 'head-tilts-1018', 'Head tilts', '[]', '["none (bodyweight exercise)"]', 'Starting position: Sit or stand with your back straight. Steps: Tilt your head to one side and hold for a bit. Return your head to neutral position and hold for a bit. Tilt your head to the other side and hold for a bit. Return your head to neutral position yet again and hold for a bit. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1018/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1019', 'side-plank-right-1019', 'Side plank right', '["abs"]', '["none (bodyweight exercise)"]', 'Starting position: Lie down on your side, with your bottom elbow at a right angle, arm sticking out. Lift your pelvis off the floor by lifting your bottom shoulder up, keeping the forearm on the floor; your head, pelvis, and feet should be in a straight line. Steps: Hold this position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1019/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1020', 'pistol-squats-right-1020', 'Pistol squats right', '["glutes","quads","hamstrings","calves","abs"]', '["none (bodyweight exercise)"]', 'Stand on one leg, with your other leg straight and slightly forward. Bend one knee slowly, descending into a squat and keeping your back and your other leg straight. Slowly raise yourself from the squat, straightening the bent knee and keeping the other leg straight. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1020/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1021', 'calf-raises-right-leg-1021', 'Calf raises, right leg', '["calves"]', '["none (bodyweight exercise)"]', 'Stand on the floor or on the edge of a step to increase the range of movement. Raise one foot. Lift your heel until you''re standing on your toes. (variable) Stay in this position for three seconds Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1021/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1022', 'single-arm-plank-to-row-1022', 'Single Arm Plank to Row', '["shoulders","biceps","lats","abs"]', '["kettlebell"]', 'Start position as row, extend to plank and back. Finish with row and repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1022/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1027', 'elevated-prayer-stretch-1027', 'Elevated prayer stretch', '["lats"]', '["bench"]', 'Starting position: Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up. Steps: On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench. Hold for a few seconds. On inhale, relax your back to return to the starting position. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1027/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1028', 'quadruped-thoracic-rotation-left-1028', 'Quadruped thoracic rotation left', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start kneeling on all fours, knees shoulder-width apart. Place your left hand behind your head while keeping your right hand outstretched and touching the floor. Steps: On inhale, move your left elbow toward your right hand, keeping your left hand behind your head. On exhale, move your left elbow to point up toward the ceiling. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1028/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1029', 'quadruped-thoracic-rotation-right-1029', 'Quadruped thoracic rotation right', '[]', '["none (bodyweight exercise)"]', 'Starting position: Start kneeling on all fours, knees shoulder-width apart. Place your right hand behind your head while keeping your left hand outstretched and touching the floor. Steps: On inhale, move your right elbow toward your left hand, keeping your right hand behind your head. On exhale, move your right elbow to point up toward the ceiling. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1029/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1080', 'hindu-pushups-1080', 'Hindu Pushups', '["shoulders","chest","triceps"]', '[]', 'Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position "Dog Facing Down", passing to "Cobra" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Imobard', 'https://wger.de/en/exercise/1080/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1081', 'shoulder-dislocates-1081', 'Shoulder dislocates', '[]', '[]', 'Starting position: Stand up with your back straight and a resistance band, towel, or broomstick handle in hand. With your hands straight in front of your body and the band between your hands, push your hands apart to both be at around 45 degrees from your body, thumbs facing down. If using a towel or broomstick handle instead, grab it with an overhand grip. Steps: Keeping your arms outstretched, rotate at the shoulders to bring your arms overhead and then down toward your glutes. Rotate at the shoulders in the opposite direction - overhead and then toward your groin. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1081/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1082', 'bent-over-row-to-external-rotation-1082', 'Bent over row to external rotation', '[]', '[]', 'Starting position: Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor. Steps: Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine. Hold for a bit. Rotate at your elbows to bring your hands as far up as you can. Hold for a bit. Rotate at your elbows back to the previous position. Bring your arms down to the original position. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1082/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1083', 'ywts-1083', 'YWTs', '[]', '[]', 'Starting position: Lie down, preferably on a mat. Stretch your arms above your head in a "Y" position (arms pointing up diagonally at around 45 degrees). Your thumbs should be pointing up. Steps: With arms in the Y position, lift your chest slightly from the ground, creating a pull tension in your arms upward. Hold this position for several seconds (15-30 is ideal). Keeping your chest up, bend at your elbows to move from a Y position to a "W" position, with arms bent at the elbows and maintaining the upward tension. Hold for around as long as with the Y position. Still with your chest up, move to a "T" position, straightening your arms out to the side to be perpendicular to your body. Hold for around as long as you held the W position. Move from the T position to the W position, then from the W position to the Y position. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1083/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1084', 'dumbbell-floor-press-1084', 'Dumbbell Floor Press', '["chest","shoulders","biceps","triceps"]', '["dumbbell"]', 'Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1084/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1086', 'close-grip-press-ups-1086', 'Close-grip Press-ups', '["lats","chest","shoulders","biceps","triceps"]', '["none (bodyweight exercise)"]', 'Drop into a strong plank position, bringing your hands close together until they''re almost touching. (picture 1)Bend your elbows to slowly bring your chest to the floor (picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1086/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1087', 'dumbbell-hang-power-cleans-1087', 'Dumbbell Hang Power Cleans', '["hamstrings","glutes","calves","quads"]', '["dumbbell"]', 'On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1087/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1088', 'dumbbell-sumo-deadlift-1088', 'Dumbbell sumo deadlift', '["hamstrings","glutes","quads"]', '["dumbbell"]', 'Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’ (picture 1).Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position (picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1088/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1089', 'medicine-ball-twist-1089', 'Medicine ball twist', '["abs"]', '["swiss ball"]', 'In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1089/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1090', 'vpushup-1090', 'Vpushup', '["chest","quads","abs","triceps"]', '["none (bodyweight exercise)"]', 'Lift your body off the ground by pushing your arms upwards', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1090/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1091', 'plank-shoulder-taps-1091', 'Plank Shoulder Taps', '["shoulders","glutes","abs","lats"]', '["gym mat"]', 'In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1091/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1092', 'bag-training-1092', 'Bag training', '["shoulders","chest","biceps","hamstrings","calves","lats","abs"]', '["none (bodyweight exercise)"]', 'Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1092/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1093', 'rowing-machine-1093', 'Rowing Machine', '["shoulders","biceps","hamstrings","calves","glutes","lats","quads","abs"]', '["none (bodyweight exercise)"]', 'Sit on a rowing machine with your back straight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Boertie', 'https://wger.de/en/exercise/1093/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1094', 'seated-bench-press-1094', 'Seated Bench Press', '["chest"]', '["bench"]', 'Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'colundrum', 'https://wger.de/en/exercise/1094/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1096', 'abduction-while-standing-1096', 'Abduction while standing', '[]', '["none (bodyweight exercise)"]', 'Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tregga', 'https://wger.de/en/exercise/1096/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1098', 'seated-rear-delt-rise-1098', 'Seated rear delt rise', '["lats"]', '["dumbbell"]', 'Seated, bent 45 deg forward. Arms fully stretched out, raise arms up to shoulder height and back down', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1098/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1099', 'dynamic-side-hold-1099', 'Dynamic side hold', '["abs"]', '["kettlebell"]', 'Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1099/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1100', 'wall-balls-1100', 'Wall balls', '["shoulders","glutes","quads","biceps","chest","abs"]', '["swiss ball"]', 'Get a medicine ball, shoulder width stance, squat, thrust the ball as high as possible against the wall and catch', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1100/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1101', 'horizontal-traction-isometry-1101', 'Horizontal traction isometry', '["lats","chest","shoulders","biceps"]', '["pull-up bar"]', 'Pull yourself up on the bar until your chin is at or above bar height, and hold this position for the set time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1101/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1102', 'alternate-back-lunges-1102', 'Alternate back lunges', '["glutes","quads"]', '["none (bodyweight exercise)"]', 'The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1102/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1103', 'walking-bridge-1103', 'walking bridge', '["abs","shoulders","biceps","glutes","lats"]', '["none (bodyweight exercise)"]', 'from a standing position with knees slightly bent and hands resting on the floor. From here, proceed forward with your hands keeping your buttocks contracted and without losing control of your lower back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1103/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1104', 'walking-1104', 'Walking', '["hamstrings","calves","glutes","lats","quads","abs"]', '["none (bodyweight exercise)"]', 'Walking outdoor or indoor, try keeping a pace of at list 100 steps per minute.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1104/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1105', 'seated-knee-tuck-1105', 'Seated Knee Tuck', '["abs"]', '["none (bodyweight exercise)"]', 'Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'utkb', 'https://wger.de/en/exercise/1105/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1109', 'cable-concentration-curl-1109', 'Cable Concentration Curl', '["biceps"]', '["cable machine"]', 'The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/1109/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1111', 'push-ups-incline-1111', 'Push-Ups | Incline', '["chest","triceps"]', '["bench","incline bench"]', 'Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1111/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1112', 'push-ups-decline-1112', 'Push-Ups | Decline', '["chest","shoulders","triceps"]', '["bench","incline bench"]', 'Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position. Unlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1112/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1113', 'push-ups-parallettes-1113', 'Push-Ups | Parallettes', '["chest","shoulders","triceps"]', '[]', 'Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position. Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form. The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1113/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1114', 'rest-for-timed-workouts-1114', 'Rest (for timed workouts)', '[]', '[]', 'When creating a workout based on time, add this to add rest time in the program', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1114/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1115', '3d-lunge-warmup-1115', '3D lunge warmup', '[]', '["dumbbell"]', 'As a warmup, use light dumbbells, one in each hand. Lunge in alternating directions, forward, sideways, backwards and 45 degree angles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1115/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1116', 'dumbbell-farmer-s-carry-1116', 'Dumbbell farmer''s carry', '[]', '["dumbbell"]', 'Grab half your body weight in each hand and walk.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1116/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1117', 'seated-cable-row-1117', 'Seated Cable Row', '["lats","biceps"]', '["cable machine"]', 'Take a seat on the machine with your feet planted, a little wider than shoulder width. Drive the heels, and squeeze the glutes. Grab onto the cable handle. Sit up tall with a slight bend through the knees. Tighten up the abs and low back to maintain a perpendicular angle to the floor with your torso. Roll the shoulders back and down. Squeeze them together as you row, thinking about pinching a pencil in between them. As you do this, pull the handle back towards you, landing right above your belly button. Pause here for a moment before returning the handle, still squeezing the shoulder blades. Once you''ve returned the weight to the stack, then allow the shoulder blades to relax, without pulling the torso forward. Repeat the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1117/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1119', 'remo-maquina-agarre-estrecho-1119', 'Remo maquina agarre estrecho', '["lats","biceps"]', '[]', 'Remo en máquina con barra en agarre estrecho', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1119/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1120', 'remo-maquina-agarre-estrecho-supino-1120', 'Remo maquina agarre estrecho supino', '["lats","biceps"]', '[]', 'Remo en máquina o polea con agarre cerrado supino', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1120/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1125', 'wide-grip-supinated-lat-pulldown-1125', 'Wide-grip supinated lat pulldown', '["lats"]', '["cable machine"]', 'Downward movement: Pull the bar down so that it passes close to your chin and touches the upper part of your chest. Keep the rest of your body still.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1125/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1127', 'close-grip-supinated-lat-pulldown-1127', 'Close-grip supinated lat pulldown', '["lats"]', '["cable machine"]', 'Downward movement: Pull the bar down so that it passes close to your chin and touches the upper part of your chest. Keep the rest of your body still.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1127/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1131', 'cable-glute-extension-1131', 'Cable glute extension', '["glutes"]', '["cable machine"]', 'This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes. Stand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury. It is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1131/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1132', 'machine-glute-extension-1132', 'Machine glute extension', '["glutes"]', '[]', 'A GHD hip extension is one of the best exercises for the glutes. While the exercise mainly targets the glutes, it is also excellent for the lower back, the calves and the hamstrings.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1132/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1136', 'neutral-grip-chest-pulldown-1136', 'Neutral-grip chest pulldown', '["biceps","lats"]', '["cable machine"]', 'The lat pulldown is an important exercise for strengthening the back and improving posture, which can contribute to a healthier life. To perform this exercise correctly and avoid injury, it is important to follow a few key steps: Position yourself in front of the cable machine with your knees slightly bent and your feet on the floor. Grip the cable handle with your palms facing each other and your hands shoulder-width apart. Pull the handle down until it touches or comes close to your chest, holding the position for one or two seconds. Slowly raise the handle back to the starting position, making sure to keep your arms and hands straight and your back straight throughout the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1136/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1137', 'high-pulley-pullover-1137', 'High-pulley pullover', '["lats"]', '["cable machine"]', 'Stand facing the machine, feet slightly apart, gripping the bar with an overhand grip, arms extended, hands shoulder-width apart. Keeping your back fixed and your abdominal muscles contracted, inhale and bring the bar down to your thighs while keeping your arms extended (or your elbows slightly bent). Exhale at the end of the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1137/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1138', 'incline-bench-pulldown-1138', 'Incline bench pulldown', '["lats"]', '["cable machine"]', 'Lying face down on the incline bench facing the cable machine, perform the pulldown.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1138/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1141', 'arabesque-1141', 'Arabesque', '["hamstrings","glutes"]', '["none (bodyweight exercise)"]', 'Take all your weight onto one leg and you''re going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cleen', 'https://wger.de/en/exercise/1141/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1143', 'seated-back-extension-machine-1143', 'Seated Back Extension Machine', '["lats"]', '[]', 'Adjust the seat and the back pad so that the pad sits at the height of your shoulder blades or mid-back. Sit in the machine with your hips and lower back against the seat and backrest and your feet on the platform. Cross your arms over your chest or hold the handles. Exhale and push the pad backwards using your lower back muscles until your spine is in line with your hips. Pause for a second at the end position. Inhale and slowly return to the starting position, without letting the weight stack slam down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1143/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1185', 'triceps-pushdown-1185', 'Triceps Pushdown', '["triceps"]', '["cable machine"]', 'Triceps pushdown on cable using lat bar.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'anto.kreegyr', 'https://wger.de/en/exercise/1185/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1186', 'one-arm-bent-row-1186', 'One Arm Bent Row', '["lats","biceps"]', '["cable machine"]', 'One arm bent over row on cable with a machine', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'anto.kreegyr', 'https://wger.de/en/exercise/1186/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1188', 'side-bend-1188', 'Side bend', '["abs"]', '["dumbbell"]', 'With a weight in one hand, extend that arm down and bend the other arm, resting your hand on your head. Now move the hand holding the weight by rotating your torso up and down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1188/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1192', 'alternating-biceps-curls-with-dumbbell-1192', 'Alternating Biceps Curls With Dumbbell', '["biceps"]', '["dumbbell"]', 'Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend one arm at a time and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring the arm back down, slowly, and do the same with the other arm. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1192/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1193', 'russian-twist-1193', 'Russian Twist', '["lats","abs"]', '["dumbbell","gym mat","swiss ball"]', 'Hold a dumbbell, barbell weight or something else that is heavy with both hands, but make sure it is not too heavy and you are able to keep in form. Lean back to a 45-degree angle from the floor. For an extra challenge, lift your feet off the floor. Rotate your arms to one side to the same level as your chest, touch the floor for a little extra challenge, and then do the same to the other side. When you''re back in your original position after doing both sides it will count as 1 rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lion', 'https://wger.de/en/exercise/1193/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1194', 'pallof-press-1194', 'Pallof Press', '["shoulders","glutes","abs","chest","triceps"]', '["cable machine"]', 'The Pallof press is an anti-rotation exercise that trains the larger and smaller muscles around the spine to resist rotation. Stand parallel to the cable machine or to the anchor point to the resistance band and clasp with the handle or band with both hands. Make sure your torso is front on and bring your hands to the center of your chest and slowly press out. Slowly return your hands to the chest and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'prevail90', 'https://wger.de/en/exercise/1194/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1195', 'side-slides-squats-1195', 'Side Slides + Squats', '["quads","calves","glutes"]', '["none (bodyweight exercise)"]', 'With feet a little wider than shoulder-width apart and staying low to mimic a defensive position, you should step with their lead leg and push off with their plant leg. After three slides, rotate your body for 180 degree on the guiding (/outer) leg and do a squat. Continue.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Insight', 'https://wger.de/en/exercise/1195/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1196', 'wall-drills-1196', 'Wall Drills', '["quads","calves"]', '["none (bodyweight exercise)"]', 'Exercises for strengthening knee and leg musculature. Lateral Wall Drills March - https://youtu.be/9RiTlJ6Mmek Lateral Wall Drills OPEN - https://youtu.be/ADRlN8-Wfdg Lateral Wall Drills CROSS - https://youtu.be/hGH2sj0Tzu4', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Insight', 'https://wger.de/en/exercise/1196/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1198', 'inverted-rows-1198', 'Inverted Rows', '["biceps","lats","chest","abs"]', '["none (bodyweight exercise)"]', 'Maintain a straight body, retract your shoulder blades, and pull your chest to the bar for an effective back and upper body workout.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Gavru', 'https://wger.de/en/exercise/1198/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1200', 'tibialis-raises-1200', 'Tibialis raises', '[]', '["none (bodyweight exercise)"]', 'Stand up straight Lift the balls of your feet, resting on your heels.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1200/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1201', 'dragon-squat-1201', 'Dragon squat', '["quads","hamstrings","calves","glutes"]', '["none (bodyweight exercise)"]', 'Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1201/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1202', 'side-lying-hip-abduction-1202', 'Side Lying Hip Abduction', '[]', '["none (bodyweight exercise)"]', 'Begin by lying down on your side with your top leg straight and your bottom leg bent for support. Lift your top leg off the ground (optional) - Hold position at the top Resources: 40 seconds YouTube video: https://www.youtube.com/watch?v=g9FtnmsIYgI', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1202/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1203', 'calf-raises-left-leg-1203', 'Calf raises, left leg', '["calves"]', '["none (bodyweight exercise)"]', 'Stand on the floor or on the edge of a step to increase the range of movement. Raise one foot. Lift your heel until you''re standing on your toes. (variable) Stay in this position for three seconds Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1203/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1204', 'cycling-cardio-session-1204', 'Cycling cardio session', '[]', '[]', 'Cardio session on a Technogym Bike Excite 1000 stationary bike.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1204/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1205', 'wrist-curl-dumbbells-1205', 'Wrist curl, dumbbells', '[]', '["dumbbell"]', 'Sitting on a bench, grab the dumbbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face. (optional/variable) Pause at the top. Slowly return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1205/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1207', 'scorpion-kick-1207', 'Scorpion Kick', '[]', '["none (bodyweight exercise)"]', 'Get into the push-up position with your shoulders directly above your hands and your feet hip-width apart. Make sure that your body forms a straight line from your head to your heels. Now pull your right knee towards your chest. While keeping your knee bent, lift your right leg as high as possible with your lower right leg pointing straight up. Now rotate your hips so that your right foot swings over your left leg. Continue to rotate and move your right foot towards the floor until you are forced to roll onto the outside of your left standing foot. Make sure that you do not rotate your upper body. Now return to the starting position and repeat the exercise with your left leg.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1207/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1208', 'prisoner-squat-1208', 'Prisoner Squat', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'Stand upright with your chest slightly raised, your feet hip-width apart and your toes pointing straight ahead. Bring your hands to the back of your head with your fingers slightly interlaced and your elbows pointing to the side. Push your hips back and bend your knees, keeping your upper body as upright as possible. Push your knees outwards, they must never point towards each other. If your upper body moves slightly forward, make sure that it does not bend. Always keep your elbows level with your ears by tensing the muscles between your shoulder blades. If you are flexible enough, you can sink down until your buttocks touch your calves. However, make sure that you do not bend your spine. Before this happens, reverse the movement and use your heels and glutes to push yourself upwards with so much momentum that your feet lift off briefly and you do a little hop. If necessary, correct the position of your feet, arms and upper body before you move on to the next repetition. Translated with www.DeepL.com/Translator (free version)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1208/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1209', 'shoulder-width-three-point-push-up-1209', 'Shoulder width three-point push-up', '["chest","shoulders","abs","triceps"]', '["none (bodyweight exercise)"]', 'Get into a push-up position with your shoulders directly above your hands and your feet hip-width apart. Draw your belly button in towards your spine and tighten your abdominal muscles. Lift your left foot about five centimetres off the floor. Point your toes straight down. Do not move your hips. Your body forms a straight line from your head to your heels throughout the exercise. Now bend your elbows, lower your chest to the floor and push yourself back up. Repeat the exercise on the other side.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1209/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1210', 'skydiver-with-arms-in-t-position-1210', 'Skydiver with arms in T-position', '[]', '["none (bodyweight exercise)"]', 'Lie on your stomach with your legs more than shoulder-width apart and your feet up. Your arms are stretched out to the side and form a T with your upper body, your palms are on the floor. Now raise your upper body, arms and legs as high as you can while keeping your body under tension. Turn your thumbs towards the ceiling and pull your shoulder blades together. While keeping your upper body and all limbs in the air, bring your legs together and then spread them again, keeping them constantly in the air. For the remaining repetitions, only move your legs open and closed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1210/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1214', 'front-lever-tuck-1214', 'Front lever tuck', '["shoulders","biceps","lats","triceps"]', '["pull-up bar"]', 'The muscles involved in the Front Lever, most subjected to stress, are mainly the extensors such as: the latissimus dorsi, the teres major, the posterior deltoid and the long head of the biceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1214/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1215', 'reverse-snow-angel-1215', 'Reverse Snow Angel', '["shoulders","hamstrings","glutes","abs"]', '["none (bodyweight exercise)"]', 'Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and move them to your side slowly. Then, move them back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'mike6426', 'https://wger.de/en/exercise/1215/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1216', 'recruitment-pulls-1216', 'Recruitment Pulls', '[]', '[]', 'Find a few specific edge sizes on a hangboard, get fixed underneath them with the board overhead, and pull with max effort, 1 arm at a time, for 3-5 seconds. When positioning for this get set up with a large elbow angle (120-150 degrees) and not in full extension.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1216/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1217', 'finger-pushup-1217', 'Finger Pushup', '["chest","shoulders","abs","triceps"]', '["none (bodyweight exercise)"]', 'Hand Positioning: Start in a plank position with your hands directly beneath your shoulders. Spread your fingers wide apart, placing them firmly on the ground. Finger Placement: Gradually lift your palms off the ground, shifting the weight onto your fingers. Focus on distributing the load evenly across your fingertips and thumbs. Body Alignment: Maintain a straight line from head to heels to engage your core. Keep your body in a controlled and stable position throughout the exercise. Lowering Phase: Slowly bend your elbows, lowering your chest towards the ground. Ensure controlled movement, maintaining stability on your fingertips. Pushing Up: Press through your fingertips to straighten your arms, returning to the starting position. Emphasize the engagement of your fingers and thumbs throughout the push-up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1217/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1218', 'knee-push-ups-1218', 'knee push-ups', '["shoulders","chest","triceps"]', '["none (bodyweight exercise)"]', 'Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart. Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders. Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor. Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement. Perform the desired number of repetitions, controlling the movement and maintaining good form.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'PaukOne', 'https://wger.de/en/exercise/1218/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1219', 'australian-pull-ups-1219', 'Australian pull-ups', '["shoulders","biceps","lats"]', '["none (bodyweight exercise)"]', 'Lie down under a high bar or suspension bar, positioned at an appropriate height. Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you). Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body. Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together. Hold the contraction at the top of the movement for a moment to maximize muscle activation. Slowly return to the starting position, extending your elbows.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'PaukOne', 'https://wger.de/en/exercise/1219/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1223', 'claps-over-the-head-1223', 'Claps over the head', '["shoulders"]', '["none (bodyweight exercise)"]', 'Stand with your feet shoulder width apart. Raise your arms and clap over your head', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1223/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1224', 'dumbbell-drag-curls-1224', 'Dumbbell drag curls', '["biceps"]', '["dumbbell"]', 'Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1224/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1225', 'dumbbell-wide-bicep-curls-1225', 'Dumbbell wide bicep curls', '["biceps"]', '["dumbbell"]', 'Hold a dumbbell in each hand with your hands slightly wider than shoulder-width apart and palms facing forward. Bend your elbows and lift the dumbbells to your shoulders. Slowly return and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1225/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1226', 'dumbbell-bicep-curl-to-press-1226', 'Dumbbell bicep curl to press', '["biceps"]', '["dumbbell"]', 'Bend your elbows and lift the dumbbells to your shoulders. Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1226/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1227', 'dumbbell-rear-delt-row-1227', 'Dumbbell rear delt row', '["shoulders"]', '["dumbbell"]', 'Hold a dumbbell in each hand. Bend at your hips to make your back almost parallel to the floor. Let your arms hang down. Keep your arms in line with your shoulders. bend and lift your elbows out to the sides until your upper arms are parallel to the floor. Slowly return and repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1227/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1228', 'dumbbell-close-grip-bench-press-1228', 'Dumbbell close grip bench press', '["chest","triceps"]', '["dumbbell"]', 'Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together. Slowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1228/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1230', 'triceps-stretch-left-1230', 'Triceps stretch left', '["triceps"]', '["none (bodyweight exercise)"]', 'Put your left hand on your back, use your right hand to grab your left elbow and gently pull it. Hold this position for a few seconds.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1230/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1231', 'triceps-stretch-right-1231', 'Triceps stretch right', '["triceps"]', '["none (bodyweight exercise)"]', 'Put your right hand on your back, use your left hand to grab your right elbow and gently pull it. Hold this position for a few seconds.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1231/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1232', 'standing-biceps-stretch-left-1232', 'Standing biceps stretch left', '["shoulders","biceps","chest"]', '["none (bodyweight exercise)"]', 'Stand with your left arm close to a wall. Extend your left arm and put your left hand on the wall, then gently turn your body to the right.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1232/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1233', 'standing-biceps-stretch-right-1233', 'Standing biceps stretch right', '["shoulders","biceps","chest"]', '["none (bodyweight exercise)"]', 'Stand with your right arm close to a wall. Extend your right arm and put your right hand on the wall, then gently turn your body to the left.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1233/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1234', 'dumbbell-single-leg-hip-thrust-1234', 'Dumbbell Single-leg Hip Thrust', '["glutes","hamstrings","quads"]', '["dumbbell"]', 'The single-leg hip thrust is performed by placing your upper back on a weight bench, raising one leg, and extending the hip of the other leg to achieve an isolated contraction of the glute. By working each side separately, you can fully isolate your glutes unilaterally, providing maximal training stimulus.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1234/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1238', 'frog-stand-1238', 'Frog stand', '["shoulders","biceps","abs"]', '["none (bodyweight exercise)"]', 'Starting position: Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed. Bend your knees into a squat position. Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide. Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels. Upward phase: Push with your feet and hands to lift your body off the ground. Straighten your legs and arms, keeping your body aligned. Engage your core and glutes to maintain the position. If needed, rest your knees on the wall or bench for assistance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1238/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1239', 'standing-calf-stretch-1239', 'Standing Calf Stretch', '["calves"]', '["none (bodyweight exercise)"]', 'This stretch targets the gastrocnemius (the chief muscle of the calf of the leg, which flexes the knee and foot). It is easy to perform anywhere. All you need is a wall or a chair.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1239/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1240', 'standing-soleus-stretch-1240', 'Standing Soleus Stretch', '[]', '["none (bodyweight exercise)"]', 'This stretch targets the Soleus part of your calf. It may be performed with a wall or chair.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1240/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1241', 'exercise-band-dorsiflexion-1241', 'Exercise Band Dorsiflexion', '[]', '["resistance band"]', 'This exercise uses an exercise band. It targets the Soleus and Tibialis anterior.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1241/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1242', 'exercise-band-plantarflexion-1242', 'Exercise Band Plantarflexion', '["calves"]', '["resistance band"]', 'Banded plantarflexion is a great way to bridge the gap between plantarflexion range of motion and the more strenuous calf raises in weight bearing. This can help strengthen the calf muscles, load the Achilles tendon, and improve plantarflexion range of motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1242/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1243', 'double-leg-calf-raise-1243', 'Double Leg Calf Raise', '["calves"]', '["none (bodyweight exercise)"]', 'The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1243/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1244', 'yoga-exercise-cow-cat-1244', 'Yoga exercise: Cow-cat', '["shoulders","lats","abs"]', '["gym mat"]', 'First get into the four-footed stance. The hands are underneath the shoulders. The fingers are fanned out wide and ensure a stable stance. It is best to rest your front body weight on your thumbs and index fingers. Now place your legs hip-width apart on the yoga mat. Your thighs should be vertically below your hips. Make sure that your weight is evenly distributed between your hands and knees. Your head is an extension of your spine and you are looking down at your mat. Your back is in a neutral position. Breathe in deeply and start with the cat. With the next exhalation, round your back vertebra by vertebra. Try to pull yourself as far as possible towards the ceiling. Pull your head towards your chest and tilt your pelvis. Now inhale deeply and move into the opposite position, cow pose. Bend your back down, pull your shoulders back slightly and lift your head as far as is comfortable for you. Your gaze is directed upwards. Breathe out consciously and switch back to the cat. With the next exhalation, switch back to cow. Repeat the exercise a few times and make sure that you are in the flow.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'damnlost', 'https://wger.de/en/exercise/1244/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1245', 'front-lever-1245', 'Front Lever', '["lats","abs"]', '["none (bodyweight exercise)"]', 'The front lever is a figure where the body is kept in a horizontal position parallel to the floor.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1245/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1246', 'trx-roll-out-1246', 'TRX roll out', '["abs"]', '["none (bodyweight exercise)"]', 'Hold the handles in your hands, extend your arms and keep them parallel at chest height. The movement you need to perform is to open your arms in line with your shoulders while leaning your body forward. Try not to extend your shoulders beyond 90°, and keep your abdominal muscles and glutes contracted. Muscles involved: transverse abdominis, rectus abdominis and spinal erectors.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1246/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1248', 'ice-cream-maker-1248', 'Ice cream maker', '["lats","abs"]', '["none (bodyweight exercise)"]', 'From the final phase of a pull-up, we push ourselves back with our shoulders until we reach the front lever position. From there, we pull ourselves back up to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1248/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1252', 'front-lever-pull-up-1252', 'Front lever pull-up', '["biceps","lats","abs","shoulders"]', '["pull-up bar"]', 'in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1252/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1259', 'trx-obliques-1259', 'TRX Obliques', '["abs","shoulders","chest"]', '[]', 'Place your feet in the stirrups and assume a high plank with your hands directly beneath your shoulders. Pull your knees to your right elbow, then push them back out and to the centre.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1259/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1260', 'trx-hammer-curl-1260', 'TRX hammer curl', '["biceps"]', '[]', 'Place the grips as if they were a continuation of the straps. We will position our arms stretched forward and our body leaning back, completely straight. The biceps muscles will activate as you bend your elbows to bring your body towards the straps. The contraction movement will end with a slight outward movement of the hands, due to the grip we are using.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1260/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1261', 'trx-gorilla-biceps-curl-1261', 'TRX gorilla biceps curl', '["biceps"]', '[]', 'We''ll stand facing the TRX straps and grab them with our fists facing each other, facing forward, with our arms fully extended at about shoulder-width apart. We''ll keep our body straight, backward, as in the previous exercises, since we''ll be lifting our body toward the TRX straps by activating our biceps. Our body will be straight, with our feet flat on the floor. This time, we''ll place our arms open to the sides and at chest height. The movement we''ll perform is a contraction toward our chest. To achieve this, we''ll bend our elbows so that, by activating our biceps, we can pull our body toward the straps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1261/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1262', 'trx-single-arm-bicep-curl-1262', 'Trx Single Arm Bicep Curl', '["biceps","shoulders"]', '[]', 'Step 1: Stand comfortably and grasp the handles of the suspension system. Step 2: Lean back resting your weight on one arm, keepng the spine neutral. Step 3: Slowly curl to pull your body weight to the up position. Supinate the arm and squeeze as you approach the end position. Step 4: Lower yourself back down and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1262/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1263', 'back-bridge-1263', 'Back bridge', '["shoulders","hamstrings","calves","lats","triceps"]', '["none (bodyweight exercise)"]', 'Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It''s not good to lift your back off the floor; it should remain straight. It should be well rounded. You''ll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1263/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1266', 'trx-tricep-extension-1266', 'TRX Tricep Extension', '["triceps"]', '[]', 'Attach the TRX or other suspension system overhead, having the handles hanging at chest level or slightly lower. Experiment to see what height allows you to set up in the best way. Stand in front of the handles and grab them with your palms facing down. Engage your abs, squeeze your glutes, take a breath and lean forward, lifting your heels off the floor. Keep your elbows straight. Take another breath and lower yourself slowly by bending your elbows. Go down until your elbows are at a 90-degree angle (to the point where your wrists are above your elbows). Hold the position for a moment. Extend your arms by engaging your triceps and bring yourself to the starting position as you exhale.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1266/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1269', 'trx-dips-1269', 'TRX dips', '["triceps","chest"]', '[]', 'Start with the hands on the suspension trainer and feet on the ground. Your hands should be under your shoulders with the feet slightly in front. Lower yourself by bringing the hips between the handles and flexing the elbows. Extend the elbows to come back to the starting position and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1269/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1270', 'low-pulley-cable-fly-1270', 'Low Pulley Cable Fly', '["chest","shoulders"]', '["cable machine"]', 'Adjust the cable machine: Set the pulley to the lowest setting possible. Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists. Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise. Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables. Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest. Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles. Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level. Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'FEFFO', 'https://wger.de/en/exercise/1270/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1273', 'pullover-1273', 'Pullover', '["chest","lats"]', '["dumbbell"]', 'Doubling as a back and chest exercise, the Dumbbell Pullover can train both your pecs and lats.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '3leh', 'https://wger.de/en/exercise/1273/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1274', 'sitting-calf-stretch-dorsiflexion-1274', 'Sitting Calf Stretch (Dorsiflexion)', '["calves"]', '["none (bodyweight exercise)"]', 'This is a light stretch for the calf that is great for rehab.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1274/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1275', 'plantarflexion-stretch-with-band-1275', 'Plantarflexion Stretch with Band', '[]', '["resistance band"]', 'This stretch is for the ankles, as well as Tibialis anterior.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1275/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1280', 'biceps-close-grip-pull-down-1280', 'Biceps Close Grip Pull Down', '["biceps","shoulders","lats"]', '[]', 'On a lat pull down machine, hold the bar keeping your hands relatively close. Use an underhand grip (I.E.: the back of your hand must be facing the machine). Then pull down the bar in a straight line towards the ground. Make sure your biceps are the main drivers of the motion. You will probably feel your shoulders and lats working, but make sure your biceps are working more.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daniel.escada', 'https://wger.de/en/exercise/1280/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1282', 'chin-up-isometric-hold-1282', 'Chin-up Isometric Hold', '["lats","biceps"]', '["pull-up bar"]', 'Grip the bar with an underhand grip (palms facing you) and pull yourself up until your chin is at or above the bar. Hold this top position for the set time, keeping your core tight, your shoulders stable and your body still.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1282/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1283', 'incline-chest-supported-dumbbell-row-1283', 'Incline Chest-Supported Dumbbell Row', '["biceps","lats"]', '["bench","dumbbell"]', 'Set up an adjustable bench at a 45-degree angle. Lay on your stomach with your head hanging just above the edge of the bench. Grab a dumbbell in each hand and set up with a good posture - core and lats engaged and shoulders neutral. Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep. Finally, lower the dumbbells back to the starting position and repeat until all reps are completed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1283/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1284', 'pseudo-planche-push-up-1284', 'Pseudo Planche Push-up', '["shoulders","chest"]', '["none (bodyweight exercise)"]', 'You should have the shoulder line in front of your wrists an perform a push-up, maintaining the shoulder in the same position', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'vdrb', 'https://wger.de/en/exercise/1284/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1285', 'talons-fesses-1285', 'Talons fesses', '["calves","hamstrings"]', '["none (bodyweight exercise)"]', 'Touch your heels to your buttocks, while remaining static or moving', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1285/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1286', 'dynamic-planche-1286', 'Dynamic Planche', '["abs"]', '["none (bodyweight exercise)"]', 'Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart. Engage your core to keep your body in a straight line from head to toe. From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position. Continue repeating this jumping motion, maintaining control and core stability throughout the exercise. Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing. Keep your gaze fixed on the ground to maintain proper spinal alignment. Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program. To finish the exercise, rest by releasing the plank position, then stretch if necessary to loosen your muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1286/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1287', 'reach-ups-1287', 'Reach ups', '["abs"]', '["none (bodyweight exercise)"]', 'To perform this exercise, lie on your back with your arms extended overhead. Then, contract your abdominals and lift your torso off the floor while reaching your arms toward the ceiling to "reach" as high as possible. Slowly return to the starting position, controlling the movement. Reach ups strengthen the abdominal muscles and improve the flexibility of the spine. They can be incorporated into a variety of training routines to work on core strength and stability.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1287/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1288', 'dynamic-side-plank-1288', 'Dynamic side plank', '["abs"]', '["none (bodyweight exercise)"]', 'The dynamic side plank involves positioning yourself on your side, supported on one elbow and the side of your foot, then dipping your hips up and down while keeping your body in a straight line.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1288/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1289', 'seated-dumbbell-curls-1289', 'Seated Dumbbell Curls', '["biceps"]', '["dumbbell"]', 'Seated Dumbbell Curls are an effective bicep workout that isolates the muscles by stabilizing the upper body, reducing momentum that can detract from the exercise’s effectiveness. This exercise is performed sitting down with a dumbbell in each hand, focusing on controlled movement to maximize engagement of the bicep muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sTiKyt', 'https://wger.de/en/exercise/1289/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1290', 'reverse-grip-barbell-curls-1290', 'Reverse Grip Barbell Curls', '["biceps"]', '["barbell"]', 'Hold the barbell with an overhand grip (palms facing down) approximately shoulder-width apart. Ensure your back is straight, shoulders slightly pulled back, and arms fully extended. Curl the barbell upwards towards your chest in a controlled motion, keeping your elbows close to your body. The motion should be smooth without any swinging or momentum use. Once the barbell is at chest level, pause briefly to maximize contraction in the biceps and forearms. Slowly lower the barbell back to the starting position with a controlled movement, fully extending your arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'sTiKyt', 'https://wger.de/en/exercise/1290/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1292', 'reverse-grip-pull-ups-1292', 'Reverse-grip pull-ups', '["biceps","lats","abs"]', '["pull-up bar"]', 'Pull-ups on the bar with your thumbs pointing outward.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1292/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1293', 'one-armed-push-ups-1293', 'One armed push-ups', '["chest","triceps","shoulders","abs"]', '["none (bodyweight exercise)"]', 'Perform push-ups with one hand, alternating the sides', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1293/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1294', 'single-leg-hamstring-curl-1294', 'Single-leg hamstring curl', '["hamstrings","glutes"]', '["none (bodyweight exercise)"]', 'Specifically, the muscles involved are: biceps femoris, semimembranosus and semitendinosus.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1294/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1296', 'low-cable-cross-over-nb-1296', 'Low-Cable Cross-Over - NB', '["chest","shoulders"]', '["cable machine"]', 'The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JackSparrow', 'https://wger.de/en/exercise/1296/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1298', 'high-cable-cross-tricep-extention-nb-1298', 'High-Cable Cross Tricep Extention - NB', '["triceps"]', '["cable machine"]', 'The high-cable cross tricep extension is an isolation exercise for targeting the triceps, particularly the long head. It utilizes cables and handles grasped with opposite hands, allowing for a unique pressing motion that can be effective for building tricep strength. Unlike exercises that use a straight bar or rope, this variation can be more comfortable on your wrists and elbows', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JackSparrow', 'https://wger.de/en/exercise/1298/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1302', 'jm-press-1302', 'JM Press', '["triceps","biceps","chest"]', '["barbell"]', 'The JM press keeps your shoulders stationary, relying on the elbow flexion and extension to move the weight using your triceps strength. That means you get all the benefits of the best triceps-strengthening exercises without overtaxing that delicate shoulder joint. Classic win-win!', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Epiphany8424', 'https://wger.de/en/exercise/1302/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1303', 'helms-row-1303', 'Helms Row', '["lats"]', '["dumbbell"]', 'Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats. If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1303/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1304', 'meadows-row-1304', 'Meadows Row', '["lats","biceps","abs"]', '["barbell"]', 'The Meadows row is a unilateral row performed with a landmine setup, overhand grip, and staggered stance. Lean your torso forward and grip the barbell. Rest the other forearm on the forward leg. Start this movement by driving the elbow behind you while retracting the shoulder-blade. Keep the working shoulder down. Pull toward your back hip until the elbow is level with your torso.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1304/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1307', 'front-plank-1307', 'Front Plank', '["abs","chest","quads"]', '["none (bodyweight exercise)"]', 'The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism. Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body. Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1307/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1312', 'bodyweight-squat-hd-1312', 'Bodyweight Squat HD', '["quads","calves","glutes","abs"]', '["none (bodyweight exercise)"]', 'Squat is a type of bodyweight exercise. It is one of the most popular exercises for strength and muscle growth. Squat is particularly effective for focusing on the muscles of the leg and hips. Squat are an easy exercise for beginners to do. It can help strengthen leg muscles, tighten hip muscles and burn calories to lose weight. It tightens the butt and legs. Squats are very effective for firming and strengthening your legs by acting on the gluteus,hip flexors, quadriceps, hamstrings and inner thigh muscles. Also, bodyweight squats can help shape your glutes and butt.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1312/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1314', 'jumping-jack-hd-1314', 'Jumping Jack HD', '["quads","glutes","abs"]', '["none (bodyweight exercise)"]', 'Jumping jack are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body. Jumping jack target the arm, shoulder, abdominal muscles, hip muscles and hip flexors and also work on the thighs, knee tendons and quadriceps. Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1314/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1318', 'high-knee-skips-hd-1318', 'High Knee Skips HD', '["abs","biceps","glutes","quads","triceps"]', '["none (bodyweight exercise)"]', 'You can use this exercise both as a dynamic warm-up before training and add it to your cardio training routine to burn fat. High knee skips are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body. High knee skips target the oblique, leg muscles, hip muscles and hip flexors and also work on the thighs, knee tendons, quadriceps and shoulders. Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1318/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1320', 'bench-dips-on-floor-hd-1320', 'Bench Dips On Floor HD', '["biceps","triceps","shoulders","chest"]', '["none (bodyweight exercise)"]', 'Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder. Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms. Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1320/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1324', 'bodyweight-lunge-hd-1324', 'Bodyweight lunge HD', '["quads","glutes"]', '["none (bodyweight exercise)"]', 'Bodyweight lunges are an effective calisthenic exercise for strengthening the lower body, improving balance and stability, and developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1324/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1325', 'lateral-push-off-1325', 'Lateral Push Off', '["calves","hamstrings"]', '["none (bodyweight exercise)"]', 'Push off the ground and land on one leg and regain balance before jumping to the other leg', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cleen', 'https://wger.de/en/exercise/1325/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1333', 'forearm-curls-underhand-grip-1333', 'Forearm Curls (underhand grip)', '[]', '["dumbbell"]', 'Engage the muscles Don''t use momentum Controlled movement Slow movement', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1333/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1336', 'triceps-overhead-dumbbell-1336', 'Triceps Overhead (Dumbbell)', '["triceps"]', '["dumbbell"]', 'Keep the elbows fixed Engage the muscles Don''t use momentum Controlled movement Slow movement Don''t overextend', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1336/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1338', 'shoulder-raise-dumbbell-1338', 'Shoulder Raise (Dumbbell)', '["shoulders"]', '["dumbbell"]', 'Engage the muscles Don''t use momentum Controlled movement Slow movement Always keep the arms bent Don''t overextend', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1338/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1348', 'lower-back-extensions-1348', 'Lower Back Extensions', '[]', '[]', 'Engage the muscles Lift your bottom slightly Controlled movement Slow movement Don''t use momentum Keep your upper body straight', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1348/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1353', 'dumbbell-hex-press-1353', 'Dumbbell Hex Press', '["chest","triceps","shoulders"]', '["dumbbell"]', 'Engage the muscles Position your feet wide Controlled movement Slow movement Bring the weights toward your lower chest/stomach', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1353/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1360', 'double-kettlebell-clean-and-press-1360', 'Double Kettlebell Clean and Press', '["shoulders","biceps","quads","triceps","hamstrings","glutes","lats","abs"]', '["kettlebell"]', 'Full-body muscles building exercise. This exercise provides a huge range of benefits in terms of strength & size and is extremely functional.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'm4k3r', 'https://wger.de/en/exercise/1360/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1361', 'double-kettlebell-front-squat-1361', 'Double Kettlebell Front Squat', '["glutes","quads","hamstrings","calves","abs"]', '["kettlebell"]', 'The kettlebell front squat is a compound, multi-joint exercise that works several muscle groups.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'm4k3r', 'https://wger.de/en/exercise/1361/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1363', 'blackroll-1363', 'Blackroll', '[]', '[]', 'Controlled movements Slow movements Don''t use momentum', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1363/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1366', 'dumbbell-split-squat-1366', 'Dumbbell Split Squat', '["glutes","quads","hamstrings","calves"]', '["dumbbell"]', 'Controlled execution No momentum Execute slowly', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1366/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1370', 'dumbbell-deadlift-1370', 'Dumbbell Deadlift', '["hamstrings","glutes","quads"]', '["dumbbell"]', 'Controlled execution Don''t use momentum Slow execution', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1370/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1372', 'triceps-dips-assisted-1372', 'Triceps Dips (Assisted)', '["triceps","chest"]', '[]', 'Assisted triceps dips is a gym work out exercise that targets triceps and also involves chest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'matpn', 'https://wger.de/en/exercise/1372/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1373', 'box-jumps-1373', 'box jumps', '["glutes","calves"]', '["none (bodyweight exercise)"]', 'Jump from a standing position onto the box, stretch your body, then step down again (do not jump)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tekknokrat@gmx.de', 'https://wger.de/en/exercise/1373/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1374', 'rotary-torso-machine-1374', 'Rotary Torso Machine', '["abs"]', '[]', 'Slow and Steady Not too much weight', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '6LXBO', 'https://wger.de/en/exercise/1374/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1376', 'recumbent-bike-1376', 'Recumbent Bike', '["hamstrings","calves","glutes","quads"]', '[]', 'For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'pera_perkan', 'https://wger.de/en/exercise/1376/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1377', 'torso-twist-1377', 'Torso Twist', '["abs"]', '["none (bodyweight exercise)"]', 'Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'brucem', 'https://wger.de/en/exercise/1377/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1378', 'cable-lateral-raises-single-arm-1378', 'Cable Lateral Raises (Single Arm)', '["shoulders"]', '["cable machine"]', 'The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders. Position a cable at the lowest position possible and attach a single handle. Reach across your body and grab the handle with a neutral grip. Keep the elbow slightly bent and pull the handle across your body and raise laterally. Slowly lower the handle back to the starting position under control.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1378/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1380', 'band-pull-aparts-1380', 'Band pull-aparts', '[]', '["resistance band"]', 'Hold the band with your arms extended in front of you at shoulder height. Keep your elbows slightly bent but fixed throughout the movement. Pull the band apart by spreading your arms until the band touches or comes close to your chest. Slowly bring your arms back to the starting position, controlling the tension on the band.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'schwolfar', 'https://wger.de/en/exercise/1380/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1381', 'upper-back-1381', 'Upper Back', '["shoulders","biceps","lats"]', '[]', 'Upper Back is suitable for building up the core muscles with a special focus on the deltoid and rhomboid muscles and the upper back muscles', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'phpi', 'https://wger.de/en/exercise/1381/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1384', 'pullover-machine-1384', 'Pullover Machine', '["lats","chest","triceps"]', '[]', 'Pullover machine, sitting, elbows on pads', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Paul@Chemistry', 'https://wger.de/en/exercise/1384/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1387', 'hamstring-kicks-1387', 'Hamstring Kicks', '["hamstrings","glutes"]', '["none (bodyweight exercise)"]', 'Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1387/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1388', 'single-leg-rdl-1388', 'Single Leg RDL', '["hamstrings","glutes"]', '["none (bodyweight exercise)"]', 'Stand upright and hold weights in both hands if using loads. Brace your core and lift one leg off the ground. Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips. Lower until you feel a stretch in your standing leg''s hamstring, then return to standing position. Repeat on both sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1388/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1390', 'toe-touch-1390', 'Toe Touch', '["hamstrings","glutes","calves"]', '["none (bodyweight exercise)"]', 'Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1390/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1391', 'elephant-walks-1391', 'Elephant Walks', '["hamstrings","calves"]', '["none (bodyweight exercise)"]', 'Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1391/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1392', 'good-morning-1392', 'Good Morning', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1392/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1393', 'single-leg-hamstring-stretch-1393', 'Single Leg Hamstring Stretch', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1393/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1394', 'sit-reach-1394', 'Sit & Reach', '["hamstrings"]', '["gym mat"]', 'Sit on the ground with your legs extended straight in front of you. Reach both hands forward, trying to reach past your toes or as far as you can go. Return to the starting position and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1394/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1395', 'crossbody-leg-swings-1395', 'Crossbody Leg Swings', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1395/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1396', 'standing-pancake-1396', 'Standing Pancake', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1396/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1397', 'standing-pancake-good-morning-1397', 'Standing Pancake Good Morning', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1397/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1398', 'hamstring-chokes-1398', 'Hamstring Chokes', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Sit on the ground and bend one leg, bringing your knee toward you. Place your hand behind your hamstring and gently pull your leg toward your chest, feeling a stretch in the back of your thigh. Straighten your leg, extending up toward the ceiling.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1398/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1399', 'roll-down-1399', 'Roll Down', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Stand with your feet hip-width apart and slowly roll your upper body forward, one vertebra at a time, until your hands touch the ground or as far as you can comfortably go. Roll back up to the starting position in the same controlled manner.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1399/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1400', 'crossbody-hamstring-stretch-1400', 'Crossbody Hamstring Stretch', '["hamstrings"]', '["none (bodyweight exercise)"]', 'While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1400/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1406', 'plank-to-elbow-extension-1406', 'Plank-to-Elbow Extension', '["shoulders","abs","triceps","chest"]', '["none (bodyweight exercise)"]', 'The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1406/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1407', 'cossack-squat-1407', 'Cossack squat', '["glutes","quads","calves","abs"]', '[]', 'The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1407/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1408', 'wall-sit-1408', 'Wall-sit', '["glutes","quads","calves","abs"]', '[]', 'The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1408/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1409', 'dragon-flag-1409', 'Dragon-flag', '["abs","shoulders","glutes","lats","triceps"]', '[]', 'Keep your body completely rigid throughout the movement, avoiding sagging in your lower back. Use a firm grip to stabilize your upper body. Start with simpler versions (such as with bent knees) to build strength and control.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1409/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1410', 'plank-with-alternating-leg-lift-1410', 'Plank with Alternating Leg Lift', '["glutes"]', '["none (bodyweight exercise)"]', 'In a plank position, lift one leg alternately.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1410/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1411', 'heel-touches-1411', 'Heel Touches', '["abs"]', '["none (bodyweight exercise)"]', 'Starting Position: Lie on your back on an exercise mat. Bend your knees, keeping your feet flat on the floor and hip-width apart. Place your arms along your sides, palms facing inward, just off the floor. Engage Core: Lift your head, shoulders, and upper back slightly off the ground. Keep your neck neutral and chin slightly tucked. Perform the Movement: Side-bend to the right, reaching your right hand toward your right heel. Return to the center, then side-bend to the left, reaching your left hand toward your left heel. Continue alternating sides in a controlled manner. Breathing: Exhale as you reach toward your heel and inhale as you return to the center.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1411/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1412', 'bicycle-crunches-1412', 'bicycle crunches', '["abs"]', '["none (bodyweight exercise)"]', 'Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1412/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1414', 'hack-squats-1414', 'Hack Squats', '["quads","hamstrings","calves","glutes"]', '[]', 'Hack squats target the lower body and are performed on a hack squat machine or with a barbell. For the machine variation, position yourself on the platform with your shoulders under the pads and feet slightly forward. Push through your heels to lift the weight, then bend your knees to lower the platform in a controlled motion until your thighs are parallel to the ground. Push back up to the starting position. For the barbell variation, hold the bar behind your legs with your arms extended and perform a squat-like motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1414/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1415', 'dumbbell-crunches-1415', 'Dumbbell Crunches', '["abs"]', '["dumbbell"]', 'Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1415/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1424', 'biceps-curl-machine-1424', 'Biceps Curl Machine', '["biceps"]', '[]', 'The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1424/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1425', 'toe-taps-1425', 'Toe Taps', '["abs"]', '["none (bodyweight exercise)"]', 'Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1425/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1426', 'standing-side-crunches-1426', 'Standing Side Crunches', '["abs"]', '["none (bodyweight exercise)"]', 'Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1426/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1429', 'dumbbell-shoulder-rotations-1429', 'Dumbbell Shoulder Rotations', '["shoulders"]', '["dumbbell"]', 'Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility. External Rotation : Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position. Internal Rotation : Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1429/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1430', 'plate-pinch-hold-1430', 'Plate Pinch Hold', '["shoulders"]', '[]', 'The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1430/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1433', 'reverse-wood-chops-1433', 'Reverse Wood Chops', '["glutes","lats","shoulders","biceps","quads","abs"]', '["none (bodyweight exercise)"]', 'Attach a looping resistance band to a rack below knee height Grip the other end of the band like holding a baseball bat with both hands Stretch the band facing it Start with your hands at the side of your hips, knees bent Rotate your hips while moving your hands towards over the top of your opposite shoulder Imagine the motion as striking a baseball with a bat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1433/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1434', 'lat-pull-db-1434', 'Lat Pull DB', '["lats","glutes"]', '["dumbbell"]', 'Bend upper body forward Move dumbbells near your body with slightly bent arms towards your back', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1434/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1435', 'scapula-pulls-1435', 'Scapula Pulls', '["lats"]', '["pull-up bar"]', 'Hang straight on a pull-up bar Pull shoulder blades together, moving the body slightly up', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1435/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1436', 'pin-bench-press-bb-1436', 'Pin Bench Press BB', '["chest","triceps"]', '["barbell"]', 'Set security pins to about the height of your sticking point Lower the bar, rest on the pins for 1s while holding tension Move bar up with maximum force', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1436/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1437', 'pin-squat-1437', 'Pin Squat', '["hamstrings","glutes","quads","abs"]', '["barbell"]', 'Set security pins to about the height of your sticking point Lower the bar, rest on the pins for 2s keeping tension Stand up with maximum force', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1437/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1438', 'clean-1438', 'Clean', '["glutes","quads","hamstrings","lats","abs"]', '["barbell"]', 'Regular olympic lift clean. Pull bar from ground, catch on shoulders performing a front squat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1438/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1439', 'pin-ohp-1439', 'Pin OHP', '["shoulders","triceps"]', '["barbell"]', 'Set security pins to the height of your lower chin Rest bar on pins keeping tension Raise bar over head', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1439/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1440', 'push-ohp-1440', 'Push OHP', '["shoulders","glutes","quads","triceps"]', '["barbell"]', 'Rest bar in front on your shoulders Bend knees while keeping upper body straight Extend legs pushing the bar overhead with force', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1440/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1441', 'incline-ohp-db-1441', 'Incline OHP DB', '["shoulders","triceps"]', '["dumbbell"]', 'Sit on a bench with 45° incline Ellbows 45° out Move dumbbells down until upper arms are parallel to shoulders Move dumbbells up, meeting overhead', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1441/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1442', 'kreis-press-db-1442', 'Kreis Press DB', '["shoulders","biceps","chest","abs","triceps"]', '["dumbbell"]', 'Sit on a bench with 45° incline Hold dumbbells overhead Move dumbbells down as if doing overhead press Rotate dumbbells palms facing up and extend your arms in front of your body Move hands together until dumbbells meet, keep arms extended Reverse the motion until dumbbells are overhead again This is one repetition', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1442/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1443', 'shoulder-raise-side-and-front-db-1443', 'Shoulder Raise Side and Front DB', '["shoulders"]', '["dumbbell"]', 'Stand while holding dumbbells beside body Keep arms almost fully extended Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down Lower dumbbells beside body, palms facing inwards Immediately raise dumbbells in front of your body until shoulder height, palms facing down Down again This is one repetition', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1443/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1445', 'jerk-ol-1445', 'Jerk OL', '["shoulders","glutes","quads","triceps"]', '["barbell"]', 'Olympic lift jerk Hold bar in front on shoulders like push press Bend and extend knees pushing bar up while diving under the bar Catch bar overhead with straight arms using lunge Move feet parallel while holding bar in lockout', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1445/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1446', 'clean-and-jerk-ol-1446', 'Clean and Jerk OL', '["shoulders","hamstrings","glutes","quads","lats","abs","triceps"]', '["barbell"]', 'Olympic lift clean and jerk. Combination of clean and jerk in one motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1446/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1447', 'snatch-ol-1447', 'Snatch OL', '["shoulders","hamstrings","glutes","quads","lats"]', '["barbell"]', 'Olympic lift snatch Pull barbell from ground to overhead lockout using a wide grip and overhead squat. Move bar slowly until cleared knees then explosively extend hips, pull bar up and dive under the bar Catch bar overhead with straight arms Push head forward during lockout', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1447/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1448', 'seated-w-curl-1448', 'Seated W Curl', '["biceps"]', '["bench","dumbbell"]', 'Sit on bench with 60° incline Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended Move dumbbells up using only biceps and without momentum', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1448/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1449', 'climbmill-1449', 'ClimbMill', '["quads","hamstrings","glutes"]', '[]', 'The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1449/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1450', 'cobra-stretch-1450', 'Cobra Stretch', '["abs","chest"]', '["none (bodyweight exercise)"]', 'The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1450/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1451', 'torso-rotation-stretch-1451', 'Torso rotation stretch', '["chest"]', '["none (bodyweight exercise)"]', 'The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated. Standing Variation : Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side. Seated Variation : Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1451/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1452', 'knee-to-chest-stretch-1452', 'Knee to Chest Stretch', '["glutes","hamstrings"]', '["none (bodyweight exercise)"]', 'The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15-30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1452/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1455', 'towel-superman-1455', 'Towel Superman', '["lats","shoulders"]', '[]', 'In this exercise, you lie flat on your stomach, hold a towel with your arms extended in front of you, and pull it apart to create tension. Then, you move it forward and back under your stomach. This exercise targets the back and shoulder muscles as well as core stability.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Yderkone', 'https://wger.de/en/exercise/1455/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1457', 'cable-press-around-1457', 'Cable Press Around', '["shoulders","chest","triceps","biceps"]', '["cable machine"]', 'Set the cable pulley at chest height and attach a D-handle bar. Grab the handle with a neutral grip and hold it next to your chest with your elbow fully flexed and tight to your side. Turn away from the pulley so your torso is at 45 degrees. Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance. While keeping your chest proud, extend your elbow at 45 degrees across your midline while keeping your arm parallel to the floor. Stop shy of lockout and contract your chest at the top of the range of motion (ROM).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1457/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1458', 'cross-body-cable-y-raise-1458', 'Cross-Body Cable Y-Raise', '["shoulders","lats"]', '["cable machine"]', 'Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1458/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1461', 'no-leg-drive-dumbbell-chest-press-1461', 'No Leg Drive Dumbbell Chest Press', '["chest","shoulders","triceps"]', '["bench","dumbbell"]', 'Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1461/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1462', 'punches-1462', 'punches', '["shoulders","triceps"]', '["none (bodyweight exercise)"]', 'stand stable and throw normal straight punches', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lh1701', 'https://wger.de/en/exercise/1462/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1463', 'dumbbell-underhand-dead-row-1463', 'Dumbbell Underhand Dead Row', '["biceps","lats"]', '["dumbbell"]', 'The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps. Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent. Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees. Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level. Slowly lower to the starting position and repeat. Keep your back flat all the time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1463/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1464', 'pause-hack-squats-1464', 'Pause Hack Squats', '["quads","hamstrings","calves","glutes"]', '[]', 'Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1464/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1465', 'spider-curl-1465', 'Spider Curl', '["biceps"]', '["incline bench"]', 'To get the most out of DB Spider Curls, you need an adjustable weight bench set at a 45-degree incline. This inclined position allows your arms to hang freely, putting them in an extended start position with elbows slightly in front of your torso, which is the key to maintaining low-level isometric tension throughout the movement pattern. Lie face-down on an adjustable weight bench with your chest fully supported, holding a pair of dumbbells. Keep a neutral head position and don’t crane your neck. Let your arms hang straight down with your palms facing forward (for a standard Spider Curl) or palms facing inward for a Hammer Curl exercise variation. Keep a stable foot position on the floor to maintain balance and control. Start the curl motion by flexing your biceps muscles and lifting the pair of dumbbells or curl bar toward your shoulders. Keep your elbow flexion controlled. Your arms should stay locked in position with no unnecessary movement. Squeeze hard at the top for 1-2 seconds. This is where maximum tension hits the biceps muscle fibers. Lower the weight under control for 3-4 seconds to keep muscles under tension for the entire range of motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1465/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1466', 'calf-raise-using-hack-squat-machine-1466', 'Calf Raise using Hack Squat Machine', '["calves"]', '[]', 'Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1466/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1467', 'incline-close-grip-barbell-bench-press-1467', 'Incline Close Grip Barbell Bench Press', '["triceps","shoulders","chest"]', '["barbell"]', 'Narrower grip than regular bench press, just outside shoulder width.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1467/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1468', 'floor-skull-crusher-1468', 'Floor Skull Crusher', '["triceps"]', '["sz-bar"]', 'Allowing you to safely load more weight than a regular skull crusher, lie on the floor and rest the weight on the floor in between each repetition.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1468/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1469', 'bent-over-cable-flye-1469', 'Bent over Cable Flye', '["chest"]', '["cable machine"]', 'Holding your upper body at an approximate 105° angle.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1469/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1470', '1-arm-half-kneeling-lat-pulldown-1470', '1-Arm Half-Kneeling Lat Pulldown', '["lats"]', '["cable machine"]', 'Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1470/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1471', 'kroc-row-1471', 'Kroc Row', '["lats"]', '[]', 'Dumbbell rows with looser technique but heavier weight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1471/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1472', 'cable-shrug-in-1472', 'Cable Shrug-In', '[]', '["cable machine"]', 'Attach a D-handle to each of two low pulleys, stand between them and shrug your shoulders up and inwards, using your upper traps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1472/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1473', 'reverse-cable-flye-1473', 'Reverse Cable Flye', '["shoulders"]', '["cable machine"]', 'Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1473/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1474', 'w-raise-1474', 'W-Raise', '["abs"]', '["none (bodyweight exercise)"]', 'This challenging exercise is a variation of reverse crunches that is made up of three parts in which we’re basically drawing an upside down ‘W’ with our legs. Start position is lying face up flat on the floor with legs extended at the low point of the outer leg of the ‘W’. Keeping a strong core and legs straight, go up, rise your hips and then slowly lower your legs down halfway. Then, lifting your legs back up to the top, rise your hips again, maintaining that straight line, use your core strength to finally come back all the way down to the other outer leg of the W. Then you reverse the ‘W’ to return to the start.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1474/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1475', 'black-widow-knee-slides-1475', 'Black Widow Knee Slides', '["abs"]', '[]', 'In this bottom-up rotation exercise movement, you’ll cross your knee over and drive it into that opposite elbow. Start in high plank position (or tabletop position) with hands directly beneath your shoulders. Lift the left knee toward the right arm and slide it up the forearm to get more of that posterior pelvic tilt and engagement of the abdominal muscles. Then do the opposite side, bringing your right knee toward your left hand.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1475/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1476', 'butterfly-sit-up-1476', 'Butterfly Sit Up', '["abs"]', '["none (bodyweight exercise)"]', 'In this midrange exercise your arm muscles provide you with a little bit of momentum to help to get you off the ground. You also open them up in overhead position which engages the upper back. Start lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using your ab muscles, bring your upper body off the ground as you open your arms into goal post position, then slowly lower yourself back down to return to starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1476/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1477', 'seated-corkscrew-1477', 'Seated Corkscrew', '["abs"]', '["none (bodyweight exercise)"]', 'To do this abs and obliques exercise, start with your hands back behind your body and bring your knees in and across, really trying to contract the obliques. Then extend your legs back out to starting position and repeat toward the opposite side of the abs. Beginners might find that they can’t even get through the first 45 seconds of this challenging reverse crunches variation. That’s ok because it gives you a place to start and something to improve upon.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1477/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1478', 'levitation-crunch-1478', 'Levitation Crunch', '["abs"]', '["none (bodyweight exercise)"]', 'For this top down movement, we’re trying to move the upper torso without moving the lower torso. Start lying on the ground with feet flat on the floor and crossed arms above your head with hands behind head. Lift upper body up and clear your shoulder blades off the ground and then hold and pause at the top for a one or two count. Try to make the upper abs work and hold that contraction for 10 good quality reps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1478/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1479', 'sit-up-elbow-thrust-1479', 'Sit Up Elbow Thrust', '["abs"]', '["none (bodyweight exercise)"]', 'This is a top down rotation movement, and it’s a bit more explosive, too. Lying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back to center and then finally lower yourself down. Then hit the other side.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1479/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1480', 'lying-triceps-extensions-1480', 'Lying Triceps Extensions', '["triceps"]', '["barbell","dumbbell"]', 'Starting position for this practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart. Begin with arms over your upper chest and elbows bent back at about a 45-degree angle. First bend at the elbows and then allow the upper arm to drop back, bringing the barbell/dumbbells behind your head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to ensure that you’re targeting the triceps. Keep the shoulder blades tucked under, the elbows tight in toward your head and your core active during this entire movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1480/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1481', 'drag-pushdown-1481', 'Drag Pushdown', '["triceps"]', '["cable machine","sz-bar"]', 'Starting position for this rope pushdown is standing facing a cable machine with the handles of a rope attachment in both hands and feet shoulder width apart. Hinge forward slightly at the hips maintaining an upright chest and bring the shoulders and elbows behind the body so that when you push down on the cable attachments, you can get a fully contracted triceps long head. Drag the cable machine rope attachment as close to the body as possible and straighten your elbows until lockout.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1481/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1482', 'dumbbell-cheat-curl-1482', 'Dumbbell Cheat Curl', '["biceps"]', '["dumbbell"]', 'Starting position is standing with feet shoulder width apart. Hands should take an underhand or supinated grip on the dumbbells holding them with hands shoulder width apart. Keeping elbows tucked into your sides throughout the entire movement, use momentum to curl the dumbbells, squeezing your biceps at the top of the movement. Slowly lower to return to the starting position. Keep the core tight throughout the exercise. Cheating through the concentric curling portion of this challenging exercise gives us a great opportunity to increase time under tension and create eccentric overload with heavier weight when we lower.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1482/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1483', 'bizeps-curls-trifecta-1483', 'Bizeps Curls Trifecta', '["biceps"]', '["dumbbell"]', 'This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You alternate between three curl variations that each accomplish different goals, and you’ll keep the set going beyond the usual 8-12 rep range which gives us that intensity. For the Supinated Cross Body Curl, supinate the forearm with palms facing toward the ceiling and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder. For the Pronated Cross Body Curl, pronate the forearm with palms facing toward the floor (pronated grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder. For the No Money Curl, you’ll curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1483/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1484', 'omni-cable-cross-over-1484', 'Omni Cable Cross-over', '["chest"]', '["cable machine","sz-bar"]', 'Adjust the weights based on the motion. When pulling from top to bottom, increase the weight by 20% to 40% more than the bottom-to-top motion. This accounts for the fact that when operating from top down, the upper chest muscles are naturally weaker than the lower chest muscles. So, adjust your weight stack to compensate. Position one cable at a high setting and the other at the lowest level setting. Get into a staggered stance in between the cable towers. For the cable set low, pull it upward and across your body. This effectively targets the upper chest. For the cable set high, draw it downward and across your body. This will primarily engage the lower chest. Once you’re done, swap the positions of the cables. Change the previously high cable to the lowest position and vice versa. Repeat the exercise sequence, ensuring you’re targeting both chest regions effectively.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1484/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1485', 'rocking-triceps-pushdown-1485', 'Rocking Triceps Pushdown', '["triceps"]', '["cable machine","sz-bar"]', 'Set your feet below the rope and lean your upper body towards the rope. Set one foot back. Push down the rope and lean your entire body back onto the rear foot as you push down to get your hands behind your body. Don''t forget to bring your chest to the front during the pushdown. As you release the rope slowly, lean your body back onto the front foot.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1485/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1486', 'alternating-high-cable-row-1486', 'Alternating High Cable Row', '["lats"]', '["cable machine"]', 'Start by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot. Pull your elbow joint in toward the torso twisting slightly and perform a single-arm row. Engage the lats as you twist. Return to the starting position with cable pulley and left foot and grab the cable pulley handle in the right hand. Repeat this motion on the opposite side with your right foot stepped back.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1486/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1487', 'hyper-y-w-combo-1487', 'Hyper Y W Combo', '["lats"]', '[]', 'Use a glute-ham raise or a stability ball for this exercise and a light weight plate in each hand. Raise your torso to form a straight line with your legs and raise the arms outward slightly beyond a 90-degree angle into a W position to hit the rotator cuff muscles, and then lower back to the starting position. Then raise up again with arms in a Y position to activate the lower traps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1487/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1489', 'plank-jacks-1489', 'Plank Jacks', '["glutes","abs","calves","quads"]', '["none (bodyweight exercise)"]', 'Jumping jacks from the plank position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'jayninja', 'https://wger.de/en/exercise/1489/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1490', 'lying-triceps-kickback-1490', 'Lying Triceps Kickback', '["triceps"]', '["dumbbell","incline bench"]', 'Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1490/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1492', 'high-row-1492', 'High Row', '["lats"]', '["cable machine"]', 'Kneeling down on one leg and pulling cable down while driving elbow into the lats.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aahuja', 'https://wger.de/en/exercise/1492/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1493', 'bayesian-curl-1493', 'Bayesian Curl', '["biceps"]', '["cable machine"]', 'Cable curl with the shoulder extended backwards, which puts the biceps in a stretched position at the start of the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aahuja', 'https://wger.de/en/exercise/1493/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1496', 'db-upper-chest-variation-1496', 'DB Upper Chest Variation', '["chest","shoulders"]', '["dumbbell"]', 'Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1496/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1497', 'db-underhand-bench-press-1497', 'DB Underhand bench press', '["chest","shoulders"]', '["bench","dumbbell"]', 'Underhand grip DB, perform a normal bench press movement, keeping the elbows close to the chest', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1497/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1498', 'elbows-tucked-db-bench-press-1498', 'Elbows Tucked DB Bench Press', '["triceps","chest"]', '["bench","dumbbell"]', 'Elbows Tucked DB Bench Press, chest press movement focusing on the triceps. DB stays parallel with body', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1498/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1501', 'alternative-db-gorilla-rows-1501', 'Alternative DB Gorilla rows', '["lats"]', '["dumbbell"]', 'Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1501/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1502', 'db-cross-body-hammer-curls-1502', 'DB Cross Body Hammer Curls', '["biceps"]', '["dumbbell"]', 'Hammer curl with a neutral grip, curling the dumbbell across your body towards the opposite shoulder. Works the brachialis in particular.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1502/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1503', 'dumbbell-frog-press-1503', 'Dumbbell Frog Press', '["glutes"]', '["dumbbell"]', 'Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1503/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1504', 'dumbbell-bradford-press-1504', 'Dumbbell Bradford press', '["shoulders"]', '["dumbbell"]', 'From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1504/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1508', 'high-incline-smith-machine-press-1508', 'High-Incline Smith Machine Press', '["shoulders","chest","triceps"]', '[]', 'Set the bench to a 45-60° incline. Touch the upper chest with the bar.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1508/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1509', 'cable-tricep-kickback-1509', 'Cable Tricep Kickback', '["triceps"]', '["cable machine"]', 'Grab onto the handle, and pull your elbow up and back slightly above your torso. Keep your upper arm to be parallel to the ground for the duration of the set', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1509/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1510', 'neutral-grip-lat-pulldown-1510', 'Neutral Grip Lat Pulldown', '["lats"]', '["cable machine"]', 'Lat pull downs with a neutral grip on the bar.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1510/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1511', 'kong-curl-1511', 'Kong Curl', '["biceps"]', '["dumbbell"]', 'This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view. During the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1511/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1512', 'drop-curl-1512', 'Drop Curl', '["biceps"]', '["dumbbell"]', 'Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width. Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1512/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1513', 'overhead-cable-tricep-extension-1513', 'Overhead Cable Tricep Extension', '["triceps"]', '["cable machine"]', 'Use rope handle with your back against the cable machine. Straighten your arms until they are filly extended and reverse the motion resisting on the negative.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1513/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1514', 'lateral-walk-1514', 'Lateral Walk', '["glutes"]', '["none (bodyweight exercise)"]', 'Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cozyGalvinism', 'https://wger.de/en/exercise/1514/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1515', 'leg-press-toe-press-1515', 'Leg Press Toe Press', '["calves"]', '[]', 'Move the leg press using your calves by placing your feet at the bottom of the platform.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1515/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1516', 'handstand-1516', 'Handstand', '["shoulders"]', '[]', 'Handstand free standing by pressing arms into the ground and contracting core and glutes', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Fittness69', 'https://wger.de/en/exercise/1516/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1519', 'overhead-triceps-extension-1519', 'Overhead Triceps Extension', '[]', '["sz-bar"]', 'Overhead Triceps Extension with EZ Bar - Quick Guide The overhead position emphasizes the long head of the triceps (because it''s stretched under load), the exercise does engage all three triceps heads (long, lateral, and medial) to some degree during extension. Setup : Sit on a bench (or stand) and hold an EZ bar with a narrow, overhand grip. Lift the bar overhead, arms fully extended. Keep your core tight and elbows close to your head. Execution : Slowly lower the bar behind your head by bending your elbows until they reach ~90°. Keep elbows pointed forward (not flaring out). Finish : Extend your arms back up to the starting position, squeezing your triceps at the top. Tips : Control the movement to avoid straining your shoulders. Use a moderate weight for full range of motion. Keep your back straight and avoid arching.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'benjamin.yildiz@proton.me', 'https://wger.de/en/exercise/1519/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1521', 'pendular-hack-1521', 'Pendular hack', '[]', '[]', 'Pendulum hack, made on a pendulum machine', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1521/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1523', 'sled-push-1523', 'Sled Push', '["calves","glutes","quads","shoulders","hamstrings","triceps"]', '[]', 'Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight. Stand behind the sled and grab the poles with a high-grip hand position. Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1523/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1524', 'battle-ropes-1524', 'Battle Ropes', '["hamstrings","glutes","lats","quads","abs","shoulders","biceps","chest","triceps"]', '[]', 'Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart. Brace your core and begin alternately raising and lowering each arm explosively. Keep alternating arms for three to four sets of 1 to 2 minutes.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1524/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1525', 'ball-slams-1525', 'Ball Slams', '["lats","abs","shoulders","glutes"]', '[]', 'Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture. Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive. Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down. Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1525/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1526', 'ski-machine-1526', 'Ski Machine', '["calves","lats","triceps","hamstrings","glutes","quads","abs"]', '[]', 'Start standing on the platform with your feet hip-width apart. Reach overhead to grip the handles with your palms facing in. Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees. Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended. Repeat for reps, time or distance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1526/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1527', 'pendulum-squat-1527', 'Pendulum Squat', '["quads","hamstrings","glutes"]', '["none (bodyweight exercise)"]', 'Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'schweezer', 'https://wger.de/en/exercise/1527/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1528', 'glute-drive-1528', 'Glute Drive', '["glutes","hamstrings","quads"]', '[]', 'Lie down on the back pad and strap yourself in with the waistband. Position yout feet shoulder-length apart. They should be slightly splayed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'schweezer', 'https://wger.de/en/exercise/1528/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1529', 'toes-to-bar-1529', 'Toes to bar', '["abs","lats"]', '["pull-up bar"]', 'The name "Toes to Bar" says it all: This exercise, in which you hang from a pull-up bar, involves bringing your toes toward the bar, pointing toward your face. This really works your abdominal muscles. "Toes to Bar" is popular in functional fitness programs like Freeletics and CrossFit, and is an effective exercise for six-pack training.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'florian.bussmann', 'https://wger.de/en/exercise/1529/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1530', 'lying-dumbbell-curls-1530', 'Lying Dumbbell Curls', '["biceps"]', '["bench","dumbbell"]', 'Take a dumbbell in each hand and lie backwards on a bench, similar to a classic chest press. Let your arms hang down at your sides, with the dumbbells possibly touching the floor. Now start to lift the dumbbells upwards until your forearms are perpendicular to the ceiling. Slowly lower the dumbbells until they almost touch the floor again. Keep your ellbows in place to minimize cheating.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1530/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1531', 'cable-curls-1531', 'Cable Curls', '["biceps"]', '["cable machine"]', 'Bicep Curls using cables. Can be seated or standing', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Brigade7938', 'https://wger.de/en/exercise/1531/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1536', 'delt-stretch-1536', 'Delt Stretch', '["shoulders"]', '["none (bodyweight exercise)"]', 'Stretch your deltoids for a certain period of time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1536/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1537', 'pull-up-isometric-hold-1537', 'Pull-up Isometric Hold', '["biceps","lats"]', '["pull-up bar"]', 'Hold the pull-up movement in any position', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'DiscoCop', 'https://wger.de/en/exercise/1537/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1545', 'archer-pull-up-1545', 'Archer Pull Up', '["lats","biceps"]', '[]', 'An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the "bow-drawing" position your body takes at the top.Here''s how to do it: Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip. Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down. The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling. Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control. Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Antsy6277', 'https://wger.de/en/exercise/1545/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1546', 'larsen-press-1546', 'Larsen Press', '["chest","triceps"]', '["barbell"]', 'Put your legs up on a separate Bench and press with no leg drive', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1546/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1548', 'stair-master-1548', 'Stair Master', '["hamstrings","calves","glutes","quads"]', '["none (bodyweight exercise)"]', 'cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MisterPinnacle', 'https://wger.de/en/exercise/1548/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1551', 'push-up-1551', 'Push-Up', '["chest","shoulders","abs","triceps"]', '["none (bodyweight exercise)"]', 'The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength. Instructions: Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels. Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward. Lower until your chest nearly touches the ground while maintaining a neutral spine. Push through your palms to return to the starting position, fully extending your arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1551/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1554', 'clap-push-up-1554', 'Clap Push-UP', '["chest","shoulders","abs","triceps"]', '["none (bodyweight exercise)"]', 'The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep. Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged Lower your body explosively and push off the ground with enough force to lift your hands. Quickly clap your hands together at chest level before returning them to the floor. Land with soft elbows to absorb the impact and immediately move into the next rep', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1554/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1556', 'devil-s-press-1556', 'Devil’s Press', '["shoulders","glutes","chest","hamstrings","lats","triceps"]', '["dumbbell"]', 'The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning. Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells. Explosively jump your feet forward and swing the dumbbells between your legs. Drive the dumbbells overhead in one continuous motion, locking out your arms. Lower the dumbbells with control to return to the starting position and repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1556/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1567', 'alternating-dumbbell-hammer-curl-1567', 'Alternating dumbbell hammer curl', '["biceps"]', '["dumbbell"]', 'Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1567/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1572', 'bird-dog-1572', 'Bird Dog', '["abs","shoulders","glutes"]', '["none (bodyweight exercise)"]', 'The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control. Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral. Extend your right arm forward and left leg backward simultaneously, keeping hips square. Pause briefly at full extension while engaging your core and glutes. Return to the starting position and repeat on the opposite side', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1572/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1573', 'ab-wheel-1573', 'Ab wheel', '["abs"]', '["none (bodyweight exercise)"]', 'Starting Position : Kneel on the floor with the ab wheel in front of you. Grip the Wheel : Hold the handles firmly. Roll Out : Slowly roll the wheel forward, extending your body while keeping your core tight. Return : Pull the wheel back towards your knees, maintaining tension in your core.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'lhegedus', 'https://wger.de/en/exercise/1573/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1574', 'schwimmen-1574', 'Schwimmen', '[]', '[]', '800m Schwimmen in 20 Minuten', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'delta@romeo', 'https://wger.de/en/exercise/1574/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1575', 'standing-dowel-shoulder-press-1575', 'Standing Dowel Shoulder press', '[]', '["barbell"]', 'Mobility - prone dowel press or standing dowel shoulder press alternating between front andback', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1575/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1576', 'snap-down-1576', 'Snap Down', '["hamstrings","glutes","quads","calves","abs"]', '[]', 'Begin in a standing position with your arms up over your head and your toes pushing into the ground raising your heels up becoming as tall as you can. From this position, perform a small hop with both feet slightly coming off of the ground. As you land, bend your knees and begin to hinge forward at your hips absorbing the landing. Return to the starting position and repeat. You should feel the muscles in your lower body working. Start with your arms and knees fully straightened out. Keep a stable balance as you land and briefly hold that end position, don’t go too fast and become off balanced. Keep your chest up. For a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1576/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1577', 'bretzel-stretch-1577', 'Bretzel stretch', '["glutes","hamstrings","lats","chest"]', '["none (bodyweight exercise)"]', 'How to Perform the Bretzel Stretch Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground. Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground. Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body. Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest. Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1577/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1578', 'hip-hinge-1578', 'Hip hinge', '["hamstrings","glutes","calves","quads","abs"]', '["barbell"]', 'Hip Hinge Exercise Description The hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge: Starting Position: Stand with your feet hip-width apart and a slight bend in your knees. Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up. Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings. Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1578/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1579', 'bronco-1579', 'Bronco', '[]', '["none (bodyweight exercise)"]', 'Fitness test for rugby. 5 x shuttle runs of 20m, 40m, and 60m (20yd, 45yd, 65yd/far 45yd mark) Complete as fast as possible', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MU5H', 'https://wger.de/en/exercise/1579/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1580', 'perpendicular-unilateral-landmine-row-1580', 'Perpendicular Unilateral Landmine Row', '["shoulders"]', '["barbell"]', 'Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1580/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1581', 'trap-press-1581', 'Trap press', '[]', '["barbell","bench","dumbbell"]', 'Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1581/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1582', 'side-laying-interior-rotation-1582', 'Side-laying interior rotation', '[]', '["barbell","bench","dumbbell"]', 'Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1582/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1583', 'supine-press-1583', 'Supine press', '[]', '["barbell","bench"]', 'Take a close grip and push perpendicular to the bench. Keep back flat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1583/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1584', 'march-or-jog-in-place-1584', 'March or jog in place', '["hamstrings","calves","glutes","quads","shoulders","biceps","abs","triceps"]', '["none (bodyweight exercise)"]', 'Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1584/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1589', 'leg-and-hip-stretch-1589', 'Leg and hip stretch', '["hamstrings","glutes","quads","lats"]', '["none (bodyweight exercise)"]', 'Gentle movements to improve the flexibility of the lower body and release tension in the hips.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1589/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1590', 'arm-and-neck-stretch-1590', 'Arm and neck stretch', '["shoulders","triceps","lats"]', '["none (bodyweight exercise)"]', 'Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1590/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1591', 'deep-breathing-standing-or-seated-1591', 'Deep breathing (standing or seated)', '["abs"]', '["none (bodyweight exercise)"]', 'A conscious breathing technique to improve oxygenation, reduce stress and connect with the present moment.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1591/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1592', 'guided-or-free-meditation-1592', 'Guided or free meditation', '[]', '["none (bodyweight exercise)"]', 'A mental mindfulness exercise that helps reduce anxiety, improve focus and enhance overall well-being.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1592/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1593', 'smith-machine-split-squat-1593', 'Smith Machine Split Squat', '["hamstrings","quads"]', '["barbell"]', 'The "Smith Machine Split Squat" is a strength exercise performed on the Smith machine, ideal for targeting the legs and glutes. It involves placing one foot forward and the other back, lowering the body until the front thigh is parallel to the ground while the bar slides vertically along the machine. This exercise helps improve stability, correct muscle imbalances, and reduces stress on the back, providing a safe environment for strength training.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'workout@rooven.anonaddy.me', 'https://wger.de/en/exercise/1593/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1602', 'dumbbell-scaption-1602', 'Dumbbell Scaption', '["shoulders"]', '["dumbbell"]', 'Starting position: Stand upright with your feet shoulder-width apart. Hold a dumbbell in each hand with a neutral grip (palms facing each other). Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back. Execution: Slowly raise the dumbbells forward and slightly to the side, at about a 30-45° angle from your body (between a front raise and a lateral raise). Lift until your arms are about shoulder height (do not go overhead). Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers. Lower the dumbbells back down under control to the starting position. Breathing: Inhale as you lower the dumbbells. Exhale as you lift them. Common mistakes: Using dumbbells that are too heavy (causing jerky movements). Lifting above shoulder height (puts unnecessary stress on the shoulder joint). Arching the lower back instead of keeping the movement controlled at the shoulders. Purpose of the exercise: Activates the lower trapezius, serratus anterior, and scapular stabilizers. Helps correct posture and improve shoulder balance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'zdelko', 'https://wger.de/en/exercise/1602/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1603', 'leg-curl-with-elastic-1603', 'Leg curl with elastic', '["calves","hamstrings"]', '["resistance band"]', 'Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1603/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1604', 'sliding-lateral-lunge-1604', 'Sliding Lateral Lunge', '["hamstrings","glutes","quads","calves"]', '["barbell"]', 'Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'RiccaBaro', 'https://wger.de/en/exercise/1604/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1605', 'copenhagen-adduction-exercise-1605', 'Copenhagen Adduction Exercise', '["glutes","quads"]', '["bench"]', 'Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'RiccaBaro', 'https://wger.de/en/exercise/1605/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1606', 'arm-raises-t-y-i-1606', 'Arm Raises (T/Y/I)', '["shoulders","lats"]', '["none (bodyweight exercise)"]', 'Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back: T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape. Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape. I Raise: Raise your arms straight overhead, close together, forming an “I” shape. Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'WiNNiE', 'https://wger.de/en/exercise/1606/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1607', 'typewriter-pull-ups-1607', 'Typewriter Pull-ups', '["biceps","lats"]', '["none (bodyweight exercise)"]', 'Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tenebrizz', 'https://wger.de/en/exercise/1607/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1608', 'bodyweight-biceps-curl-1608', 'Bodyweight Biceps Curl', '["biceps"]', '["none (bodyweight exercise)"]', 'Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tenebrizz', 'https://wger.de/en/exercise/1608/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1612', 'kettlebell-sumo-deadlift-1612', 'kettlebell sumo deadlift', '["hamstrings","glutes","quads"]', '["kettlebell"]', 'Place your feet wider than shoulder-width apart, pointing your toes outward. Keep your back straight, shoulders back, and chest up. The knees must follow the same direction as the toes and not move forward. When going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise..', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1612/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1613', 'rubber-band-glute-kickback-1613', 'rubber band glute kickback', '["glutes"]', '["resistance band"]', 'A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1613/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1615', 'treadmill-cardio-1615', 'Treadmill Cardio', '[]', '["none (bodyweight exercise)"]', 'It''s a cardiovascular workout performed on a treadmill to improve endurance, burn calories, and promote heart health. It offers multiple benefits, such as the ability to easily adjust speed and incline, allowing for a variety of workouts, from hill walking to high-intensity interval training (HIIT) and tempo runs. To optimize results, it''s important to vary your workouts. Benefits of Treadmill Cardio: Improved Cardiovascular Health: Regular aerobic exercise on a treadmill strengthens the heart and lungs, which can help prevent heart disease. Weight Loss: By burning calories, treadmill training can be an effective tool for weight loss and maintaining a healthy weight. Muscle Strengthening: It strengthens the muscles in the legs and glutes, helping to prevent muscle loss, which is especially important with age. Training Flexibility: Allows you to vary speed, incline, and intervals, making your workout more dynamic and adaptable to different fitness levels. Types of Treadmill Training: Hill Walking: Increasing the incline of the treadmill and walking at a brisk pace can improve endurance and work your leg muscles. Endurance Jog: A run at a comfortable, steady pace that keeps your heart rate in a target zone (such as Zone 2) to build endurance. Interval Training: Alternating periods of high intensity (fast running) with periods of low intensity (easy walking or jogging) to maximize calorie burn and cardiovascular improvement. Tempo Run: A run at a steady, sustained pace that is slightly faster than a normal jog, which challenges your ability to sustain a more intense effort for an extended period.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1615/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1616', 'dumbbell-donkey-kick-1616', 'Dumbbell donkey kick', '["hamstrings","glutes"]', '["dumbbell"]', 'The dumbbell donkey kick is an effective exercise for working the glute and hamstring muscles. This exercise is usually performed on all fours, using a dumbbell to add resistance. The steps for performing it correctly are described below. Starting position: Get on all fours on a mat, with your hands aligned under your shoulders and your knees aligned under your hips. Placing the dumbbell: Take a dumbbell and place it behind the knee of the leg you are going to lift. Make sure it is held securely to prevent it from falling during the exercise. Exercise: Inhale and, as you exhale, lift the leg with the dumbbell upward, keeping the knee bent at a 90-degree angle. Raise the leg until it is parallel to the floor, feeling the contraction in the glutes. Hold the position for one second at the top and then slowly lower the leg back to the starting position. Repetitions: Perform 10 to 15 repetitions per leg, making sure to maintain good form throughout the exercise. Sets: Complete 2 to 3 sets, depending on your fitness level.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1616/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1618', 'stationary-bike-cardio-1618', 'Stationary bike cardio', '[]', '["none (bodyweight exercise)"]', 'Benefits of Stationary Bike Cardio Stationary bike cardio is an excellent form of exercise that offers multiple benefits for health and well-being. Here are some of the most notable ones: Improved Cardiovascular Health Strengthens the heart: Regular exercise helps improve the heart''s efficiency and reduce the risk of cardiovascular disease. Increases circulation: It improves blood flow, which can help lower blood pressure. Calorie Burning and Weight Loss Efficient for burning calories: Depending on the intensity, you can burn between 400 and 600 calories per hour. Helps with weight loss: Combined with a balanced diet, stationary bike cardio can be effective for losing weight. Muscle Strengthening Tones the legs: It mainly works the leg muscles, including the quadriceps, hamstrings and calves. Improves muscular endurance: Over time, you can increase the endurance and strength in your legs. Mental Health Benefits Reduces stress: Exercise releases endorphins, which can improve your mood and reduce stress. Boosts energy: Regular physical activity can raise your energy levels and improve sleep quality.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1618/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1620', 'seated-dumbbell-calf-raise-1620', 'Seated Dumbbell Calf Raise', '["calves"]', '["dumbbell"]', 'The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1620/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1621', 'unilateral-cable-row-1621', 'Unilateral Cable row', '["lats"]', '["bench","cable machine"]', 'Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1621/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1630', 'blaze-1630', 'Blaze', '["shoulders","glutes","chest","quads","biceps","hamstrings","lats","abs"]', '["bench","dumbbell","kettlebell"]', 'BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ricwheatley', 'https://wger.de/en/exercise/1630/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1634', 'rope-pullover-row-1634', 'Rope Pullover/row', '["lats"]', '["cable machine","incline bench"]', 'Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1634/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1635', 'modified-pulldown-1635', 'Modified pulldown', '["lats"]', '["cable machine","incline bench"]', 'With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1635/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1637', 'single-arm-row-1637', 'Single arm row', '["lats"]', '["cable machine","incline bench"]', 'Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1637/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1638', 'barbell-clean-and-press-1638', 'Barbell Clean and press', '["shoulders","chest"]', '["dumbbell"]', 'This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1638/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1639', 'dumbbell-bent-over-face-pull-1639', 'Dumbbell Bent Over Face Pull', '["shoulders","lats"]', '["dumbbell"]', 'This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1639/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1640', 'dumbbell-front-squat-1640', 'Dumbbell Front Squat', '["glutes","quads","shoulders","abs"]', '["dumbbell"]', 'This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1640/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1641', 'kettlebell-one-legged-deadlift-1641', 'Kettlebell One Legged Deadlift', '["glutes"]', '["dumbbell","kettlebell"]', 'This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1641/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1642', 'dumbbell-hip-thrust-1642', 'Dumbbell Hip Thrust', '["glutes","quads"]', '["dumbbell"]', 'This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1642/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1648', 'weighted-crunch-1648', 'Weighted Crunch', '[]', '["dumbbell"]', 'The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work. Lay down (Optional) Bend your knees to add difficulty (Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees) Lift your head and torso while bending your back forward (if you don''t it''s a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting. Go back to starting position an repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1648/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1650', 'dumbbell-side-bend-1650', 'Dumbbell Side Bend', '[]', '["dumbbell"]', 'This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1650/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1651', 'dumbbell-rear-lunge-1651', 'Dumbbell Rear Lunge', '["glutes","quads"]', '["dumbbell"]', 'This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1651/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1652', 'dumbbell-romanian-deadlift-1652', 'Dumbbell Romanian Deadlift', '["hamstrings","glutes"]', '["dumbbell"]', 'This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1652/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1653', 'dumbbell-side-squat-1653', 'Dumbbell Side Squat', '["glutes","quads","hamstrings"]', '[]', 'This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1653/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1654', 'machine-lateral-raise-1654', 'Machine Lateral Raise', '["shoulders"]', '["gym mat"]', 'The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine''s fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'roneydya', 'https://wger.de/en/exercise/1654/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1656', 'cable-chest-press-decline-1656', 'Cable Chest Press - Decline', '["chest","triceps"]', '["cable machine"]', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1656/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1657', 'preacher-curl-internally-rotated-1657', 'Preacher Curl - Internally Rotated', '["biceps"]', '["dumbbell"]', 'Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1657/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1658', 'preacher-curl-externally-rotated-1658', 'Preacher Curl - Externally Rotated', '["biceps"]', '["dumbbell"]', 'Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body away from the weight', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1658/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1659', 'lat-pulldown-cross-body-single-arm-1659', 'Lat Pulldown - Cross Body Single Arm', '["lats"]', '["cable machine"]', 'Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1659/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1660', 'cable-chest-press-incline-1660', 'Cable Chest Press - Incline', '["chest","triceps"]', '["cable machine"]', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1660/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1661', 'cable-triceps-press-1661', 'Cable Triceps Press', '["triceps"]', '["cable machine"]', 'A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1661/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1662', 'cable-tri-extension-internal-rotation-1662', 'Cable Tri Extension - Internal Rotation', '["triceps"]', '["cable machine"]', 'single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1662/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1666', 'curl-with-shoulder-elevated-1666', 'Curl - With Shoulder Elevated', '["biceps"]', '["dumbbell"]', 'Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1666/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1668', 'one-arm-overhead-cable-tricep-extension-1668', 'One Arm Overhead Cable Tricep Extension', '["triceps"]', '["cable machine"]', 'Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead. While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1668/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1670', 'leg-swings-front-back-1670', 'Leg Swings (Front-Back)', '["hamstrings","glutes","quads"]', '["none (bodyweight exercise)"]', 'Stand tall next to a wall or stable support. Swing one leg forward and backward in a controlled motion, keeping the torso upright and the core engaged. Alternate legs after completing the repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Jhonatan', 'https://wger.de/en/exercise/1670/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1672', 'seated-hip-abduction-1672', 'Seated Hip Abduction', '["glutes"]', '["none (bodyweight exercise)"]', 'Starting Position: Adjust the seat height so that your knees are aligned with the pivot point of the machine. Sit with your back flat against the backrest, maintaining good posture. Place the outside of your thighs against the machine''s padded levers. Position your feet flat on the footrests or platform of the machine. Grasp the handles or sides of the seat for stability. Ensure your spine is neutral and your core is slightly engaged. Movement: Exhale as you slowly push your legs outward against the resistance pads. Focus on initiating the movement from your hips, not your knees. Continue opening your legs until you feel a strong contraction in your outer hips and thighs. Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement. Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement. Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles. Repeat for the desired number of repetitions, maintaining control throughout the set.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Iko', 'https://wger.de/en/exercise/1672/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1679', 'wall-angels-1679', 'Wall Angels', '["shoulders"]', '[]', 'The Wall Angels exercise primarily targets the upper back and shoulder muscles , helping improve posture , shoulder mobility , and scapular control .', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'bbayuwega', 'https://wger.de/en/exercise/1679/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1680', 'seated-figure-four-1680', 'seated figure four', '["glutes"]', '["bench"]', 'Seat on a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ricardodavidrd', 'https://wger.de/en/exercise/1680/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1683', 'zottman-curl-1683', 'Zottman curl', '["biceps"]', '["dumbbell"]', 'With your palms facing forward, curl the weights up to your shoulders. Turn your hands so that that your palms downwards and slowly return the weights back down. Finally face your palms back forward.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1683/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1684', 'dumbbell-thruster-1684', 'Dumbbell Thruster', '["hamstrings","glutes","quads","shoulders"]', '["dumbbell"]', 'Start with the dumbbells resting on your shoulders and squat down. Push into standing and raise the dumbbells into an overhead position. Bring the dumbbells back to your shoulders and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1684/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1686', 'glute-bridge-single-arm-press-1686', 'Glute Bridge Single-Arm Press', '["chest","shoulders","biceps","hamstrings","glutes","triceps"]', '["dumbbell"]', 'With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1686/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1687', 'bear-crawl-pull-through-1687', 'Bear crawl pull through', '["shoulders","glutes","quads","abs","hamstrings","calves"]', '["dumbbell"]', 'Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold. With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1687/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1688', 'kickstand-rdl-1688', 'Kickstand RDL', '["hamstrings"]', '["barbell"]', 'use non-working leg''s toes to help with balance and perform an RDL.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'eriktrinkle', 'https://wger.de/en/exercise/1688/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1689', 'cable-fly-middle-chest-1689', 'Cable Fly Middle Chest', '["chest"]', '["cable machine"]', 'Execution Start position: Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest. Movement: Bring your hands together in front of your chest in a wide hugging motion . Focus on squeezing your chest at the center. Do not lock your elbows or turn it into a press. Return: Slowly open your arms back to the start, maintaining tension on the chest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1689/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1690', 'cable-fly-upper-chest-1690', 'Cable Fly Upper Chest', '["chest"]', '["cable machine"]', 'Execution Start position: Arms down and slightly behind your body, elbows slightly bent. Feel a light stretch across your chest. Movement: Bring your hands upward and together in front of your upper chest - roughly at chin to collarbone level . Use a smooth, controlled motion (avoid jerking). Squeeze your chest at the top for 1-2 seconds. Return: Slowly let your arms move back down and out to the sides, keeping control and tension.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1690/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1691', 'cable-fly-lower-chest-1691', 'Cable Fly Lower Chest', '["chest"]', '["cable machine"]', 'Execution Start position: Arms extended out to your sides in a “Y” shape. Feel a stretch in your chest (slight bend in elbows - don’t lock them). Movement: Bring your hands downward and together in front of your lower chest or upper abs , in a smooth arc motion. Squeeze your chest hard at the bottom for 1-2 seconds. Return: Slowly raise your arms back up along the same path until you feel a good stretch in your chest. Maintain control - don’t let the weights pull you back too quickly.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1691/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1693', 'incline-static-hold-1693', 'Incline Static Hold', '["chest"]', '["dumbbell"]', 'Execution Hold Position: Lower the dumbbells a few inches above your chest - about the midpoint of a normal incline press. This is where your upper chest is under maximum tension. Static Hold: Hold the position for 20-45 seconds while keeping the chest tight. Breathe slowly but stay tense - do not relax your chest or shoulders . End the set: After the hold, carefully bring the dumbbells down and rest.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1693/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1694', 'flat-machine-press-1694', 'Flat Machine Press', '["chest"]', '["bench"]', 'Execution Start position: Elbows bent at roughly 90°, hands just outside your chest. Keep wrists straight and aligned with your forearms. Pressing phase (concentric): Push the handles forward until your arms are almost fully extended - don’t lock out. Focus on squeezing your chest at the end of the movement. Returning phase (eccentric): Slowly bring the handles back toward your chest, feeling the stretch in your pecs . Maintain tension - don’t let the weight stack touch down between reps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1694/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1695', 'pull-ups-wide-grip-1695', 'Pull-Ups (Wide Grip)', '["lats"]', '["none (bodyweight exercise)"]', 'Execution Pulling phase (concentric): Drive your elbows down and slightly back , pulling your chest toward the bar . Focus on leading with your chest , not your chin. Keep your shoulders depressed (avoid shrugging). Top position: Chin should clear the bar (or at least reach bar level). Pause for a brief squeeze in your lats .', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1695/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1696', 'pull-ups-neutral-grip-1696', 'Pull-Ups (Neutral Grip)', '["lats"]', '[]', 'Execution Pulling phase (concentric): Drive your elbows down and back , pulling your chest toward your hands . Keep your shoulders depressed and retracted (avoid shrugging). Focus on squeezing your lats and upper back at the top. Top position: Chin should clear or reach the level of your hands. Pause briefly and contract your lats hard.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1696/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1698', 'barbell-row-overhand-1698', 'Barbell Row (Overhand)', '["lats"]', '["barbell"]', 'Execution Starting position: Hold the barbell with arms fully extended toward the floor. Maintain tension in your lats and back muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1698/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1699', 'barbell-row-underhand-1699', 'Barbell Row (Underhand)', '["lats"]', '["barbell"]', 'Execution Starting position: Hold the barbell with arms fully extended toward the floor. Maintain tension in your lats and back muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1699/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1700', 'barbell-romanian-deadlift-rdl-1700', 'Barbell Romanian Deadlift (RDL)', '["hamstrings","glutes"]', '["barbell"]', 'Execution Hinge at the hips: Push your hips backward , keeping a slight bend in the knees (soft knees). Lower the barbell along the front of your thighs/shins while maintaining a neutral spine . Keep the bar close to your body .', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1700/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1701', 'one-arm-heavy-row-1701', 'One-Arm Heavy Row', '["lats"]', '["dumbbell"]', 'Execution Rowing phase (concentric): Pull the dumbbell toward your lower chest or waist , leading with your elbow . Keep your torso stable - avoid twisting or rotating your shoulders. Pause at the top and squeeze your lats .', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1701/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1702', 'jal-n-al-pecho-con-agarre-ancho-1702', 'Jalón al pecho con agarre ancho', '["lats","biceps"]', '["cable machine"]', 'The lat pulldown is a pulling exercise that primarily targets the latissimus dorsi muscles (commonly known as “lats”) in your back. It involves pulling a cable bar or handle down towards your chest while seated on a machine specifically designed for this exercise. The lat pulldown is typically performed with a wide grip, but can also be done with a narrow grip or underhand grip to target different muscle groups in the back and arms. It is a popular exercise for building upper body strength and improving posture.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1702/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1703', 'patadas-traseras-1703', 'Patadas traseras', '["triceps"]', '["bench","dumbbell"]', 'The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics. Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1703/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1704', 'tuck-l-sit-1704', 'Tuck L-sit', '["abs","chest","quads","triceps"]', '["bench"]', 'The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1704/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1706', 'bulgarian-squat-with-dumbbells-1706', 'Bulgarian Squat with Dumbbells', '["glutes","quads","hamstrings"]', '["dumbbell"]', 'The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1706/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1707', 'unilateral-cable-lateral-raise-1707', 'Unilateral Cable Lateral Raise', '["shoulders"]', '["incline bench"]', 'Single-arm lateral raise on a cable machine. Pull the cable out to the side up to shoulder height with control, then lower it slowly.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1707/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1709', 'reverse-fly-standing-1709', 'Reverse Fly Standing', '["shoulders"]', '["cable machine"]', 'Stand with a good posture holding a cable in each hand opposite the machine Starting with the hands in front of your chest pull the arms out to your side into the shape of a T with the elbows nearly straight Slowly release the arms forward to the start Repeat with the arms moving into the shape of a Y Repeat with the arms in the shape of a W Repeat with the arms in the shape of an L by your side', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1709/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1710', 'butchers-block-stretch-1710', 'Butchers Block Stretch', '["lats"]', '["bench"]', 'Kneel down with the hands together Rest the elbows on a bench in front of you and lower the chest down Keep the elbows bent with good posture and hold', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1710/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1711', 'sleeper-stretch-1711', 'Sleeper Stretch', '["shoulders"]', '["none (bodyweight exercise)"]', 'Lie on your side so that you are resting a little weight on your shoulder blade to keep it still Extend your arm to 90 degrees in front of you, resting on the floor/mat Lift your hand with your elbow so that your fingers point to the ceiling and your palm points towards your feet Keeping your elbow still, gently lower your palm toward the floor', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1711/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1712', 'horizontal-shoulder-flexion-stretch-1712', 'Horizontal Shoulder Flexion Stretch', '["chest","shoulders"]', '["none (bodyweight exercise)"]', 'Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height Turn your body away from your arm to stretch the chest, as far as is comfortable', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1712/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1713', 'doorway-pectoral-stretch-1713', 'Doorway Pectoral Stretch', '["chest"]', '["none (bodyweight exercise)"]', 'Place the forearm vertically on a door frame or stationary object at head height Step forward past the arm, keeping it still against the object to stretch the chest', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1713/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1714', 'shoulder-dumbbell-pendular-exercise-1714', 'Shoulder Dumbbell Pendular Exercise', '["shoulders","lats","chest"]', '["dumbbell"]', 'Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand Gently swing the dumbbell in a circular motion', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1714/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1715', 'shoulder-external-rotation-with-dumbbell-1715', 'Shoulder External Rotation with Dumbbell', '["shoulders"]', '["dumbbell"]', 'Lie on your side holding a dumbbell in your upper hand Tuck your elbow into your side and rest the hand in front of you Rotate the shoulder so the hand raises up Lower the hand down', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1715/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1716', 'incline-shoulder-press-up-1716', 'Incline Shoulder Press Up', '["shoulders","chest"]', '["bench"]', 'Place your hands on the bench in a press up position Push your chest away from the bench to separate your shoulder blades Keeping your elbows straight , lower your chest towards the bench so your shoulder blades move closer together Push your chest away from the bench again', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1716/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1717', 'neck-extension-1717', 'Neck extension', '["biceps"]', '["cable machine","sz-bar"]', 'Unilateral triceps exercise with your back to the pulley, with the pulley at the top', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1717/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1718', 'remo-alto-polea-alta-1718', 'Remo alto polea alta', '["triceps"]', '["cable machine"]', 'High pulley row with support using a single grip', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1718/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1719', 'half-kneeling-unilateral-lat-pulldown-1719', 'Half-Kneeling Unilateral Lat Pulldown', '[]', '["dumbbell"]', 'Single-arm lat pulldown performed in a half-kneeling (knight''s) stance. The knee on the floor is on the same side as the pulling arm.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1719/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1723', 'glute-kickback-machine-1723', 'Glute Kickback (Machine)', '["glutes"]', '[]', 'Drive through your heel, not your toes, to hit the glute. Don’t hyperextend your lower back at the top.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1723/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1724', 'standing-adduction-cable-1724', 'Standing Adduction (Cable)', '[]', '["cable machine"]', 'Keep your hips square and still, pulling the cable across your opposing leg using only your inner thigh. Don’t let your torso lean or twist - no side bending to help the rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1724/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1725', 'seated-row-machine-1725', 'Seated Row (Machine)', '["lats","shoulders"]', '[]', 'Keep your chest up and squeeze your shoulder blades at the end. Don’t hunch forward or round your back during the pull.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1725/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1726', 'straight-arm-pulldown-cable-1726', 'Straight-Arm Pulldown (Cable)', '["lats"]', '["cable machine"]', 'Keep arms straight but not locked, pulling with your lats, not your shoulders. Don’t let your shoulders shrug up during the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1726/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1727', 'side-straight-arm-pulldown-cable-1727', 'Side Straight-Arm Pulldown (Cable)', '["lats"]', '["cable machine"]', 'Keep your torso still, pulling the handle down along your side using the outer lat. Don’t twist your body or rotate your torso to cheat the rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1727/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1728', 'shoulder-internal-rotation-cable-1728', 'Shoulder Internal Rotation (Cable)', '["shoulders"]', '["cable machine"]', 'Keep your elbow tucked to your side like it''s superglued there. Don’t rotate your torso - only your forearm should move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1728/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1729', 'shoulder-external-rotation-cable-1729', 'Shoulder External Rotation (Cable)', '["shoulders"]', '["cable machine"]', 'Keep elbow fixed at your side and rotate forearm outward smoothly. Don’t let your wrist or elbow drift upward - stay in one plane.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1729/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1730', 'side-lateral-raise-cable-1730', 'Side Lateral Raise (Cable)', '["lats"]', '["cable machine"]', 'Lift with your elbows leading, not your hands. Don’t shrug your shoulders; keep traps quiet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1730/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1731', 'front-raise-cable-1731', 'Front Raise (Cable)', '["shoulders"]', '["cable machine"]', 'Raise the handle in a slight arc with controlled movement. Don’t swing your torso to start the rep.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1731/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1732', 'face-pulls-with-yellow-green-band-1732', 'Face pulls with yellow/green band', '["lats"]', '["resistance band"]', 'Face pulls with band - standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '54str', 'https://wger.de/en/exercise/1732/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1733', 'isometric-squat-to-failure-1733', 'Isometric Squat to Failure', '["glutes","quads"]', '["none (bodyweight exercise)"]', 'sometric Squat to Failure: A Strength Training Technique Definition The isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1733/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1734', 'single-leg-lunge-with-kettlebell-1734', 'Single-Leg Lunge with Kettlebell:', '["calves","glutes","quads"]', '["kettlebell"]', 'How to do a single-leg kettlebell lunge Preparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg). Step and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle. Focus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright. Return: Push off with your front leg to return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1734/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1735', 'single-leg-side-glute-press-1735', 'Single-leg side glute press', '["calves","glutes","quads"]', '["incline bench"]', 'The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out. How to Perform: Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward. Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad. Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring. Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends. Control: Avoid bouncing and don''t let your lower back lift off the pad; maintain tension throughout the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1735/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1736', 'single-leg-deadlift-with-dumbbell-1736', 'Single-Leg Deadlift with Dumbbell', '["hamstrings","glutes"]', '["dumbbell"]', 'Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor. The Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg. Range of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement. Return to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one. Switch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1736/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1737', 'assisted-chin-ups-1737', 'Assisted chin-ups', '["biceps","lats"]', '[]', 'Chin-ups with machine assistance (counterweights)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1737/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1738', 'neutral-grip-pull-ups-or-trx-rows-1738', 'Neutral-grip pull-ups or TRX rows', '["lats","biceps"]', '["pull-up bar"]', 'Pull-Up: Vertical Pull - Focuses more on the Lats (back width). TRX Row: Horizontal Pull - Focuses more on the Rhomboids/Traps (mid-back thickness and posture).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '54str', 'https://wger.de/en/exercise/1738/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1739', 'shrimp-squat-1739', 'Shrimp Squat', '["glutes","quads","hamstrings","calves"]', '["none (bodyweight exercise)"]', 'Single leg squat where one leg is behind you.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1739/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1740', 'single-leg-glute-bridge-1740', 'Single Leg Glute Bridge', '["glutes"]', '["none (bodyweight exercise)"]', 'A glute bridge, where you use just one leg at a time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1740/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1741', 'l-sit-pull-ups-1741', 'L-Sit Pull-ups', '["lats","biceps","abs"]', '["none (bodyweight exercise)"]', 'Pull-ups performed with your legs held straight out in front of you, so that your body forms an L. Trains both the upper body and the core.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1741/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1742', 'back-lever-1742', 'Back Lever', '[]', '["pull-up bar"]', 'Hanging from a pull-up bar facing downwards with your arms extended', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1742/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1743', 'windshield-wipers-1743', 'Windshield Wipers', '["abs"]', '["pull-up bar"]', 'Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1743/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1744', 'machine-side-lateral-raises-1744', 'Machine Side Lateral Raises', '["shoulders"]', '[]', 'Machine side lateral raises are an isolation exercise for the side (lateral) deltoids, performed on a machine for stability, targeting the outer shoulder by lifting pads or handles out to the sides to shoulder height, then lowering slowly, keeping elbows slightly bent and traps down to focus on the delts. This exercise helps build shoulder width by preventing swinging and providing constant tension, making it great for beginners or as a finisher. How to Perform Machine Lateral Raises Setup: Adjust the seat so your shoulders align with the machine''s pivot point, your chest is against the pad (or back if facing out), and your arms are at a 90-degree angle with the pads/handles. Starting Position: Grip the handles with a relaxed grip, elbows slightly bent, and shoulders down (depressed) away from your ears. Lifting Phase: Exhale and lift your arms out to the sides, moving your upper arms laterally, until they are parallel to the floor. Peak Contraction: Pause briefly at the top, squeezing the side delts, but don''t shrug your shoulders up. Lowering Phase: Inhale and slowly lower the weight back down with control, resisting the weight on the way down.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1744/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1745', 'cable-front-raise-with-a-small-bar-1745', 'Cable Front Raise with a small bar', '["shoulders"]', '["cable machine"]', 'The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum. How to Perform the Cable Front Raise (Bar) Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting. Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down. The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below). The Hold: Pause briefly at the top, squeezing your front delts. The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1745/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1747', 'smith-machine-squat-1747', 'Smith machine squat', '["glutes","quads"]', '[]', 'Technique and Execution The Smith machine squat is a variation of the traditional barbell squat that uses a guided, fixed-path barbell. Here''s a detailed breakdown of the proper technique: Starting Position Foot Placement: Position feet slightly forward of the bar, about shoulder-width apart Bar Position: Rest the bar on your upper trapezius/shoulders, similar to a traditional back squat Stance: Feet can be slightly angled outward for natural hip rotation Squat Movement Unrack the bar by rotating it to release from the safety hooks Slowly lower your body by bending knees and hips Descend until thighs are parallel to the ground (or slightly below) Pause briefly at the bottom of the movement Drive through your heels to return to the starting position Benefits and Considerations Advantages Reduced Balance Requirements: Fixed bar path makes it easier for beginners Controlled Movement: Less risk of improper form compared to free weight squats Isolation: Allows focused leg muscle development', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1747/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1748', 'machine-hip-abduction-1748', 'Machine Hip Abduction', '["glutes"]', '[]', 'Technique and Execution Starting Position Seated Positioning: Sit in the machine with back against the pad Leg Placement: Inner thighs against the machine''s padded resistance points Adjust Machine: Set seat position to align your hip joint with the machine''s pivot point Movement Technique Start with legs together or slightly pressed against the inner pads Slowly push legs outward, spreading them apart Move until maximum comfortable lateral range is reached Pause briefly at the outer point of the movement Slowly return to the starting position with controlled movement Biomechanical Breakdown Muscle Engagement Primary Activation: Gluteus Medius (side hip muscle) Stabilization: Engages core and lower back muscles Functional Movement: Mimics lateral leg movement used in walking, sports, and daily activities Benefits Strength and Stability Improves Hip Stability Reduces Risk of Knee Injuries Enhances Lateral Movement Capabilities Targets Often-Neglected Muscle Groups', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1748/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1751', 'cable-pull-through-1751', 'Cable pull through', '["glutes","hamstrings","calves","quads"]', '["cable machine"]', 'The Cable Pull Through is a lower-body exercise that targets the glutes and hamstrings using a "hip hinge" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings. To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is not a squat ; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'manuher89', 'https://wger.de/en/exercise/1751/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1752', 'side-lateral-raise-front-cable-1752', 'Side lateral raise - Front (Cable)', '["shoulders"]', '["cable machine"]', 'in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1752/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1753', 'side-lateral-raise-back-cable-1753', 'Side lateral raise - Back (Cable)', '["shoulders"]', '["cable machine"]', 'on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1753/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1754', '45-lateral-raises-1754', '45° lateral raises', '[]', '["dumbbell"]', 'Dumbbell raise at an angle halfway between a front raise and a lateral raise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1754/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1755', 'shoulder-y-pull-cable-1755', 'Shoulder Y-pull cable', '[]', '["cable machine"]', 'on a cable rack cross the cables and pull elbows to ceiling close to the body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1755/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1766', 'plank-reach-1766', 'Plank Reach', '["abs","shoulders"]', '["none (bodyweight exercise)"]', 'Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1766/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1771', 'wrist-curl-cable-1771', 'Wrist curl, cable', '["biceps"]', '["cable machine"]', 'Extend your arm down, then slightly lift your forearm Extend your wrist in a supinated form (palm up) Adjust cable height so that the cable handle is in your supinated hand Perform the movement by curling your palms and wrists upwards (optional/variable) Pause at the top Slowly return to the starting position', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1771/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1772', 'reverse-crunch-1772', 'Reverse crunch', '["abs"]', '["none (bodyweight exercise)"]', 'Lay down Place your hands near your butt (often slightly in front or under or both) Raise your legs, but about 70% of the way you should be able to also raise your pelvis (optional/variable) Hold 1/2 seconds at the top Go back to starting position', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1772/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1773', 'legend-incline-bench-press-1773', 'Legend Incline Bench Press', '["chest","shoulders","triceps"]', '[]', 'Incline bench press on the Legend Fitness LeverEdge machine. Adjust the seat, release the lever and press until your arms are extended, then lower under control.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1773/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1774', 'chair-dips-1774', 'Chair dips', '["triceps","shoulders","chest"]', '["none (bodyweight exercise)"]', 'Starting position: Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair. Steps: Slowly lower your body, keeping the back straight, until your arms are at a right angle. Raise your body again to the initial position, arms extended. Repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1774/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1775', 'pec-deck-rear-delt-fly-1775', 'Pec deck rear delt fly', '[]', '[]', 'Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1775/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1776', 'suitcase-carry-1776', 'Suitcase Carry', '["abs"]', '["dumbbell"]', 'Walk forward and backward with holding dumbbell on one side without leaning to counter the weight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/1776/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1777', 'deficit-push-ups-1777', 'Deficit Push ups', '["chest","triceps"]', '["none (bodyweight exercise)"]', 'Push-ups with your hands on blocks or push-up handles, so that you can lower your chest below the level of your hands.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1777/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1778', 'supino-inclinado-1778', 'Supino inclinado', '["chest","shoulders","triceps"]', '[]', 'Inclinado 90 graus e movimentos leves e precisos', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1778/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1779', 'landmine-rotation-1779', 'Landmine Rotation', '["shoulders","abs"]', '["barbell"]', 'Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/1779/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1795', 'unilateral-cross-body-cable-pull-down-1795', 'unilateral cross body cable pull down', '["lats","shoulders"]', '["cable machine"]', 'on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1795/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1801', 'barbell-full-squat-1801', 'Barbell Full Squat', '["hamstrings","glutes","quads","calves","abs"]', '["barbell"]', 'The barbell full squat is a compound exercise that targets multiple muscle groups in the lower body, including the quadriceps, hamstrings, and glutes. Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning. Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique. To achieve new personal records in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and prioritize rest and recovery between training sessions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'fabrice', 'https://wger.de/en/exercise/1801/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1803', 'trap-bar-squat-1803', 'Trap Bar Squat', '["quads","hamstrings"]', '[]', 'A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'kmcalderwood', 'https://wger.de/en/exercise/1803/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1804', 'ankle-dorsiflexion-rocks-1804', 'ankle dorsiflexion rocks', '["calves"]', '["none (bodyweight exercise)"]', 'Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1804/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1807', 'behind-the-back-cable-lateral-raise-1807', 'Behind the Back Cable Lateral Raise', '["shoulders"]', '["cable machine"]', 'Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'LEBRERO', 'https://wger.de/en/exercise/1807/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1808', 'parallel-bar-hold-1808', 'Parallel Bar Hold', '["shoulders","chest","triceps","lats","abs"]', '[]', 'Stand between a set of parallel bars. Place your hands, knuckles outwards, on the bars. Push down on your hands to lift yourself off the floor. Hold yourself in this position with your arms straight for the required time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1808/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1809', 'reverse-hyperextension-1809', 'Reverse Hyperextension', '["hamstrings","glutes"]', '["bench"]', 'Lie face-down on a bench with your legs hanging off the edge. Bend your hips so your thighs are vertical, bending your knees at the same time so your shins stay horizontal. Straighten out your legs so they are not bent and your toes are pointing backwards horizontally. Return to the original position, and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1809/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1810', 'sphinx-1810', 'Sphinx', '["abs"]', '["none (bodyweight exercise)"]', 'Lie on your stomach flat, legs extended and the backs of your feet on the ground. Bring your forearms under your shoulders, elbows directly underneath. Then press your hands into the floor to lift your chest. Draw your shoulder blades together, open your collarbones, and direct your gaze forward, while keeping the lower back relaxed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Joculari', 'https://wger.de/en/exercise/1810/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1822', 'open-book-1822', 'Open Book', '[]', '["none (bodyweight exercise)"]', 'Basic exercise Focus: enhances thoracic mobility and spinal segmentation while opening the shoulders and chest. **Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably. Begin with your arms relaxed and open in front of your chest, palms facing each other and hands apart. Inhale to initiate the movement, allowing your left arm -the one farther from the wall- to open outward and backward. Lead the twist from your thoracic spine, rotating your upper back progressively while keeping your pelvis still. Exhale as you complete the rotation, guiding your left hand toward the wall as your gaze follows your hand. Return by inhaling and slowly bringing your arm forward, reversing the spinal rotation segment by segment. Repeat on the opposite side. Progression **Position:**kneeling on the floor with your right side facing a wall. Left knee down and right foot forward. Before the basic exercise: inhale , exhale while moving the right arm along the wall with a circle upwards and backwards, inhale while bringing back the arm. Basic exercise. Repeat on the opposite side.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1822/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1823', 'clamshell-1823', 'Clamshell', '["glutes","abs"]', '["none (bodyweight exercise)"]', 'Position Side plank with the elbow and the forearm on the ground and the legs slightly bent. Execution Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1823/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1824', 'dumbell-tate-press-1824', 'Dumbell Tate Press', '["triceps","shoulders","chest"]', '["bench","dumbbell"]', 'Set Up : Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press Starting Position : Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other) Lowering : Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest Touch and Pause : Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps Press : Forcefully extend your elbows to return the dumbbells to the starting position. Focus on "pushing your pinkies toward the sky" to maximize triceps engagement https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1824/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1825', 'chest-supported-rear-delt-raise-1825', 'Chest-Supported Rear Delt Raise', '["shoulders"]', '["bench","dumbbell"]', '"The Y" Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain. Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling). Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a "Y" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms. Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a "Y". Control: Lower the dumbbells slowly to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1825/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1826', 'band-pull-apart-with-external-rotation-1826', 'Band pull-apart with external rotation', '["shoulders"]', '["resistance band"]', 'Stand tall with your feet shoulder-width apart, chest out, and shoulders back. Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type. Bend your elbows at a 90-degree angle and glue your upper arms to your sides. The band should have some tension in the starting position, with your hands closer together in front of your stomach. Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band. Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward. Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides. Hold: Hold the end position for 1-2 seconds to maximize muscle engagement. Return: Slowly and with control, bring your hands back to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1826/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1827', 'double-leg-abdominal-press-1827', 'Double-Leg Abdominal Press', '["abs"]', '["gym mat"]', 'Lie on your back with knees and hips bent at 90 degrees (tabletop). Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands. Hold for 10 seconds of maximum effort. Your abs should be shaking.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1827/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1828', 'abdominal-draw-in-1828', 'Abdominal Draw-In', '["abs"]', '["none (bodyweight exercise)"]', 'Lie on your back with knees bent. Gently pull your belly button toward your spine without moving your hips or holding your breath.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1828/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1829', 'landmine-squat-to-press-1829', 'Landmine Squat to Press', '["shoulders","glutes","quads","hamstrings","abs"]', '["barbell"]', 'Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner. Stance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10-35 degrees to allow for better pelvic movement and depth. Grip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone. Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels. Depth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees. Posture: Ensure your back remains flat and your spine neutral throughout the movement. Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to "thrust" the weight upward. Extension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears. The "Lean": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching. Slowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1829/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1830', 'barbell-step-back-lunge-1830', 'Barbell Step Back Lunge', '["quads"]', '["barbell"]', 'Stand with your feet hip-width apart, holding a barbell on your upper back. Keep your back straight, chest up, and core engaged. Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground. Push off your back foot to return to the starting position. Repeat the movement with the other leg. Continue alternating between legs for the desired repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1830/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1831', 'hammerstrength-decline-chest-press-1831', 'Hammerstrength Decline Chest Press', '["chest","shoulders","triceps"]', '[]', 'Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees. The back pad should be contact with your head, shoulders, and butt at all times. Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest. Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso. Once your arms are fully extended, return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1831/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1832', 'ring-support-hold-1832', 'Ring Support Hold', '[]', '[]', 'Hold yourself in a support position on gymnastic rings with arms straight at sides. Focus on keeping rings turned out slightly and maintaining hollow body position. This is an isometric hold for chest, shoulders, and triceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1832/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1833', 'floor-glider-hamstring-curls-1833', 'Floor Glider Hamstring Curls', '["hamstrings","calves","glutes"]', '[]', 'Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1833/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1834', 'trap-3-raise-1834', 'Trap-3 Raise', '[]', '["none (bodyweight exercise)"]', 'Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee. Raise your hand about 15 degrees overhead, maintaining the position of your shoulder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1834/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1835', 'external-rotation-stretch-1835', 'External Rotation Stretch', '["shoulders"]', '["barbell"]', 'Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body. Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell. Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot. Lower your hand to the original position and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1835/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1838', 'banded-shoulder-drills-1838', 'Banded Shoulder Drills', '["shoulders","chest"]', '["resistance band"]', 'Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut. Perform the shoulder mobility and rotation drills shown in the video: https://www.youtube.com/watch?v=zdwEWchSjrI', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1838/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1839', 'solo-hip-flexor-stretch-1839', 'Solo Hip Flexor Stretch', '[]', '["none (bodyweight exercise)"]', 'See this instructive video: https://www.youtube.com/watch?v=qHwyBHS6MQs .', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1839/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1840', 'bent-leg-hamstring-stretch-1840', 'Bent-Leg Hamstring Stretch', '[]', '["none (bodyweight exercise)"]', 'Lie on your back with one leg straight on the floor. Hold the other leg behind the knee or the back of the thigh and pull it towards your chest, keeping the knee bent, until you feel a stretch in the hamstrings. Hold the position while breathing calmly, then switch sides. See this instructional video from Stretch Therapy: https://www.youtube.com/watch?v=CrF2iMnn09w', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1840/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1841', 'seated-shoulder-extension-stretch-1841', 'Seated Shoulder Extension Stretch', '["lats","chest"]', '["none (bodyweight exercise)"]', 'Sit with your hands behind you, shoulder width apart. Lock your elbows. Scoot your feet and hips out forwards, lowering your shoulders down towards ground. Go as far as possible to obtain a good stretch. See the video: https://www.youtube.com/watch?v=ihUAbG0e8zw', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1841/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1842', 'banded-clamshell-1842', 'Banded Clamshell', '["glutes","abs","quads"]', '["resistance band"]', 'Position Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee. Execution Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1842/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1843', 'butterfly-stretch-1843', 'Butterfly Stretch', '[]', '["none (bodyweight exercise)"]', 'Sit in a prayer position with the soles of your feet gently pressed together. Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1843/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1844', 'frog-stretch-1844', 'Frog Stretch', '["glutes"]', '["none (bodyweight exercise)"]', 'Get on your hands and knees. Widen your knees outwards, and drop to your elbows. Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1844/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1845', 'seated-pancake-good-morning-1845', 'Seated Pancake Good Morning', '["glutes"]', '["none (bodyweight exercise)"]', 'Sit with your legs completely straight (knees locked), spread wide in a straddle position. Place your hands on the back of your neck. Hinge your torso and head towards the floor.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1845/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1846', 'horse-stance-side-splits-1846', 'Horse Stance (Side Splits)', '["glutes"]', '["none (bodyweight exercise)"]', 'Stand as for a squat, with your feet wide and your toes pointed slightly outwards. Gently squat into a deep, wide squat - your hips should be below your knees. Hold for 3 to 5 seconds. Come up under control, and repeat as needed.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1846/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1847', 'straddle-l-sit-1847', 'Straddle L-Sit', '["abs","lats","chest","quads"]', '["none (bodyweight exercise)"]', 'With your legs in a sitting saddle position, push your body upwards off the ground. Your legs should be horizontal and point straight outwards. Your arms should be between your legs. Hold isometrically as long as required.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1847/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1852', 'l-sit-1852', 'L-sit', '["lats","chest","abs","quads","triceps"]', '["none (bodyweight exercise)"]', 'Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor. Hold for as long as required.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1852/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1853', 'l-sit-foot-supported-1853', 'L-Sit (Foot Supported)', '["lats","chest","abs","quads","triceps"]', '["none (bodyweight exercise)"]', 'As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1853/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1854', 'calves-foam-roller-1854', 'Calves foam roller', '["calves"]', '["none (bodyweight exercise)"]', 'Move your calves slowly over the foam roller', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1854/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1855', 'hamstring-foam-roller-1855', 'Hamstring Foam roller', '[]', '["none (bodyweight exercise)"]', 'Move your hamstrings slowly over the foam roller', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1855/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1856', 'foam-roller-anterior-tibialis-1856', 'Foam Roller Anterior tibialis', '[]', '["none (bodyweight exercise)"]', 'Slowly roll the front of your shin (tibialis anterior) over the foam roller with moderate pressure, moving back and forth.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1856/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1857', 'foam-roller-iliotibial-band-1857', 'Foam Roller Iliotibial band', '["quads"]', '["none (bodyweight exercise)"]', 'Lie on your side with the foam roller under the outside of your thigh and slowly roll back and forth along the iliotibial band with moderate pressure.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1857/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1858', 'foam-roller-quadriceps-1858', 'Foam Roller quadriceps', '["quads"]', '["none (bodyweight exercise)"]', 'Lie face down with the foam roller under your thighs and slowly roll back and forth over your quadriceps with moderate pressure.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1858/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1859', 'foam-roller-gluteus-1859', 'Foam Roller Gluteus', '["glutes"]', '["none (bodyweight exercise)"]', 'Sit on the foam roller and slowly roll back and forth over your glutes with moderate pressure.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1859/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1860', 'foam-roller-adductors-1860', 'Foam Roller Adductors', '[]', '["none (bodyweight exercise)"]', 'Lie face down with one leg bent out to the side and the foam roller under the inner thigh. Slowly roll back and forth over your adductors with moderate pressure.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1860/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1861', 'side-stretch-1861', 'Side stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1861/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1862', 'hip-circles-1862', 'Hip Circles', '[]', '[]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1862/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1863', 'hip-crossover-1863', 'Hip Crossover', '[]', '[]', 'Lie on your back with your arms stretched out to the sides and your knees bent, legs together. Slowly lower both knees to one side while keeping your shoulders and arms on the floor. You should feel a stretch in your hips, glutes and lower back. Hold briefly, bring your knees back to the centre and repeat on the other side.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1863/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1864', 'ankle-roll-1864', 'Ankle Roll', '[]', '[]', 'Sit on the floor and lift one foot off the ground, for example by resting that leg on the other knee. Slowly draw circles with your foot, moving only at the ankle. Do several circles in both directions, then switch feet.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1864/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1865', 'banded-ankle-mobility-1865', 'Banded Ankle Mobility', '[]', '[]', 'Anchor a resistance band low behind you, for example at the bottom of a rack, and loop it around the front of your ankle, just above the foot. Get into a half-kneeling position with the banded foot in front, so that the band pulls your ankle backwards. Keeping your heel on the floor, drive your knee forward over your toes, then return under control. Repeat for several reps and switch sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1865/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1867', 'hip-flexor-stretch-1867', 'Hip Flexor Stretch', '[]', '["none (bodyweight exercise)"]', 'Kneel in a lunge position with one knee on the floor and the other foot in front, hands on your hips. Keep your torso upright, squeeze the glute of the back leg and push your hips forward until you feel a stretch at the front of the hip and thigh. Hold, then switch sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1867/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1868', 'lunge-with-twist-stretch-1868', 'Lunge with Twist Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1868/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1869', 'lying-figure-four-stretch-1869', 'Lying Figure Four Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1869/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1870', 'lying-hamstring-stretch-with-band-1870', 'Lying Hamstring Stretch with Band', '[]', '["resistance band"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1870/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1872', 'pigeon-stretch-1872', 'Pigeon Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1872/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1873', 'quad-stretch-1873', 'Quad Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1873/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1874', 'runners-lunge-stretch-1874', 'Runners Lunge Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1874/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1875', 'standing-it-band-stretch-1875', 'Standing IT Band Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1875/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1876', 'supported-calf-stretch-1876', 'Supported Calf Stretch', '[]', '["none (bodyweight exercise)"]', 'View the video to undestand the exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1876/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1877', 'banded-scapular-retraction-1877', 'Banded Scapular Retraction', '["shoulders"]', '["resistance band"]', 'Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'hurr99', 'https://wger.de/en/exercise/1877/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1879', 'incline-db-y-raise-1879', 'Incline DB Y-Raise', '["shoulders"]', '["dumbbell"]', 'Set an incline bench to a 45-degree angle and sit facing the bench, chest against the pad, with a dumbbell in each hand, palms facing each other. Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows. Engage your core and keep your back straight throughout the movement. Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent. Lift until your arms are roughly parallel to the floor and in line with your ears. Pause briefly at the top of the movement to engage your shoulder muscles fully, then slowly lower your arms back down to the starting position. Ensure the movement is slow and controlled during both the ascent and descent to maximize engagement of the deltoids and supporting muscles. Repeat for the desired number of repetitions, maintaining proper form throughout.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1879/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1881', 'db-wrist-extension-1881', 'DB Wrist Extension', '[]', '["dumbbell"]', 'Grab two dumbbells with an overhand grip and lay your forearms across your knees. Let your wrists flex fully, then extend your wrists.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1881/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1882', 'high-cable-lateral-raise-1882', 'High-Cable Lateral Raise', '["shoulders","lats"]', '["cable machine"]', 'Stand next to a cable machine with the pulley set to waist height. Grab the opposite-side handle with the hand farthest from the pulley, keeping your palm facing in. Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift. Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow. Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1882/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1884', 'shinbox-ir-stretch-1884', 'Shinbox IR Stretch', '["glutes"]', '["none (bodyweight exercise)"]', 'Starting Position: Sit on the floor with both hips and knees bent at 90-degree angles. Leg Placement: Place one leg in front of you (external rotation) and the other leg out to the side/behind you (internal rotation). The shins and knees should remain flat on the ground. The Movement: Keeping your hips square, hinge your torso forward or tilt it laterally (side-to-side) toward the front leg to deepen the stretch. Target Areas: Stretches the glutes and piriformis (front leg) and the hip flexors and quads (back leg). Engages the core and obliques during lateral flexion. Goal: Improves hip mobility, specifically internal and external rotation, and relieves lower back tension.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1884/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1885', 'ytwl-exercise-1885', 'YTWL Exercise', '["shoulders"]', '["dumbbell","incline bench"]', 'Purpose: Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups. Starting Position: Stand with feet shoulder-width apart. Hinge forward at the hips (like a deadlift) keeping your back flat, or lie face down on an incline bench. Keep your thumbs pointing up throughout. Y (Arms up): Extend both arms straight forward and upward at a 135-degree angle from your body, forming a "Y". Squeeze your shoulder blades together at the top. T (Arms out): Open your arms straight out to the sides, perpendicular to your body, forming a "T". Focus on pinching your shoulder blades. W (Arms bent): Pull your elbows back, bending them to 90 degrees, and squeeze your shoulder blades to form a "W". Keep your wrists firm. L (Arms rotated): Start with elbows bent at 90 degrees and close to your body. Rotate your forearms outward (external rotation) like a goalpost, forming an "L" or a gate. Key Focus: Movements should be slow and controlled. Always lead with the thumbs and think about moving the shoulder blades, not just the arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1885/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1886', 'supine-hip-abduction-1886', 'Supine Hip Abduction', '["glutes","quads"]', '["dumbbell"]', 'Starting Position: Lie on your back (supine) on a mat, with your legs extended and relaxed. Arms can be placed alongside your body or out to the sides for stability. The Movement: Slightly lift one leg off the floor (keeping it straight or with a slight bend). Move it laterally outward, away from the other leg, as if stepping over a small obstacle. Range of Motion: Move the leg as far as comfortable without lifting your pelvis or rotating your torso, feeling a stretch in the inner thigh and hip. Return: Slowly bring the leg back to the starting position with controlled movement. Goal: Improves lateral hip mobility (abduction) and strengthens the pelvic stabilizer muscles.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1886/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1889', 'decline-bench-leg-raise-1889', 'Decline Bench Leg Raise', '["abs"]', '["incline bench"]', 'Setup : Lie on a decline bench with your head at the top and grip the handles. The Start : Extend legs fully, keeping them slightly elevated to engage your core. The Lift : Raise your legs toward the ceiling using your abs, not momentum. The Squeeze : Pause and contract your lower abdominals at the top. The Return : Lower your legs slowly to the starting position with control.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1889/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1893', 'overhead-barbell-press-1893', 'Overhead Barbell Press', '["shoulders"]', '["barbell"]', 'Setup: Stand with feet together and grip the bar slightly wider than shoulders. Position: Rest the bar on your upper chest. Press: Brace your core and push the bar straight up until your arms lock out. Finish: Control the bar back down to your chest. https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1893/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1900', 'tricep-rope-pushdowns-1900', 'Tricep Rope Pushdowns', '["triceps","lats"]', '["cable machine"]', 'Setup: Stand facing the cable, feet shoulder-width apart, with a slight forward lean. Grip: Hold the rope with palms facing each other and elbows tucked tight to your ribs. Execution: Push the rope down until arms are fully straight, pulling the ends apart at the bottom. Control: Keep upper arms still and return to the start with a slow, controlled motion.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1900/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1901', 'clean-and-press-1901', 'Clean and Press', '["shoulders","quads"]', '["barbell"]', 'The First Pull: Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant. The "Power" Position: As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum. The Quick Elbow Turnover: In the catch phase, rotate your elbows rapidly under the bar to create a "shelf" on your front deltoids. The Vertical Press: Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1901/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1902', 'weighted-push-ups-1902', 'Weighted push-ups', '["chest","triceps"]', '["none (bodyweight exercise)"]', 'Setup: Begin in a standard plank position with a weight plate balanced securely on your upper back. Alignment: Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging. Execution: Lower your body until your chest nearly touches the floor, keeping your elbows at a forty-five degrees . Ascent: Press through your palms to return to the starting position, fully extending your arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1902/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1904', 'pec-deck-1904', 'Pec Deck', '["chest"]', '[]', 'Pectoral issolation exercise - full range of motion is best with full contraction and slow negative', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1904/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1905', 'pullback-1905', 'Pullback', '["biceps","lats"]', '["cable machine"]', 'Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1905/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1906', 'hip-bridge-1906', 'Hip Bridge', '["glutes","abs"]', '["none (bodyweight exercise)"]', 'Get into bridge position, balance yourself on heels and start extending legs unilaterally. Keep hip extended as much as possible.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1906/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1907', 'unilateral-lunges-1907', 'Unilateral Lunges', '["glutes","quads","hamstrings"]', '["none (bodyweight exercise)"]', 'No stops during movement, hands on the hips.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1907/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1908', 'butterfly-superman-1908', 'Butterfly Superman', '[]', '["none (bodyweight exercise)"]', 'Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1908/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1909', 'leg-wheel-1909', 'Leg Wheel', '["abs"]', '["none (bodyweight exercise)"]', 'Lay on the back and lift legs in perpendicular fashion, keeping the knees together. Start making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1909/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1910', 'kneeling-superman-1910', 'Kneeling Superman', '["hamstrings","abs"]', '["none (bodyweight exercise)"]', 'Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled. Extend arm forward with focus having the shoulder high up. Unilateral and static hold.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1910/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1911', 'cat-plank-1911', 'Cat Plank', '["quads","abs","shoulders"]', '["none (bodyweight exercise)"]', 'On your fours and raise the knees of the floor ever so slightly. Curl your back out and push back from your shoulders as to resemble a cat making itself look large.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1911/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1912', 'core-rotation-1912', 'Core Rotation', '["quads","abs"]', '["none (bodyweight exercise)"]', 'Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1912/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1913', 'unilateral-hip-thrust-1913', 'Unilateral Hip Thrust', '["glutes","abs"]', '["none (bodyweight exercise)"]', 'Extend one leg while laying down and start raising your body with one leg touching the ground through the heel.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1913/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1914', 'isometria-alle-parallele-1914', 'Isometria alle parallele', '["chest"]', '[]', 'The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1914/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1915', 'quadruped-hip-abduction-1915', 'Quadruped Hip Abduction', '[]', '["resistance band"]', 'Distribute your body weight evenly on all knees and arms. Keep the torso stable, with the abdomen engaged and the lumbar spine straight without twisting the back (imagine: a glass on your lower back won''t fall off). Raise one leg outwards without twisting it. Pay attention to the right angle at the hips and knees. Always train both sides of the body. To increase resistance, a resistance band can be used.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'treder', 'https://wger.de/en/exercise/1915/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1916', 'tuck-planche-1916', 'Tuck planche', '["shoulders","abs","chest","triceps"]', '["none (bodyweight exercise)"]', 'Basic calisthenics progression for the full planche', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ISSACS', 'https://wger.de/en/exercise/1916/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1918', 'legend-chest-press-1918', 'Legend Chest Press', '["chest","shoulders","triceps"]', '[]', 'Plate-loaded chest press machine from Legend Fitness LeverEdge line.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1918/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1919', 'extreme-pec-stretch-1919', 'Extreme Pec Stretch', '[]', '["none (bodyweight exercise)"]', 'Deep loaded stretch for pectorals, typically performed at end of chest work.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1919/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1920', 'extreme-shoulder-stretch-1920', 'Extreme Shoulder Stretch', '[]', '["none (bodyweight exercise)"]', 'Deep loaded stretch for deltoids, performed after pressing movements.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1920/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1921', 'extreme-lat-stretch-1921', 'Extreme Lat Stretch', '[]', '["none (bodyweight exercise)"]', 'Deep loaded stretch for latissimus dorsi, performed after pulling movements.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1921/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1922', 'seated-cable-chest-fly-1922', 'Seated Cable chest fly', '["chest"]', '["cable machine"]', 'Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated. Grab the handles with a neutral grip and lean against the upright backrest. Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement. Pause briefly at the top position. Slowly lower your arms back to the starting position while maintaining control of the movement. Repeat for reps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'shushu', 'https://wger.de/en/exercise/1922/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1924', '3008-abdominal-crunch-1924', '3008 Abdominal Crunch', '["abs"]', '["none (bodyweight exercise)"]', 'This is especially for the gym80 device 3008 Abdominal Crunch.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1924/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1925', 'barbell-silverback-shrug-1925', 'Barbell Silverback Shrug', '[]', '["barbell"]', 'Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width. Bend forward at the hips with a slight bend in your knees, keeping your back straight. Engage your shoulder blades, as if you are trying to touch them together. Release the shrug. Description taken from MuscleWiki', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1925/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1927', 'inverted-lat-pull-down-1927', 'Inverted Lat Pull Down', '["lats","biceps","abs"]', '["pull-up bar"]', 'The Inverted Lat Pull Down (most commonly known as the Reverse Grip Lat Pull Down ) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the lower lats and increases biceps involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1927/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1928', 'seated-v-grip-row-1928', 'Seated V-Grip Row', '["lats","shoulders","biceps","abs"]', '["cable machine"]', 'The Seated V-Grip Row is a compound pulling exercise performed on a cable machine using a close-grip "V" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on back thickness and mid-back development.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1928/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1929', 'assisted-pull-up-1929', 'Assisted Pull-Up', '["lats","shoulders","biceps","abs"]', '["resistance band"]', 'The Assisted Pull-Up is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1929/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1931', 'dumbbell-curl-1931', 'Dumbbell Curl', '["biceps","shoulders","abs"]', '["dumbbell"]', 'The Dumbbell Curl is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1931/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1933', 'abdominal-crunch-1933', 'Abdominal Crunch', '["abs"]', '["gym mat"]', 'The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1933/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1935', 'belt-squat-1935', 'Belt Squat', '["glutes","quads","hamstrings"]', '[]', 'Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1935/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1936', 'cable-rear-delt-fly-single-arm-1936', 'Cable Rear-Delt Fly (single arm)', '[]', '["cable machine"]', 'Cable rear delt fly (single arm): Stand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use light to moderate weight and controlled reps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Dulive', 'https://wger.de/en/exercise/1936/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1938', 'cat-cow-1938', 'Cat-Cow', '[]', '[]', 'On all fours. Arch spine up (cat) then drop it down (cow). Breathe with movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1938/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1939', 'neck-cars-1939', 'Neck CARs', '[]', '[]', 'Controlled Articular Rotations. Slow full circles 3 each way. Cervical mobility.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1939/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1940', 'diaphragmatic-breathing-1940', 'Diaphragmatic Breathing', '[]', '[]', 'Belly breathing. Hand on chest stays still, hand on belly rises. 8-10 slow breaths.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/1940/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1947', 'dumbbell-snatch-1947', 'dumbbell snatch', '["hamstrings","glutes","quads"]', '["dumbbell"]', 'Key Steps to Execute Correctly: Setup: Place the dumbbell between your feet, with your shoulders above your hips, chest up, and back flat. The Pull: Explosively extend your hips, knees, and ankles (triple extension) to drive the dumbbell upward, keeping your elbow high and the dumbbell close to your body. The Catch: Quickly flex your hips and knees to drop under the dumbbell and receive it overhead with your arm locked in position, landing in a half-squat stance. Common Mistakes: Using your arms too much to lift the weight instead of your legs, having a low elbow during the pull phase, and misaligning your shoulder, elbow, and wrist in the final position. For beginners, it’s recommended to start with light loads, focus on technique, and perform 3 to 5 sets of 3 to 5 reps per arm.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Aleid', 'https://wger.de/en/exercise/1947/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1948', '1-leg-box-squat-1948', '1 Leg Box Squat', '["hamstrings","quads"]', '["none (bodyweight exercise)"]', 'This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'jesusd', 'https://wger.de/en/exercise/1948/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1949', 'limber-11-1949', 'Limber 11', '[]', '[]', 'Limber 11 Source: Joe DeFranco 1. Foam Roll IT Band [soft_tissue] - 10-15 passes 2. Foam Roll Adductors [soft_tissue] - 10-15 passes 3. SMR Glutes (lax ball) [soft_tissue] - 30 sec-2 min 4. Bent-knee Iron Cross [dynamic] - 5-10 reps each side 5. Roll-overs into V-sits [dynamic] - 10 reps 6. Rocking Frog Stretch [dynamic] - 10 reps 7. Fire Hydrant Circles [dynamic] - 10 forward / 10 backward 8. Mountain Climbers [dynamic] - 10 reps each leg 9. Cossack Squats [dynamic] - 5-10 reps each side 10. Seated Piriformis Stretch [isometric] - 20-30 sec each side 11. Rear-foot-elevated Hip Flexor Stretch [dynamic + 3s hold] - 5-10 reps each side', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation probe', 'https://wger.de/en/exercise/1949/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1950', 'foam-roll-it-band-1950', 'Foam Roll IT Band', '[]', '[]', 'Foam Roll IT Band Part of: Limber 11 Source: Joe DeFranco Prescription: 10-15 passes Type: soft_tissue', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1950/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1952', 'smr-glutes-lax-ball-1952', 'SMR Glutes (lax ball)', '[]', '[]', 'SMR Glutes (lax ball) Part of: Limber 11 Source: Joe DeFranco Prescription: 30 sec-2 min Type: soft_tissue', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1952/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1953', 'bent-knee-iron-cross-1953', 'Bent-knee Iron Cross', '[]', '[]', 'Bent-knee Iron Cross Part of: Limber 11 Source: Joe DeFranco Prescription: 5-10 reps each side Type: dynamic', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1953/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1954', 'roll-overs-into-v-sits-1954', 'Roll-overs into V-sits', '[]', '[]', 'Roll-overs into V-sits Part of: Limber 11 Source: Joe DeFranco Prescription: 10 reps Type: dynamic', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1954/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1956', 'fire-hydrant-circles-1956', 'Fire Hydrant Circles', '[]', '[]', 'Fire Hydrant Circles Part of: Limber 11 Source: Joe DeFranco Prescription: 10 forward / 10 backward Type: dynamic', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1956/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1959', 'seated-piriformis-stretch-1959', 'Seated Piriformis Stretch', '[]', '["none (bodyweight exercise)"]', 'Seated Piriformis Stretch Part of: Limber 11 Source: Joe DeFranco Prescription: 20-30 sec each side Type: static Includes isometric hold.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1959/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1960', 'rear-foot-elevated-hip-flexor-stretch-1960', 'Rear-foot-elevated Hip Flexor Stretch', '[]', '["none (bodyweight exercise)"]', 'Rear-foot-elevated Hip Flexor Stretch Part of: Limber 11 Source: Joe DeFranco Prescription: 5-10 reps each side Type: dynamic Includes dynamic movement plus 3s hold.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1960/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1962', 'step-jack-1962', 'Step Jack', '["quads","shoulders","glutes","abs"]', '["none (bodyweight exercise)"]', 'The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate. Notes (Instructions): ​Stand upright with your feet together and arms at your sides. ​Step your right foot out to the side while simultaneously swinging both arms up above your head. Bring your right foot back to the center and lower your arms. ​Immediately repeat the movement, stepping out with your left foot. ​Continue alternating sides at a steady, rhythmic pace.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1962/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1963', 'slow-squat-1963', 'Slow Squat', '["quads","hamstrings","glutes","abs"]', '["none (bodyweight exercise)"]', '​A tempo-based squat that uses controlled movement to increase muscle tension and improve lower-body stability. ​Lower: Descend slowly for 3 seconds. ​Pause: Hold at the bottom for 1 second. ​Stand: Return to the starting position at a normal pace. Form: Keep your chest up and weight in your heels.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1963/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1964', 'wide-push-up-1964', 'Wide Push-Up', '["chest","abs","triceps"]', '["none (bodyweight exercise)"]', '​A push-up variation with a wider hand placement to increase the emphasis on the outer chest muscles and shoulders. ​Setup: Place hands wider than shoulder-width apart on the floor. Lower: Descend until your chest nearly touches the floor, keeping your core tight. ​Push: Drive through your palms to return to the start position. ​Form: Don''t let your lower back sag; keep a straight line from head to heels.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1964/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1965', 'marching-high-knees-1965', 'Marching High Knees', '["quads","calves","glutes","abs"]', '["none (bodyweight exercise)"]', 'A low-impact cardio and mobility exercise that strengthens the hip flexors and improves balance. ​Movement: Stand tall and lift one knee toward your chest as high as comfortable. ​Arms: Swing the opposite arm forward as you lift your knee, similar to a walking motion. ​Core: Keep your abs engaged to maintain an upright posture. ​Pace: Perform the movement with control, alternating legs rhythmically.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1965/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1966', '1-2-kneeling-thoracic-rotation-1966', '1/2 Kneeling Thoracic Rotation', '[]', '["none (bodyweight exercise)"]', 'Begin in a half kneeling position with the leg away from the wall stabilized against the wall with a ball. With both hands directly in front of you, rotate one arm open attempting to reach the wall behind you. Exhale as you rotate, inhale as you return to neutral and repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'amwang4', 'https://wger.de/en/exercise/1966/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1967', 'lento-avanti-seduto-1967', 'lento avanti seduto', '["shoulders"]', '["dumbbell"]', 'slow controlled seated forward exercise with dumbbells', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Cf', 'https://wger.de/en/exercise/1967/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1968', 'single-arm-dumbbell-shoulder-press-1968', 'Single-arm dumbbell shoulder press', '["shoulders","abs","triceps"]', '["dumbbell"]', 'Press the dumbbell vertically overhead in a controlled motion until your arm is fully extended, without locking the elbow. Slowly lower the dumbbell back to the starting position at shoulder height.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'evtimovgeorg', 'https://wger.de/en/exercise/1968/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1969', 'single-arm-cable-pushdown-1969', 'Single-arm cable pushdown', '["triceps","abs"]', '["cable machine"]', 'Single-arm cable pushdown is a unilateral isolation exercise that targets the triceps brachii. By working one arm at a time, it helps correct strength imbalances between sides while also engaging the core for stability. Starting position: Stand facing the cable machine with your feet shoulder-width apart. Attach a single handle to the high pulley. Grab the handle with one hand using an overhand grip (pronated), with your elbow bent at approximately 90° and tucked close to your body. Keep your core braced and your back straight. Execution: Push the handle downward in a controlled motion by extending your elbow until your arm is fully extended. Hold the contraction for 1 second at the bottom, then slowly return to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'evtimovgeorg', 'https://wger.de/en/exercise/1969/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1970', 'kettlebell-sumo-high-pull-1970', 'Kettlebell sumo high pull', '["shoulders","hamstrings","glutes","quads"]', '["kettlebell"]', 'A compound exercise combining elements of a sumo deadlift and a high pull. It targets the posterior chain, particularly the glutes, hamstrings, and upper back. The sumo stance increases hip engagement, while the high pull adds an explosive element, promoting power development. Stand upright overtop of a kettlebell with your feet wider than shoulder-width apart angled out slightly. Maintain a braced core and neutral spine throughout the exercise. Hinge your hips backward and extend your arms to grab ahold the kettlebell with a double overhand grip. With you lower legs nearly vertical to the ground, extend your hips to raise the kettlebell with your elbows high keeping it close to your body. Once the kettlebell has reached shoulder height, lower back to the starting position.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wgerpott', 'https://wger.de/en/exercise/1970/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1971', 'mentzer-pulldown-1971', 'Mentzer Pulldown', '["biceps","lats"]', '["cable machine","incline bench"]', 'Close grip front facing Pull down, while focusing on Biceps, Increases activation of biceps over the whole range, Avoid activating Lats.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mike Mentzer', 'https://wger.de/en/exercise/1971/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-1972', 'single-arm-lat-pulldown-1972', 'Single-Arm Lat Pulldown', '["lats","biceps"]', '["cable machine"]', 'Sit at the lat pulldown machine and grab the single handle with a neutral grip. Keep your torso stable, your chest lifted, and your shoulder blades slightly retracted. Start with your arm fully extended overhead, then pull the handle down toward your upper chest following a controlled, slightly diagonal path. Focus on engaging the latissimus dorsi while keeping the shoulder depressed and avoiding any torso rotation. Slowly return to the starting position, maintaining full control throughout the movement.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'evtimovgeorg', 'https://wger.de/en/exercise/1972/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2447', 'hip-airplane-2447', 'Hip Airplane', '["glutes","hamstrings","calves"]', '["kettlebell"]', 'Stand on one leg and lean your upper body slightly forward while keeping your back straight. Extend the free leg behind you so that your torso and leg form roughly one line. Slowly open your hip to the side by rotating your pelvis and upper body in a controlled way. Then close the hip again and return to the starting position. The movement should mainly come from the hip. Keep your standing foot stable and avoid letting your knee collapse inward.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2447/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2448', 'reverse-clamshell-2448', 'Reverse Clamshell', '["glutes"]', '["none (bodyweight exercise)"]', 'Lie on your side with your hips and knees bent, keeping your knees stacked on top of each other. Keep your feet together at first, then keep your knees touching while lifting your top foot upward. Slowly lower the foot back down with control. Move only through the hip and avoid rolling your pelvis backward. The movement should be small, controlled, and focused on hip rotation.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2448/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2449', 'clamshell-to-reverse-clamshell-2449', 'Clamshell to Reverse Clamshell', '["glutes"]', '["none (bodyweight exercise)"]', 'Lie on your side with your hips and knees bent, keeping your legs stacked. Lift your top knee into a clamshell position and keep the leg elevated throughout the movement. From there, alternate between opening the knee upward and lifting the foot upward, moving through hip external and internal rotation. Keep the movement slow and controlled. Do not let the top leg rest on the bottom leg between repetitions.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2449/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2452', 'curl-de-mu-eca-con-barra-2452', 'Curl De Muñeca Con Barra', '[]', '["barbell","bench"]', 'This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso. Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders. Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it. Your wrists and hands should extend slightly beyond the edge of the bench to allow for a full range of motion. Eccentric Phase (Lowering): Lower the bar in a controlled manner by extending your wrists toward the floor. At the bottom of the movement, slightly spread your fingers to let the bar roll down a bit, maximizing the stretch. Concentric Phase (Lift): First, close your fingers to secure the bar, then flex your wrists upward explosively but in a controlled manner, bringing the bar as high as possible. Strongly contract your forearms at the top position for one second. Form: Keep your forearms firmly pressed against the bench throughout the exercise; only your wrists and fingers should move.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'xWan', 'https://wger.de/en/exercise/2452/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2454', 'ytw-raises-2454', 'YTW Raises', '["shoulders"]', '["none (bodyweight exercise)"]', 'The YTW exercise for scapular retraction is designed to strengthen the inter-scapular muscles between your shoulder blades, to help retract or pull your shoulders back, helping to maintain proper upright posture.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'probablyforging', 'https://wger.de/en/exercise/2454/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2478', 'glute-ham-raise-2478', 'Glute-Ham Raise', '["hamstrings","glutes"]', '["bench"]', 'Kneel on a glute-ham developer or have a partner hold your ankles. Keeping hips straight, lower your torso toward the floor under control, then curl back up by contracting the hamstrings and glutes.', '2026-10-28T22:02:36.153Z', 'CC0', 'personal use', 'https://wger.de/en/exercise/2478/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2480', 'easy-continuous-swim-freestyle-2480', 'Easy Continuous Swim (Freestyle)', '["shoulders","lats","chest","hamstrings","calves","glutes","quads","abs","triceps"]', '[]', 'Swim freestyle at a relaxed, steady pace without stopping - think conversation pace, not racing. Focus on smooth, even strokes rather than speed or breathing technique; this is just to get your body moving and your heart rate up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2480/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2481', 'kick-with-board-2481', 'Kick with Board', '["glutes","quads","hamstrings","calves","abs"]', '[]', 'Hold a kickboard with both hands, arms extended in front of you, face in the water (lift head forward to breathe when needed). Kick from your hips, not your knees, keeping your legs mostly straight with a slight bend and a steady, compact flutter kick. This builds leg endurance and keeps your body horizontal without needing to worry about your arms.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2481/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2482', 'bobbing-exhale-drill-2482', 'Bobbing Exhale Drill', '["abs"]', '[]', 'Stand in chest-deep water. Take a breath, submerge your face fully, and exhale slowly and completely through your nose and/or mouth the whole time you''re underwater - a gentle humming sound can help keep the exhale steady and controlled. Once you''re empty of air, lift your head, take a fresh breath, and go back under. Repeat continuously. The goal is training your body that all your exhaling happens underwater, so all you need to do at the surface is inhale.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2482/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2483', 'wall-hold-rotation-2483', 'Wall-Hold Rotation', '["abs"]', '[]', 'Hold the pool wall or edge with one hand, body horizontal at the surface, legs kicking gently behind you. Keep your face in the water, exhaling continuously, then rotate your head to the side - not lifting it up - so one goggle stays in the water while the other clears the surface. Take a quick breath, then rotate your face back down to neutral. This isolates the head-rotation motion without any arm strokes to think about.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2483/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2484', 'side-kick-breathing-kickboard-2484', 'Side-Kick Breathing (Kickboard)', '["glutes","shoulders","hamstrings","quads"]', '[]', 'Push off the wall on your side (not flat on your stomach), one arm extended forward holding the board or just extended, kicking continuously. Keep your head in a neutral position looking at the bottom of the pool, and when you need air, rotate your head sideways (one ear stays in the water, other faces up) to breathe, then rotate back to neutral. Swim a length like this, then repeat on the other side. This teaches the exact head position and rotation you''ll use once full stroke breathing comes in.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2484/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2485', 'stroke-and-roll-drill-2485', 'Stroke-and-Roll Drill', '["shoulders","lats","abs"]', '[]', 'Push off, swim a few strokes, and every breath roll fully onto your back for 2-3 breaths, then roll back into freestyle. This teaches you to rotate your body as a unit rather than just turning your head, and helps remove the fear of not having your face in the water.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2485/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2486', 'recovery-bobbing-2486', 'Recovery Bobbing', '["abs"]', '[]', 'Same motion as the Bobbing Exhale Drill, but done in slightly deeper water (so you''re not touching the bottom) and at a slower, more relaxed pace - think of it as a recovery/reset exercise rather than a hard drill. Use it between harder drills to reset your breathing rhythm and calm down if you''re feeling rushed or out of sync.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2486/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2487', 'cool-down-swim-2487', 'Cool-Down Swim', '["shoulders","lats","chest","glutes","abs","triceps"]', '[]', 'Swim at an easy, unhurried pace - freestyle, backstroke, or just floating/gliding - with zero focus on technique or drills. The only goal here is to let your heart rate come down gradually and your muscles relax before you get out of the pool.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2487/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2488', 'posterior-pelvic-tilt-2488', 'Posterior Pelvic Tilt', '["abs","glutes"]', '["none (bodyweight exercise)"]', 'Lie on your back with knees bent, feet flat on the floor. Flatten your lower back against the floor by tilting your pelvis posteriorly, engaging your abs and glutes. Hold 5 seconds, release. This retrains pelvic positioning to counter anterior pelvic tilt.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Raj', 'https://wger.de/en/exercise/2488/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2494', 'band-terminal-knee-extension-2494', 'Band Terminal Knee extension', '["quads"]', '["resistance band"]', 'This is an end range strengthening exercise for the knee extensors. Start by looping a band around the back of one knee and anchoring the other end to a stable surface in front of you. Stand in a split stance with the banded knee bent and placed as the front leg. Straighten the knee to pull against the bands resistance and maintain a contraction in your quadriceps for up to 5 seconds before releasing.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Rehab Hero', 'https://wger.de/en/exercise/2494/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2523', 'serratus-wall-slide-stretch-2523', 'Serratus Wall Slide Stretch', '[]', '[]', 'Stand facing a wall. Place your forearms vertically against the wall so your elbows and wrists are both touching it. Point your arms slightly outwards from "straight up". Protract your shoulders had, then slide your forearms up the wall until your elbows are about level with your chin. Slide your forearms back down the wall. Repeat as necessary.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2523/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2525', 'couch-stretch-2525', 'Couch Stretch', '[]', '["bench"]', 'Stand facing away from a bench, couch or similar-height object. Extend one leg backwards, resting your foot "laces-down" on the edge of the bench. Lower yourself until your rear knee is on the floor and you are in a lunge position, with your torso hanging forwards slightly. Brace your core, tense your rear glute, and straighten up your torso to vertical, under control. Relax and repeat. Repeat for the other leg, too.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2525/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2526', 'long-lunge-pulse-stretch-2526', 'Long Lunge Pulse Stretch', '[]', '["resistance band"]', 'Hold the resistance band (or any other rope-like object, the elasticity is not necessary) above your head, between your hands, with your arms straight. Pull it taught to engage your lats. Step forwards into a lunge, dropping until your knee is almost touching the floor. Slowly and controlledly pulse your body up and down by about an inch. Repeat for required reps. Repeat for other leg.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2526/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2527', 'front-split-stretch-2527', 'Front Split Stretch', '["hamstrings","quads","calves"]', '["gym mat"]', 'Start kneeling. Extend one leg out forwards, fully straightened. Follow with your hips so your back leg begins to unfold. Carefully lower yourself into the stretch. Do not go beyond your limit. Hold for the required time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2527/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2528', 'squat-sky-reach-stretch-2528', 'Squat Sky Reach Stretch', '["lats","chest"]', '[]', 'Drop into a squat. Hold one ankle with the opposite hand. Fold your other arm to your chest. Staying in the squat and keeping hold of your ankle, twist to turn your chest-hand back/outwards until your elbow is pointing at the sky. Return to the neutral squatting position with your hand on your chest. Repeat movement as required. Repeat on both sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2528/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2529', 'explosive-push-ups-2529', 'explosive push ups', '["chest","shoulders","triceps"]', '["none (bodyweight exercise)"]', 'Explosive Push-Ups Start in a standard push-up position, lower your chest, then explosively push off the ground so your hands leave the floor. Land softly and immediately repeat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2529/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2530', 'russian-push-ups-2530', 'Russian Push Ups', '["chest","shoulders","abs","triceps"]', '["none (bodyweight exercise)"]', 'Russian Push-Ups Start in a standard push-up position with your hands slightly wider than shoulder-width apart. Lower your chest toward the floor, then shift your body forward while keeping your chest close to the ground. Extend your arms to return to the starting position, then reverse the movement smoothly. Keep your core tight and maintain controlled movement throughout the exercise.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2530/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2531', 'elbow-lever-2531', 'elbow lever', '["abs","shoulders","triceps"]', '["none (bodyweight exercise)"]', '​A calisthenics static balance skill where the entire body is held straight and parallel to the ground, supported by tucking the elbows firmly into the abdomen or pelvic bones.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2531/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2532', 'planche-lean-hold-2532', 'Planche Lean Hold', '["shoulders","biceps","chest","abs"]', '["none (bodyweight exercise)"]', 'A straight-arm calisthenics static hold where you assume a plank position and lean the shoulders as far forward as possible past the wrists with protracted scapulae and a hollow body.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2532/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2533', 'arch-hang-2533', 'Arch Hang', '[]', '["pull-up bar"]', 'https://www.youtube.com/watch?v=C995b3KLXS4&t=7s Elbows should stay straight Hold it for time/reps Start at an active hang: https://www.youtube.com/watch?v=HoE-C85ZlCE Progress towards a 90 degree in your shoulder', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wintercyan', 'https://wger.de/en/exercise/2533/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2535', 'leg-extension-isometric-2535', 'Leg Extension Isometric', '["quads"]', '[]', 'An isometric leg extension is a strengthening exercise where you contract your quadriceps muscles against an immovable resistance without changing the length of the muscle or moving your knee joint.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2535/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2536', 'bench-press-isometric-2536', 'Bench Press Isometric', '["shoulders","chest","triceps","abs"]', '["barbell","bench"]', 'A bench press isometric hold is a static strength exercise where you pause and hold a barbell or dumbbells either at your chest, mid-press, or at lockout without moving for a set time', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2536/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2537', 'overhead-press-isometric-2537', 'Overhead Press Isometric', '["shoulders","triceps"]', '["barbell"]', 'An isometric overhead press involves holding a weight statically overhead or pushing against an immovable object at a specific point in the press without moving the joint.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2537/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2538', 'lateral-raise-isometric-2538', 'Lateral Raise Isometric', '["shoulders"]', '["dumbbell"]', 'An isometric lateral raise is a shoulder exercise where you hold your arms out to the sides at waist height for a set amount of time instead of moving up and down', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2538/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2539', 'preacher-curl-isometric-2539', 'Preacher Curl Isometric', '["biceps"]', '["dumbbell","sz-bar"]', 'An isometric preacher curl is a static strength exercise where you hold a fixed position on a preacher pad or and inclined bench under tension without moving the joint.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2539/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2540', 'lat-pulldown-isometric-2540', 'Lat Pulldown Isometric', '["lats"]', '["cable machine"]', 'An isometric Lat pulldown is a strength-building exercise where you pull the bar down to your chest and hold the contracted position at the bottom without moving your limbs for a set number of seconds', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2540/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2541', 'triceps-pushdown-isometric-2541', 'Triceps Pushdown Isometric', '["triceps"]', '["cable machine"]', 'A single-arm isometric or isolated triceps pushdown is an isolation cable exercise where you pin your upper arm against your torso, hinge at the hips, and extend the elbow to achieve a peak contraction in the triceps muscle.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2541/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2542', 'boxing-2542', 'Boxing', '["shoulders","triceps","biceps","lats"]', '[]', 'Bag workout for boxing skill development and cardio improvement', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'SAH', 'https://wger.de/en/exercise/2542/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2543', 'wrist-circles-2543', 'Wrist circles', '[]', '[]', 'Wrist circles is warm-up exercise, where you rotate your wrists in a circular motion. They improve mobility and are recommended before exercises such as pull ups, hand stands and other exercises that put pressure on your wrists.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Awlex', 'https://wger.de/en/exercise/2543/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2549', 'retro-treadmill-walking-2549', 'Retro Treadmill Walking', '[]', '[]', 'Controlled treadmill walking performed backward. Begin around 30 minutes at a controlled speed and approximately 2 to 3 percent incline if tolerated. Progress duration gradually as knee, hip, and back tolerance improves.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'Personal routine', 'https://wger.de/en/exercise/2549/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2555', 'kegel-exercise-2555', 'Kegel Exercise', '[]', '[]', 'Lie on your back with your knees bent, or sit upright in a chair. Locate the pelvic floor muscles: they are the muscles you would use to stop the flow of urine or to hold back gas. Keep your abdomen, glutes and thighs relaxed and breathe normally throughout. Tighten the pelvic floor muscles and lift them gently upwards and inwards. Hold the contraction for a few seconds, then release completely and rest for at least as long as you held. Repeat for the desired number of repetitions. The exercise can be varied by holding longer with a light contraction (endurance) or by performing quick, short contractions with a full relaxation in between.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger community', 'https://wger.de/en/exercise/2555/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2557', 'supported-split-squat-2557', 'Supported Split Squat', '["quads","glutes"]', '[]', 'Supported split squat performed with stable balance support and controlled depth.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger community', 'https://wger.de/en/exercise/2557/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2564', '90-90-breathing-2564', '90/90 Breathing', '[]', '[]', 'Controlled breathing drill performed in a 90/90 position to encourage rib, abdominal, and pelvic coordination.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 3', 'wger community', 'https://wger.de/en/exercise/2564/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2613', '90-90-hip-switches-2613', '90/90 Hip Switches', '["glutes"]', '["none (bodyweight exercise)"]', 'Sit on the floor with one leg bent at 90 degrees in front of you and the other leg bent at 90 degrees out to the side, so that the rear shin is parallel to the front shin. Keep your torso upright and, if possible, your hands off the floor. Rotate both knees over to the other side so that the legs swap positions and you arrive in the same 90/90 position facing the opposite way. Move slowly and under control, keeping the feet in contact with the floor, and alternate sides for the desired number of repetitions. Mobility drill for internal and external rotation of the hips.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2613/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2614', 'adductor-rock-backs-2614', 'Adductor Rock Backs', '["hamstrings","glutes"]', '["none (bodyweight exercise)"]', 'Start on all fours with your hands under your shoulders and your knees under your hips. Extend one leg straight out to the side with the foot flat on the floor and the toes pointing forward. Keep your back flat and slowly push your hips back towards the heel of the kneeling leg until you feel a stretch along the inside of the extended leg. Pause briefly, then return to the starting position. Complete all repetitions on one side before switching legs. Mobility exercise for the adductors and the hips.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2614/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2615', 'elevated-hamstring-stretch-2615', 'Elevated Hamstring Stretch', '["hamstrings"]', '["none (bodyweight exercise)"]', 'Stand facing a bar, box or bench at roughly hip height and place the heel of one leg on it. Keep that leg straight with the toes pointing up, and keep the standing leg straight with both hips square to the support. Hinge forward at the hips with a flat back until you feel a stretch in the back of the elevated thigh. Hold the position while breathing calmly, then switch legs. Stretch for the hamstrings. The height of the support controls the intensity: the higher the leg, the stronger the stretch.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2615/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2616', 'single-leg-bosu-balance-2616', 'Single-leg BOSU balance', '[]', '["none (bodyweight exercise)"]', 'Single-Leg BOSU Balance Exercise The exercise for balancing on a BOSU ball while standing on one leg is known as the single-leg BOSU balance exercise. This exercise is effective for enhancing balance, coordination, and core stability. Benefits of the Single-Leg BOSU Balance Exercise Improves Balance: Standing on one leg challenges your stability. Enhances Coordination: Engaging different muscle groups helps improve overall coordination. Strengthens Core: The exercise activates core muscles, promoting better posture and stability. How to Perform the Single-Leg BOSU Balance Exercise Positioning: Stand on the dome side of the BOSU ball with one leg. Balance: Keep your opposite leg lifted and your core engaged. Duration: Aim to hold the position for 10-20 seconds, gradually increasing the time as you improve. Progression Tips Add Movement: Try reaching for objects around you while maintaining balance. Close Your Eyes: This increases the challenge by removing visual stability cues. Use a Ball: Catch or toss a ball while balancing to further engage your core and coordination. This exercise is a great way to build foundational balance skills before progressing to more complex movements.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2616/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2617', 'quad-sets-2617', 'Quad Sets', '[]', '["gym mat"]', 'What Are Quad Sets? Quad sets are a fundamental exercise used in knee rehabilitation. They focus on strengthening the quadriceps muscles located at the front of the thigh. This exercise is particularly beneficial for individuals recovering from knee injuries or surgeries. How to Perform Quad Sets Steps to Execute Quad Sets Positioning: Sit or lie down with your legs straight. Tightening: Tighten the quadriceps muscles while keeping the leg straight. You should see the kneecap move upward. Holding: Maintain the contraction for about 5 seconds. Releasing: Relax the muscle after the hold. Repetitions: Aim for 10 to 15 repetitions, gradually increasing as strength improves. Tips for Effective Quad Sets Ensure no other muscles are contracting to assist the quadriceps. Perform the exercise on a flat surface, like a bed or couch, with a towel or pillow under your heel for comfort. It is recommended to do these exercises multiple times a day, especially during the early stages of recovery. Benefits of Quad Sets Restores Muscle Function: Helps rebuild strength in the quadriceps. Improves Stability: Enhances stability in the knee joint. Increases Range of Motion: Aids in regaining mobility after injury or surgery. Incorporating quad sets into your rehabilitation routine can significantly aid in recovery and improve overall knee function.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2617/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2618', 'hip-out-and-hip-in-lateral-steps-2618', 'Hip-Out and Hip-In Lateral Steps', '[]', '["resistance band"]', 'Overview of Hip-Out and Hip-In Lateral Steps Hip-out and hip-in lateral steps are effective exercises designed to strengthen the hip abductors and enhance lateral stability. These movements are beneficial for improving coordination and overall hip function. Exercise Descriptions Hip-Out Steps Movement: Step out to the side with one leg, keeping the other leg stable. Target Muscles: Primarily engages the hip abductors, including the gluteus medius and minimus. Benefits: Increases lateral stability and strength in the hip area. Hip-In Steps Movement: Bring the leg back in toward the center after stepping out. Target Muscles: Continues to engage the hip abductors while also activating the adductors. Benefits: Enhances coordination and control of the hip joint. Key Benefits of Lateral Steps | Benefit | Description | |---|---| | Strengthening Hip Abductors | Improves muscle strength around the hip joint. | | Enhancing Stability | Increases lateral stability, reducing the risk of falls. | | Improving Coordination | Develops better control and movement patterns in the hips. | Incorporating hip-out and hip-in lateral steps into a regular exercise routine can lead to improved hip strength and stability, which is essential for various physical activities and daily movements.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2618/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2619', 'single-leg-soft-landing-holds-2619', 'Single-Leg Soft-Landing Holds', '[]', '["none (bodyweight exercise)"]', 'Single-Leg Soft-Landing Holds Single-leg soft-landing holds are exercises that focus on balance and stability by landing softly on one leg and holding the position. This exercise helps improve proprioception and can be beneficial for rehabilitation and athletic training. Overview Single-leg soft-landing holds are exercises designed to enhance balance, stability, and proprioception. They involve landing softly on one leg and maintaining that position for a brief period. This exercise is particularly useful in rehabilitation settings and for athletes looking to improve their performance. Benefits Improves balance: Enhances stability by training the body to control weight distribution on one leg. Enhances proprioception: Increases awareness of body position, which is crucial for injury prevention. Supports rehabilitation: Helps individuals recover from lower-limb injuries by strengthening muscles and improving joint stability. How to Perform Single-Leg Soft-Landing Holds Steps Preparation: Stand on a stable surface or a box. Takeoff: Step off the box or surface with one leg, ensuring that you do not jump. Landing: Land softly on the target leg, allowing the knee and hip to bend slightly. Hold position: Maintain balance in the landed position for up to 2 seconds. Reset: Return to the starting position and repeat. Key Points to Remember Keep your chest up and engage your core for better stability. Ensure your knee aligns with the midline of your foot during landing. Focus on a controlled descent to minimize impact. Conclusion Incorporating single-leg soft-landing holds into your training routine can significantly enhance your balance and stability, making it a valuable exercise for both rehabilitation and athletic performance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2619/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2620', 'reverse-v-squat-2620', 'Reverse V-Squat', '["glutes","quads","hamstrings"]', '[]', 'Step into the V-squat machine facing the pad, the opposite way from the regular V-squat, so that your chest rests against the pad and your shoulders sit under the shoulder pads. Place your feet on the platform about shoulder width apart and release the safety. Brace your core and lower yourself by bending your knees and pushing the hips back until your thighs are roughly parallel to the platform. Drive back up through the heels without locking out the knees. Compared to the regular V-squat, the reversed position shifts the emphasis towards the glutes and hamstrings.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2620/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2621', 'box-handstand-push-up-2621', 'Box Handstand Push-up', '["shoulders","chest","triceps"]', '["none (bodyweight exercise)"]', 'Pike push-up with legs on an elevated surface. Progression to handstand push-up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Jarda', 'https://wger.de/en/exercise/2621/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2622', 'banded-front-raise-2622', 'Banded Front Raise', '["shoulders"]', '["resistance band"]', 'Stand on the middle of a resistance band with feet about hip-width apart, holding one end in each hand in front of your thighs. Keeping your arms straight with a slight bend in the elbows, raise your hands forward to shoulder height, then lower slowly under control. Can be done with both arms together or alternating. Use a heavier band or shorten the band to increase resistance.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2622/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2623', 'plate-loaded-lat-pulldown-2623', 'Plate-Loaded Lat Pulldown', '["lats","biceps"]', '[]', 'Sit at a plate-loaded (lever) lat pulldown machine with your thighs secured under the pads. Grip the handles overhead with arms fully extended. Pull the handles down toward your upper chest by driving your elbows down and back, squeezing your lats at the bottom. Return slowly to full extension. Resistance comes from weight plates loaded on the machine''s lever arms rather than a cable stack.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2623/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2624', 'lean-away-cable-lateral-raise-2624', 'Lean-Away Cable Lateral Raise', '["shoulders"]', '["cable machine"]', 'Set a cable pulley at the lowest position and attach a single handle. Stand side-on to the machine, hold the frame with your near hand and lean your body away so you hang at an angle. With the far hand, grasp the handle in front of your hips and raise your arm out to the side to shoulder height with a slight bend in the elbow. Lower slowly. The lean increases tension on the side delts at the bottom of the movement. Complete all reps, then switch sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2624/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2625', 'wall-baby-breathing-2625', 'Wall Baby Breathing', '[]', '[]', 'Custom description created by the Integrated Conditioning routine importer for wger.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2625/view/');
