INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2633', 'preacher-curl-machine-2633', 'Preacher Curl Machine', '["biceps"]', '[]', 'Custom description created by the Integrated Conditioning routine importer for wger.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2633/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2634', 'machine-dip-or-triceps-extension-2634', 'Machine Dip or Triceps Extension', '["triceps"]', '[]', 'Custom description created by the Integrated Conditioning routine importer for wger.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wger community', 'https://wger.de/en/exercise/2634/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2635', 'seated-band-row-2635', 'Seated Band Row', '["lats","biceps"]', '["resistance band"]', 'Sit on the floor with your legs straight out in front of you and your back tall. Loop a resistance band around the soles of both feet and hold one end in each hand, arms extended and a slight bend in the knees. Pull the band toward your lower ribs by driving your elbows straight back and squeezing your shoulder blades together. Keep your chest up and your torso still rather than rocking backward to move the band. Extend the arms slowly to return. Because the torso stays upright and supported, this is a useful row when a bent-over position is uncomfortable, and it needs no anchor point.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2635/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2636', 'flexbar-wrist-extension-2636', 'FlexBar Wrist Extension', '[]', '["none (bodyweight exercise)"]', 'Performed with a flexible resistance bar such as a Theraband FlexBar. Rest your forearm on your thigh or a table with the palm facing down and the wrist just past the edge. Hold the bar in that hand, let the wrist drop, then extend the wrist to raise the bar, keeping the forearm still. Lower slowly, taking about three seconds. The resistance comes from twisting or bending the flexible bar, so a thicker or stiffer bar increases the load. Commonly used for wrist and forearm strengthening and for elbow tendon rehabilitation.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2636/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2637', 'flexbar-wrist-flexion-2637', 'FlexBar Wrist Flexion', '[]', '["none (bodyweight exercise)"]', 'Performed with a flexible resistance bar such as a Theraband FlexBar. Rest your forearm on your thigh or a table with the palm facing up and the wrist just past the edge. Hold the bar in that hand, let the wrist extend back, then curl the wrist up to raise the bar while the forearm stays still. Lower slowly, taking about three seconds. Works the wrist flexors, and is the companion movement to FlexBar wrist extension for balanced forearm strengthening.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2637/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2638', 'flexbar-tyler-twist-2638', 'FlexBar Tyler Twist', '[]', '["none (bodyweight exercise)"]', 'An eccentric exercise for the wrist extensors, done with a flexible resistance bar such as a Theraband FlexBar, and widely used in rehabilitation for lateral epicondylitis (tennis elbow). Hold the bar vertically in the affected hand with the wrist extended. Grasp the top of the bar with the other hand, palm facing away, and twist the top hand to wind up the bar. Bring both arms out in front of you with the bar horizontal, then slowly let the affected wrist untwist the bar over about four seconds while the other hand holds steady. Reset and repeat. The reverse version, twisting in the opposite direction for the wrist flexors, is used for medial epicondylitis (golfer''s elbow). Move slowly and stop if the exercise causes sharp pain rather than the expected mild discomfort.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2638/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2639', 'roman-chair-rdls-2639', 'roman chair RDLS', '["hamstrings","glutes"]', '["dumbbell"]', 'this is a really cool descriptions for an exercise I''ve created several tomes now but this thing won''t save it', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'kbk', 'https://wger.de/en/exercise/2639/view/');
