INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2662', 'paused-squats-2662', 'Paused Squats', '["quads","hamstrings","glutes"]', '["barbell"]', 'Use the same technic as your normal squat. Except that you make a pause at the bottom of the squat for about 1-2 seconds, in other words a bit longer than your normal squat.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'bbk', 'https://wger.de/en/exercise/2662/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2663', 'single-arm-cable-row-w-rotation-floor-2663', 'Single-Arm Cable Row /w Rotation (floor)', '["lats"]', '["cable machine"]', 'Go into a one-legged kneeling position and grab the cable from the lowest position. Rotate the upper torso to get into the starting position and bend the upper torso a little bit sidewise. Place the unused hand on the knee. Pull the cable while rotating the upper torso.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'bbk', 'https://wger.de/en/exercise/2663/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2664', 'seated-knee-extension-with-overpressure-2664', 'Seated Knee Extension with Overpressure', '["hamstrings","quads"]', '["none (bodyweight exercise)"]', 'A gentle stretch to restore full knee extension. Sit with one leg stretched out in front of you and the heel propped on the floor or a low surface, so the knee is unsupported. Place both hands on the thigh just above the kneecap. Keeping the leg relaxed, gently press down through the hands toward the floor until you feel a stretch behind the knee, and hold for about three seconds before releasing. The pressure should produce a stretch, never sharp pain. Repeat for the prescribed number of repetitions, then switch legs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2664/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2665', 'banded-monster-walk-2665', 'Banded Monster Walk', '["glutes","quads"]', '["resistance band"]', 'A banded walking drill for the glutes and hip stabilisers. Place a mini band around both thighs just above the knees, or around the ankles for a harder version. Stand with feet hip-width apart so the band is under tension, then sink into a quarter-squat with the chest up. Walk forward with small diagonal steps, pushing each leg out against the band and keeping the knees tracking over the toes rather than letting them fall inward. Walk forward for the prescribed number of steps, then walk backward to return, keeping the band under tension throughout.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2665/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2666', 'step-calf-stretch-2666', 'Step Calf Stretch', '["calves"]', '["none (bodyweight exercise)"]', 'Stand on a step or a sturdy raised surface with the balls of both feet on the edge and the heels hanging off, holding a rail or wall for balance. Let one or both heels drop below the level of the step until you feel a stretch through the calf, and hold. Keep the knee straight to stretch the gastrocnemius, or bend the knee slightly to bias the soleus lower down. Hold for the prescribed time, typically 30 seconds, without bouncing, then switch sides if stretching one leg at a time.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2666/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2667', 'single-leg-balance-with-eyes-closed-2667', 'Single-Leg Balance with Eyes Closed', '["calves","glutes"]', '["none (bodyweight exercise)"]', 'A balance and proprioception drill. Stand on one leg with the knee slightly bent and the other foot lifted clear of the floor, then close your eyes and hold the position. Without visual feedback the ankle and hip stabilisers have to do the work, so expect noticeable wobble. Stand within reach of a wall, counter or chair so you can steady yourself if needed. Hold for the prescribed time, then switch legs. Commonly prescribed in rehabilitation after ankle or knee injury.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2667/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2668', 'single-leg-balance-with-kettlebell-circles-2668', 'Single-Leg Balance with Kettlebell Circles', '["glutes","shoulders","abs"]', '["kettlebell"]', 'A balance drill that adds a moving load. Stand on one leg with the knee slightly bent, holding a kettlebell in one hand. Pass the kettlebell around your body in a circle, handing it from one hand to the other in front and behind you, while keeping your balance on the standing leg. Keep the hips level and the torso upright; the shifting weight of the bell constantly changes your centre of mass, which is what trains the hip and ankle stabilisers. Complete the prescribed number of circles, reverse direction, then switch legs. Use a light bell to start.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2668/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2669', 'bent-over-dumbbell-rows-two-arms-2669', 'Bent Over Dumbbell Rows (Two Arms)', '["lats","biceps"]', '["dumbbell"]', 'How to Perform It Hold a dumbbell in each hand with a neutral or overhand grip. Hinge at the hips, pushing your glutes back, until your torso is roughly 45-75 degrees to the floor. Keep a slight bend in your knees. Let the dumbbells hang directly below your shoulders with arms fully extended. Keep your back flat, chest up, and core braced - avoid rounding your spine. Pull the dumbbells up toward your ribcage/hips, driving your elbows back and squeezing your shoulder blades together at the top. Pause briefly at the top of the movement. Lower the dumbbells back down under control to the starting position. Repeat for the desired number of repetitions. Key Coaching Cues Hinge from the hips, not the lower back Keep the spine neutral throughout - no rounding Lead with the elbows, not the hands Avoid using momentum or jerking the weight up Control the eccentric (lowering) phase rather than letting the weights drop', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'karthikrrk', 'https://wger.de/en/exercise/2669/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2670', 'alternate-walking-2670', 'Alternate Walking', '["calves","quads"]', '["none (bodyweight exercise)"]', '1m30s of walking (~4.5 km/h) to 30 s of jog (7 km/h) and repeat', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mamo2604', 'https://wger.de/en/exercise/2670/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2671', 'radio-taiso-2671', 'Radio Taiso', '["shoulders","lats","quads","abs","glutes","chest"]', '["none (bodyweight exercise)"]', 'Video can be found here : https://www.youtube.com/watch?v=SGPBSqxKGAc Full-body mobility and dynamic warm-up routine (3-5 minutes) to prepare joints, muscles, and the cardiovascular system for workout. Movement Flow: Deep Breathing & Arm Raises: Inhale while raising arms laterally overhead, exhale as you lower them. Knee Bends: Soft, rhythmic knee flexions synchronized with arm swings. Arm Circles: Large full-range arm rotations forward, then backward to open up the chest and shoulder girdle. Chest Expansion: Cross arms in front of the chest and open wide to the sides. Side Bends: Reach overhead to stretch the lateral torso left and right with a smooth side flexion. Forward & Back Bends: Gently hinge at the hips to reach forward, then return upright with a mild spinal extension. Torso Twists: Swing arms side-to-side to rotate the spine and loosen the core. Ankle Mobility / Light Bounces: Soft heel lifts or light bouncing on toes to warm up lower leg joints and tendons.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Mamo2604', 'https://wger.de/en/exercise/2671/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2672', 'kelso-shrugs-2672', 'kelso shrugs', '[]', '["barbell","bench"]', 'Kelso shrugs are a variation of scapular shrugs designed primarily to train scapular retraction , with particular emphasis on the middle trapezius, rhomboids, and, secondarily, the lower trapezius . Unlike conventional shrugs, the goal is not to elevate the shoulders toward the ears, but rather to pull the shoulder blades backward . They are typically performed with the chest supported on an incline bench, using either dumbbells or a barbell: Lie face down on an incline bench, with your arms extended toward the floor. Keep your elbows almost completely locked throughout the movement. Starting with the shoulder blades slightly protracted, retract them , trying to bring them closer together. Keep your chest firmly supported on the bench; avoid turning the movement into a row by extending your torso. Briefly hold the fully retracted position, then return in a controlled manner, allowing the shoulder blades to separate.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'Friend7857', 'https://wger.de/en/exercise/2672/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2673', 'stomach-vacuum-2673', 'Stomach Vacuum', '["abs"]', '["none (bodyweight exercise)"]', 'Starting position : Lie flat on your back with knees bent, feet flat on the floor (or stand/sit upright). Exhalation : Fully exhale all the air from your lungs through your mouth. Contraction : Draw your navel in towards your spine as far as possible, pulling your stomach inward and up under your ribcage. Hold : Hold this isometric contraction without breathing for 10 to 20 seconds. Release : Slowly inhale through your nose to release the tension and relax your abdominals. Repeat : Rest briefly and perform the desired number of sets.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'TimoteoG', 'https://wger.de/en/exercise/2673/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2674', 'knieheben-beinhebemaschine-2674', 'Knieheben Beinhebemaschine', '["abs"]', '["none (bodyweight exercise)"]', 'i cannot change the language in add exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'fen', 'https://wger.de/en/exercise/2674/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2675', 'knieheben-beinhebemaschine-seitlich-2675', 'Knieheben Beinhebemaschine seitlich', '["abs"]', '["none (bodyweight exercise)"]', 'i cannot change the language in add exercise', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'fen', 'https://wger.de/en/exercise/2675/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2676', 'weighted-neck-flexion-2676', 'Weighted neck flexion', '[]', '["bench"]', 'Weighted neck flexion is an isolation exercise designed to strengthen the anterior (front) neck flexor muscles by bringing your chin toward your chest against external resistance (most commonly a light weight plate, resistance band, or neck harness).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'qoxivi', 'https://wger.de/en/exercise/2676/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2677', 'single-leg-press-2677', 'Single leg press', '["hamstrings","calves","glutes","quads"]', '[]', 'Strength training exercise where you push a weight away from your body using one leg at a time on a leg press machine. It helps to improve leg strength, balance, and muscular symmetry by isolating each leg individually. This exercise is particularly useful for identifying and correcting muscle imbalances between your legs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'qoxivi', 'https://wger.de/en/exercise/2677/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2678', 'incline-row-rings-2678', 'Incline Row - Rings', '["shoulders","biceps","lats"]', '["none (bodyweight exercise)"]', 'Perform a row using gymnastic rings, but with the body position somewhere between vertical and horizontal. Go closer to horizontal to make it harder.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'wintercyan', 'https://wger.de/en/exercise/2678/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2679', 'tyson-push-ups-2679', 'Tyson push-ups', '[]', '[]', 'Starting Position • Feet: Place the soles of your feet flat against a vertical wall, with your toes or balls of your feet on the floor. • Hands: Position your hands on the floor shoulder-width apart, directly under your lower chest or solar plexus. • Body: Keep your core tight, glutes squeezed, and head in a neutral position. Your knees should hover a few inches above the floor without touching it. Movement Pattern Lower Down: Flex your elbows (tucked around 45 degrees) to lower your chest toward the floor, stopping just a few centimeters short of touching the ground. Rock Back: As you press upward through your arms, push your hips backward and bend your knees, rocking your weight toward your heels while keeping your shins nearly parallel to the floor. Drive Forward: Explode forward from your lower-body/crouched position, shifting your weight back into the starting push-up plank stance to complete the repetition. Key Tips for Proper Form • Keep Knees Low: Do not let your knees or hips pike high up in the air; keep the motion low and horizontal. • Maintain Wall Contact: Keep the soles of your feet pressed against the wall so you don''t lose your leverage. • Engage the Core: Avoid arching your lower back by tilting your pelvis backward and bracing your abs.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'yahoo.ivory', 'https://wger.de/en/exercise/2679/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2680', 'wrist-rocks-2680', 'Wrist rocks', '[]', '["none (bodyweight exercise)"]', 'Start on all fours with your palms flat on the floor. Slowly rock forward and backward, keeping your hands planted. Move only within a comfortable, pain-free wrist range to gently improve mobility and flexibility.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nalhilal', 'https://wger.de/en/exercise/2680/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2681', 'scapular-pushups-2681', 'Scapular Pushups', '[]', '["none (bodyweight exercise)"]', 'Start in a straight-arm plank with your hands under your shoulders. Keep your elbows locked and move only your shoulder blades: let your chest sink slightly, then push the floor away to spread the shoulder blades. Move in a comfortable, controlled range.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nalhilal', 'https://wger.de/en/exercise/2681/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2682', 'dumbbell-cyclist-squat-2682', 'Dumbbell cyclist squat', '["hamstrings","calves","quads"]', '["dumbbell"]', 'Dumbbell squats with elevated heel position. Stand on either squat wedges or weight plates to raise heels higher than toes, while holding the dumbbells on your sides.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JuustoKakku', 'https://wger.de/en/exercise/2682/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2683', 'dumbbell-single-arm-row-2683', 'Dumbbell single arm row', '["biceps","lats"]', '["bench","dumbbell"]', 'Place a dumbbell next to a flat bench Place your left knee on on the bench, and plant your left hand on the bench so it is under your shoulder. Place your right foot on the floor in line with your left knee Grab the dumbbell with your right hand, neutral grip. Starting position, shoulders should be in line and back paraller to the floor Slowly pull the dumbbell up, by pushing your elbow upwards, keeping it close to your body. Do repeats on one side, then on the other.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JuustoKakku', 'https://wger.de/en/exercise/2683/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2684', 'triceps-push-up-2684', 'Triceps push up', '["triceps"]', '["none (bodyweight exercise)"]', 'Push ups for targeting triceps. Start with a plank position with your hands directly below your shoulders, feet together. When descending, keep your elbows pinned to your sides. Upper arms straight back. Lower until your chest touches the floor, then return.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'JuustoKakku', 'https://wger.de/en/exercise/2684/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2685', 'cross-body-stretch-2685', 'Cross-Body Stretch', '["shoulders"]', '["none (bodyweight exercise)"]', 'Extend your right arm straight across your chest toward the left. Hook your left arm around your right elbow and pull your right arm a little closer to your body. Keep your shoulder down as you do this. Repeat on the other side.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2685/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2686', 'wrist-stretch-2686', 'Wrist Stretch', '[]', '["none (bodyweight exercise)"]', 'Extend your right arm straight out in front of you, with your palm facing up (fingers pointing toward the floor). Using your left hand, gently pull the fingers of your right hand toward you until you feel a stretch in your forearm and biceps.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2686/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2687', 'quadriceps-stretch-2687', 'Quadriceps Stretch', '["quads"]', '["none (bodyweight exercise)"]', 'Stand on one leg (hold onto a wall if necessary). Use your hand to grasp the ankle of your other leg and gently pull your heel toward your buttocks. Make sure your knees stay close together and that you push your pelvis slightly forward (avoid arching your back).', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2687/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2688', 'hamstring-stretch-2688', 'Hamstring Stretch', '[]', '["none (bodyweight exercise)"]', 'Sit on the floor. Extend your right leg straight out in front of you. Bend your left leg and place the sole of your left foot against the inner side of your right thigh (with your knee pointing to the side). Straighten your upper body completely (chest out, shoulders back). Inhale, and as you exhale, bend forward from the hips (not the lower back!) over your extended right leg. Reach for your shin, ankle, or foot-whichever is possible while keeping your back straight.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2688/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2689', 'v-up-mark-lauren-2689', 'V-Up - Mark Lauren', '["abs"]', '["none (bodyweight exercise)"]', 'One of the best exercises for the rectus abdominis muscles. Lie on your back with your legs straight and your arms close to your sides. Lift your head off the floor and raise your legs and arms about 15 centimeters off the floor. Your palms should face down, and look up at the ceiling. Now bend your legs and at the same time sit up so that your knees and chest almost touch. Only your buttocks are still on the floor. Your arms are now extended at shoulder height. Then slowly return to the starting position with your arms and legs extended and your head raised.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2689/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2690', 'active-hang-2690', 'Active Hang', '["lats"]', '["pull-up bar"]', 'A static hold from a pull-up bar with straight elbows and actively depressed, stabilized shoulders. Grip a secure bar and let your body hang under control. Keep your elbows straight and gently draw your shoulders down, away from your ears. Maintain this active shoulder position without pulling up, swinging, or repeatedly moving the shoulder blades. Hold for up to 30 seconds. Stop earlier if your grip opens, shoulder control deteriorates, or pain occurs. Record actual seconds, grip, and any assistance used. This is distinct from a relaxed passive dead hang or a moving scapular pull-up.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nalhilal', 'https://wger.de/en/exercise/2690/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2691', 'pike-hold-floor-2691', 'Pike Hold (Floor)', '["shoulders","abs","triceps"]', '["none (bodyweight exercise)"]', 'A static bodyweight support with both hands and feet on the floor and hips raised in a pike position. Place your hands and feet securely on the floor, then raise your hips. Keep your elbows straight and actively push the floor away through your shoulders. Maintain a controlled, stationary position without bending your elbows, lowering your head for push-up repetitions, or raising your feet onto a surface. Hold for up to 30 seconds. Stop earlier for loss of alignment, loss of active shoulder support, or pain. Record actual seconds, hand and foot spacing, and alignment. This is the floor variation, not a pike push-up or an elevated-feet pike hold.', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', 'nalhilal', 'https://wger.de/en/exercise/2691/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2692', 'exhale-and-body-position-swim-drill-2692', 'Exhale and Body-position Swim Drill', '[]', '[]', 'Swim one short pool length at a gentle pace while focusing on a relaxed body position and a steady exhale into the water between breaths. Pause at the wall between lengths. This is a moving swim technique drill, not stationary bobbing or a kickboard-only exercise.', '2026-10-28T22:02:36.153Z', 'CC0', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2692/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2693', 'shoulder-flexion-wall-stretch-2693', 'Shoulder Flexion Wall Stretch', '[]', '[]', 'Place both hands against a wall above shoulder height. Step back and gently move the chest downward while reaching the arms overhead, keeping the back controlled. Hold a comfortable shoulder flexion stretch without forcing the range or arching the lower back.', '2026-10-28T22:02:36.153Z', 'CC0', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2693/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2694', 'feet-assisted-straight-bar-support-2694', 'Feet-assisted Straight-bar Support', '[]', '[]', 'Hold a stable straight bar in front of the hips with both arms straight. Keep both feet on the floor or a stable platform so they assist your body weight. Maintain steady shoulders and a controlled supported position without swinging. This is a feet-assisted straight-bar support hold, not a ring hold or a full dip.', '2026-10-28T22:02:36.153Z', 'CC0', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2694/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2695', 'controlled-brisk-swim-2695', 'Controlled Brisk Swim', '[]', '[]', 'Swim a short pool length at a controlled brisk effort, maintaining smooth strokes and steady breathing. Stop at the wall for the prescribed recovery before the next repeat. This is a submaximal swim interval, not an all-out sprint; distance, repeats and rest are set by the routine.', '2026-10-28T22:02:36.153Z', 'CC0', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2695/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2696', 'supported-deep-squat-hold-2696', 'Supported Deep Squat Hold', '[]', '[]', 'Hold a stable support in front of you and lower into a comfortable deep squat with both feet grounded. Use the support for balance and to control depth. Maintain the squat hold without bouncing or forcing the hips or ankles farther than a comfortable range.', '2026-10-28T22:02:36.153Z', 'CC0', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2696/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2697', 'biceps-2697', 'biceps', '["hamstrings"]', '["resistance band"]', 'thats good you have to text you know for good haha', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '4', 'https://wger.de/en/exercise/2697/view/');
INSERT OR REPLACE INTO exercises (id, slug, name, muscles, equipment, instructions, createdAt, licence, author, sourceUrl) VALUES ('wger-2698', 'biceps-curl-2698', 'Biceps Curl', '["biceps"]', '["dumbbell"]', 'biceps curl for biceps to grow your arm and to have a good physique', '2026-10-28T22:02:36.153Z', 'CC-BY-SA 4', '2', 'https://wger.de/en/exercise/2698/view/');
